INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p495546-math001', 'stk-user4620', 'MATH 001', 'info', '{"desc": "الكلاس تيست هو تقريبا زي الكوز ولكن يحتوي دروس اكثر ودرجات اكثر يعني تقدر تقول\nكل كلاس تيست = 3 كوزات تقريبا\nتقريبا دروس المطلوبه نفس دروس المياجر (حسب المدرس)\nوقد يكون مره بالترم او اكثر (حسب المدرس)\nوعادة يكون قبل المياجر والفاينل (تجربة = test )\nانا عن نفسي بماث 001 اعلى درجة جبتها بالكوزات امكن 3 من 10 وقلت الله يعين\nوكان عندنا كلاس تيست واحد اخر السنة جبت فيه 54 من 60 اعطاني المدرس تقريبا فل مارك بالكلاس وورك\nفركز على الكلاس تيست تراه مهم وايضا سهل لانه قبل الميجر يعني تكون دارس مضبوط…وادعيلي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/class-test/80284/2", "user": "user4620", "ts": 1258831296000, "tid": 80284, "pn": 2}}', 1258831296000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p64216-math001', 'stk-user6', 'MATH 001', 'info', '{"desc": "وعليكم السلام و رحمة الله و بركاته\n\nأخي الفاضل نصيحتي لكل أوريا إنه يحل أسئلة العصار 001 و إنه يبذل عليها أكبر جهد.\n\nالأوريا جاي من الثانوية العامة و ما أدراك ما الثانوية العامة، ده في ده وناخد اشارة ده و نحطه هنا و السلام. بصراحة هذي نظرتي و هذا اللي أنا شايفه من طالب الثانوية. و المتوقع من المهندس أكبر من كذا بكثير لا بد يكون فهمه متعمق و مهارته عالية.\n\nإذا كان طموحك له علاقة بالهندسة فأنصحك إنك تحل أسئلة العصار و تكثر منها هي موجودة بمركز النسخ و التصوير بالجمعية. لأن المهارات اللي تتعلمها بالأوريا هي الأساس للدراسة الجامعية الهندسية راح تواجه في الجبل أربع كورسات ماث على الأقل و كورسين فيزياء و باقي المواد العلمية معتمد بشكل أو بآخر على ها المواد. أسئلة العصار تحتوي أفكار غريبة لكنها مفيدة تبين طرق عديدة لحل المسائل، بعبارة أوضح تفتح مخك. راح تستفيد من عملية تفتيح المخ هذي بعدين في الكورسات اللي ذكرت و غيرها. لا تهتم للقريد اللي ممكن تطلع به من الأوريا طالما تقدر تدخل الهندسة أهم شي تكون فاهم لأن مواد الجبل معتمدة على دراسة الأوريا و حترتاح كثير إذا طلعت للجبل فاهم.\n\nأما طلاب الإدارة فما أقدر أفيدهم لأني ما أدري عن تخصصاتهم.\n\nلكن طعني و حل أسئلة العصار لأني أعرف طلاب تخصصوا في الهندسة ماكانت أساساتهم قوية في الماث و تعبوا كثير في الفيزياء و الماث.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/42506/2", "user": "user6", "ts": 1100970063000, "tid": 42506, "pn": 2}}', 1100970063000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p64247-math001', 'stk-user1039', 'MATH 001', 'info', '{"desc": "اخوي فالكون …🙂\n\nياهلا وغلا حبيبي…🙂\n\nكلامك جدا رائع …🙂\n\nراجع الخاص …🙂\n\nكوول مان…\nياميت اهلين وسهلين 😃\nوالله ناسي ايام الثانوي …ومغير فكرتي عن الجامعة … والمذاكرة شبه يومية … وشاد حيلي… بس طريقة اسئلة الاختبار هي اللي صدمتني …!! اذا عندك نصايح … تراي استقبل …:)ومانستغني عنك حبيبي …🙂\n\nالفتى الذي اتسع …\nههههههه حلوة … 😃\nوالله قبل شوي طلعت نوت العصار … ناوي اعصر النوت عصر من جد 😃", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/42506/7", "user": "user1039", "ts": 1101030027000, "tid": 42506, "pn": 7}}', 1101030027000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437472-math001', 'stk-triixer1', 'MATH 001', 'info', '{"desc": "عزيزي ابو خالد انا دكتوري ممتاز وما راح يقصر في درجة وحدة لكن اللي اقصده اني هل فيه امكانية ان الدكتور يغيره بعد ما تم وضع القريد وكل شيء اللي يغبن اني ما كان باقي لي في النجاح الفاينل الا 13 واستهنت فيه بزادة وجبت 12 هذا اللي قاهرني فعلا والا المياجر عندي جيدة والكويزات مب شينة لكن قدر الله وما شاء فعل وان شاء الله انها خيرة + لو اروح له متى اروح له.\n\nوبالنسبة للصيف انا ناوي اخذ صيف ان شاء الله ع اي حال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/171412/3", "user": "TriiXeR1", "ts": 1451486821000, "tid": 171412, "pn": 3}}', 1451486821000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p421172-math001', 'stk-user5156', 'MATH 001', 'info', '{"desc": "بسم الله الرحمن الرحيم\nشباب أنا كنت عايد الماث 001 بتقدير f بسبب إهمالي وبعدين طلعلي الترم هذا d+ ولكن والله تعبت على هالدرجة بشكل غير طبيعي\n\nوالمشكلة أنه المدرس أعطانا الكلاس ورك على حسب مزاجه وليس على حسب الهومورك ولا الحضور ولا الكويزات\n\nوغير عن كذا عندنا كم واحد ناجح وهم ما يحضرون يعني dn\n\nوالله يا شباب إني مظلوم بالكلاس ورك ويوم كلمت الدكتور العساف قالي أنه أرسل الدرجات لمسجل الجامعة ولا عاد يقدر يسوي شي\n\nتكفوون والله أني مظلوم كل اللي أبغاه أنهم يعيدون توزيع الكلاس ورك بطريقة نظامية وبعد ما يعطيون أصحاب الغيابات dn وأظن أنه هذا من حق الجامعة ومن حقي\n\nوش الحل يا شباب والله إني في الجامعة أنتظر على أحر من الجمر نتحل هالمشكلة ؟؟؟\n\nتكفوون يا شباب الفزعة علموني وش أسوي؟", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/082-091/70885/412", "user": "user5156", "ts": 1246089012000, "tid": 70885, "pn": 412}}', 1246089012000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p721857-math001', 'stk-silent-180', 'MATH 001', 'info', '{"desc": "^\nالـ R.4 هذه من جد كارثة، بالكاد فهمت شيء منها، لكن الدروس الجاية أغلبها يعتمد عليها؛ لأن التحليل شيء أساسي بالرياضيات.\n\nلهذا أفضل شيء تقعد تحاول تحل واجب الأونلاين لها، شوف الأمثلة المحلولة وطبق طريقة الحل على أسئلة الواجب، بتشوف إنك بدأت تستوعب الفكرة أكثر، وبعدها اقرأ الشرح بالكتاب وحل الأسئلة كلها، وإن شاء الله سهالات.\nولا تنسى تذاكر نوت المدرس، أنصحك بنوت ناجي إبراهيم، لكن انتبه أحيانا فيها هفوات بسيطة، لكنها جدا ممتازة وتغطي أفكار وخدع كثيرة.\n\nوبما أن الجاي يعتمد على الـ R4 فأفكارها بتتكرر كثير وإن شاء الله بتفهمها، وادعيلي أفهمها أنا بعد D:\n\nأما واحب الأونلاين R5 فيقولون إنها تختلف من واحد لثاني، وعموما الـR5 سهلة وما فيها إلا 3-4 أفكار بسيطة تتكرر دائما. ما هي معقدة مثل الـ R4، والأمثلة الي بالأونلاين توضح لك طريقة الحل، فكل الي عليك هو إنك تبدل الأرقام والمتغيرات في الأمثلة بالي عندي وتحل، وتنتبه إذا طلع الجواب Pime أو إذا طلب التبسيط أو ما شابه. بالتوفيق 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math001/96113/47", "user": "Silent-180", "ts": 1287154847000, "tid": 96113, "pn": 47}}', 1287154847000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1300888-math001', 'stk-user2352', 'MATH 001', 'info', '{"desc": "http://faculty.kfupm.edu.sa/math/alassar/Teaching/PY%20Math/book001.PDF\n\nhttp://faculty.kfupm.edu.sa/math/alassar/Teaching/PY%20Math/book002.PDF\n\nفي الملفين المرفقين مسائل أفكار لمن يرغب في الاستعداد المثالي لإختبار الماث 001 و002 من اعداد وتجميع برفوسور الماث الدكتور رجائي العصار\n\nوجميعها اختيار متعدد واغلبها تركات تحتاج لتفكير شوي وفهم ، حلك لك سيضمن لك بإذن الله قريد B على الأقل\n\nوانصحكم حلوها في قروبات وناقشوها مع مدرسيكم في حالة استصعب عليكم شيء منها\n\nوبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math001-002-final-exams-best-exercises/153493/1", "user": "user2352", "ts": 1386245393000, "tid": 153493, "pn": 1}}', 1386245393000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1468468-math001', 'stk-user8581', 'MATH 001', 'info', '{"desc": "وعليكم السلام\nرايي تسوي كذا ,\n1- حاول تركز مع الدكتور حتى لو سيئ لكن على الأقل تعرف وضعك , وين وصلتوا في الماتيريال متى الكويزات كيف راح يجيبها كل هالأشياء ممكن يقولها في الشرح .\n2- ذاكر من الكتاب , الكتاب شرحه ممتاز ومفصل ولغته بسيطة : حل الأمثلة الي فيها بيد لاتطالع الحل وتقول سهل ! إذا ماعجبك الكتاب عندك نوتة إبراهيم ناجي ممتازة\n3- إذا حسيت إنك فهمت الدرس , رح للأسئلة المحددة في السلاباس وحلها واذا حليت السؤال لكن واجهت صعوبة فيها , حل السؤال الي جنبه لأن غالبا ً يكون نفس فكرة :\nمثلا سؤال 50 وانت تحله حسيت صعب اذا حليته رح للسؤال الي بعده وهو 51 لأن بيكون بنفس الفكرة و هالشي عشان تدرب وتعرف وين أخطائك أو الاشياء الي تواجه فيها صعوبة وتنتبها لها قبل الكويزات والمياجر .\nتالي حل الريساتيشن لأن مستوى الأسئلة فيها اصعب وتبين إذا انت فاهم أو لا .\n4- إذا مافهمت شيئ عندك الأوفيس أور , تقدر تروح لأي دكتور ماث وهو يشرح لك بس رح للدكاترة المتعاونين مثلا إبراهيم ناجي , شرقاوي , أبوجيا … وهم ماراح يقصروا لكن حسسهم إنك حاولت في السؤال مثلا اكتب حلك الي مب متأكد منه في ورقة و رح لهم .\n5- في الكويزات اسئل الشباب الي خذوا مع الدكتور السنوات الماضية عن طبيعة الكويزات , ممكن تكون من الأولداقزام أو من اسئلة الكتاب , اذا كانت من الأولداقزام فحاول تذاكر الأولداقزام المرتب بالشباتر .\n\n6 - قبل المياجر على بإسبوع تدرب على الأولداقزام العادي , الي على موقع الماث .\n\n7- إذا فيه شيئ مافهمته , اليوتيوب مليان شروحات لمواضيع 001 + 002\n\nهذي القناة فيها شروحات تقريبا لكل كورسات الماث الي عليك بس اكتب اسم الدرس بالانجلش\npatrickJMT\n+\nعندك\nKhan Academy\n\nأهم شيئ عدل وضعك قبل الميجر , درجاتك في الكويزات والكلاس تيست راح تبين لك إذا انت فاهم أو لا\nواذا كانت درجاتك سيئة فيها اعرف إن طريقتك في المذاكرة خطأ ولازم تعدلها\n\nملفات للكورس بتفيدك كثير :\n\nmadridista on Twitter\nmadridista on Twitter\nmadridista on Twitter\n\nواسف طولت عليك بس حسيتك متوتر من الموضوع والي احب اقولك اياه : الاوريا سهلة بس تحتاج تنظم وقتك وتعرف كيف تذاكر كل كورس وأمورك بتكون في السليم\n\nالله يوفقك وفالك الـ A+ 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/176087/2", "user": "user8581", "ts": 1487271604000, "tid": 176087, "pn": 2}}', 1487271604000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p779134-math001', 'stk-no_zzzzzzz', 'MATH 001', 'info', '{"desc": "السلام عليكم\nاولا احب ابارك للي نجح ولي ما نجح يحاول مرة ثانية\nموضوعي غريب وعجيب في الماث001\nانا يدرسني ابوجيا وزي ما تعرفو انه من افضل المدرسين في الاوريا …\nانا حصلت على 14 في الميجر الاول … قلت لنفسي 14 درجة زينة خصوصا اني ما ذاكرة زين\nوقبل الميجر الثاني باسبوع بدات اذاكر للميجر الثاني وجبت فيه للاسف 13 اي تحت الافرج وقلت الحمد لله على كل حال بعد عندي الفاينل والكلاس ورك وقلت ان شاء الله باعدي 001\nاخر اسبوع عطاني درجة الكلاس ورك وهي 15 من 24 وافرج كلاسنا 16 والافرج العام لي الكلاس ورك لكل السكاشن 17 وشوي\nوقال لي ( ابوجيا ) باقي لك 18 درجة على النجاح وقلت الحمد لله في ناس باقي لها31 درجة وما زالت تحاول تعدي والامل موجود\nوبدأت اذاكر … اولد اقزام وغيره وحسست نفسي فاهم المنهج بشكل جيد وقال لي بعض الشباب ان الفاينل دائما ما يأتي سهل وهذا جعلني ارتاح\nالمهم … دخلت الاختبار وباقي لي 18 درجة يعني نصف الاسئلة\nوبدأت احل وصراحة واجهة صعوبة في بعض الاسئلة المهم خلص الاختبار وبعد 6 ايام جيت اشيك على الدرجة ولما شفتها … اصبت بصدمة قوية جدا جدا جدا جدا جدا جدا جدا جدا جدا جدا جدا جدا جبت في الفاينل 12 درجة فقط من 36 اي اقل من الميجر الاول 14 والثاني 13 والكلاس ورك 15 … وقال لي احد الزملاء الغير اعزاء اذا يدرسك ابوجيا و001 السهل جدا وما نجحت فكيف اذا 002 انا متأكد انك بتعيده مرتين وبتطلع من الجامعة… I am sad all the time\nماذا افعل يا قوم نصائح وارشادات…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/101833/1", "user": "NO_zzzzzzz", "ts": 1296413154000, "tid": 101833, "pn": 1}}', 1296413154000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1106978-math001', 'stk-e-asb', 'MATH 001', 'info', '{"desc": "بصراحة من احلى الاختبارات الي اختبارتها في حياتي … نظرا لكوني كنت جدا متخوف من الاخبار واموري كانت ملخبطة … في البداية كان عندي امل كبير اني اجيب درجة جدا حلوة … لكن مع الظروف الي صارت قبل الاختبارات … ابدا ما كانت تدل على شيء زي كذا ممكن يصير … صراحة جاني احباط نسبي … وكنت اتمنى اني اخرج من الاختبار بأقل الاضرار … كنت اتمنى انها تجي اجازة الحج عشان ازبط اموري … لاني اهملت في البداية … وانضغط جدا لمن بدأت فترة الاختبارات … طول فترة دراستي في البترول عمري ما جبت درجة ترضيني ومعظم الدرجات اقل من طموحي … … قبل الاختبار كنت اتوقع انو هذا الميجر ح يكون جزء من هذه السلسة … اختبرت اختبار تجريبي وجبت فيه 10 من 20 … وزاد الاحباط عندي وندمت وقتها على الاهمال لي صار من بداية السنة … كان الوقت بالنسبة ليا جدا ضيق خصوصا كان عندي اختبار ورك شوب يوم الاربعاء قبل الماث بيوم … اتوكلت على الله ودخلت الاختبار … وبدأت في حل الاسئلة … واثناء الحل تفجأت كثير بوجود اسئلة يمكن حلها بعدة ثواني … ما كنت متوقع بوجود اسئلة من هذي النوعية في مياجر البترول … اتوقع ان مثل تلك الاسئلة السهلة من المستحيل ان ارها في البترول ( انا اتكلم عن سؤالين او ثالثة كانت في متناول الجميع مثل ذلك السؤال الذي يطلب منا نخرج الكسر من الجذر الثالث له ) … وحمدلله خلصت كل اموري وتقريبا باقي على الوقت ربع ساعة وعلى الرغم من اني راجعت مراجعة خفيفة لكن استفدت في الربع الساعة المتبقية في المراجعة مرة اخرى … سلمت الورقة … وخرجت من الاختبار بفرحة غابت عني كثيررر … بصراحة ما اجمل الشعور عندما تجيب درجة جيدة في البترول … اعتقد انها الدرجة الجيدة في البترول تعطينا مؤشرات جدا جدا جيدة مقارنة بالثانوية … هناك عبارة تقول بداية الخير قطرة … لكن بالنسبة لحالتي اعتقد ان شاء الله بداية الخير غيمة … واي غنيمة … ميجر اكزام … يعني احلى غنيمة … وان شاء الله تكون بدايات الخيرات سواء لي او للجميع يارب\n\nحمدلله اخيررررا اول اختبار انصف الجهد الي ابذله … والفضل يعود لرب العالمين اولا واخيرا\n\nان شاء الله يكون هذا الميجر بداية خير لالي جابو درجات حلوه … ونهاية الاحزان الي جابو درجات سيئة … والله يوفق الجميع يارب … شدو حيلكم … ترى مافي شيء مستحيل … البترول يبغالها اجتهاد شويتين … وان شاء الله نقدر نسوي كل شيء … ونصيحيتي لالي جاب درجات سيئة او اي احد امورو ملخبطة او ضعيف في اللغة الانجليزي … انو يستغل اجازة الحج وما يضيعها في اشياء لا تفيد في شيء … نتعب في البداية وان شاء الله نرتاح بعدين … الله يوفق الجميع يارب\n\nمعليش على الاطالة … ومعليش لو ازعجتكم بقصتي … لكن حبيت اشاركم قصتي نتيجة لفرحة في داخلي … خصوصا بعد ظروف صعبة ونوع من اليأس والاحباط\n\nاشوفكم على خير\n\n:popcorn:\n\n😁\n\n😁2:", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/133493/34", "user": "e-asb", "ts": 1350008944000, "tid": 133493, "pn": 34}}', 1350008944000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1107055-math001', 'stk-akws-a7md', 'MATH 001', 'info', '{"desc": "غلطة حياتي اني ذاكرت الاولد اقزام … لو ذاكرت النوتس والريسايتيشن كان بالامكان افضل مما كان … الحمدلله على كل حال … اسئلة الاولد اقزام اصعب من اللي جات … سببت لي ازمة وخوف قبل الاختبار … والميجر كان سهل واخطائي كانت بسبب عدم مذاكرتي للريسايتيشن … كان يمديها فل مارك لكن قدر الله وما شاء فعل … نكبر ونتعلم 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/133493/38", "user": "akws-a7md", "ts": 1350038221000, "tid": 133493, "pn": 38}}', 1350038221000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1107151-math001', 'stk-user9327', 'MATH 001', 'info', '{"desc": "غلطة اني هلكت نفسي وما اديتها نو م 12 ساعة لانه ضاع علي يوم الخميس في النوم\nوغلط اني رحت الاختبار وانا خايف وسبب لي ربشة اني ما عرفة السؤال الاول مما اثر على الاجوبة الباقية وقعدت في السؤال الاول حوالي ربع ساعة مما اثر على باقي الاسئلة\nنصيحتي سؤال ما عرفته اتركه وارجع له بعدين\nلانه ادائك وانت رتاح وخلصت الاسئلة ويبقى لك الاسئلة الصعبة احسن من ادائك وانت ماتدري ويش الاسئلة الصعبة والسهلة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/133493/41", "user": "user9327", "ts": 1350050802000, "tid": 133493, "pn": 41}}', 1350050802000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p391430-math001', 'stk-bad_e', 'MATH 001', 'info', '{"desc": "انا استلمتها السمستر الأول\n\nو للحين مستلمها في السمستر هذا <<< للحين 001\n\nيقولون إنها من الجامعه علشان تبين لهم إنك فاهم بالماث بس ما عليها اي درجات داخله في الكورس\n\nبالنسبه لي السمستر اللي راح ما حليتها و للحين مني حالها\n\nلأن من إسمها إضافي = extra\n\nوانا يا دوبي الحق على الهومروكات الرسميه علشان احل الإضافيه\n\nبس اظن إن الدرجه تعتدم على المياجر و الفاينل و علاقتك مع المدرس في الكلاس و برا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/72324/5", "user": "BAD_E", "ts": 1239539747000, "tid": 72324, "pn": 5}}', 1239539747000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p733438-math001', 'stk-user7305', 'MATH 001', 'info', '{"desc": "الحمدلله كانت نتيجة مرضية …\nبـ فضل الله !\n\n/\n\nفي خاطري اقول كم شيء لعله يكون خير\nتابعت المنتدى في ايام ماضية و كان شوفت عين الجميع\nو يعني على ما قال … افرج الأخلاق كان نازل\nو المكان ما كان لايق بأغلب الرجال هنا .\n\nعموما الي بأقوله ان الناس قسمين\nقسم ضد التثبيط و آخر مثبط …\nو اي الطرفين لم يحترم وجهة نظر الآخر\n\nنكون واضحين و كل يقف في المكان الموجود فيه\nهل كان الميجر صعب ؟\n\nالميجر لا يمكن ان يكون سهل و قضية الأفريج انتم بها ادرى\nوزعت علينا الريزتيشنس و وصينا ان افهموا ما اعطيتم < بيتحمس 😆\nو الأولد اكزامز في المكتبات\n\nميجر متوسط + 5 اسئلة صعبة اعطى انطباع ان الميجر يميل لصعوبة\nو لكن فهم الريزتيشن و الاولد اكزامز كان كفيل بثلاث ارباع الأختبار\nو مستوى الميجر متوقع و الغالبية كانت تتوقع الأصعب\nنظير ما تلقيناه في الكويزات\n\nجميع الأساتذه كان مستوى كيوزاتهم اعلى من الميجر\nاو على الأقل مقارب له … و تحديداً\nانا اطلعت على كويزات خان و ناجي و عليميه و واحد تركي\nو بيرزاده وو الخ … كلها كان مستواها عالي\nلدرجة اني ما فكرت احلها او حتى افهمها قبل الميجر\nلأني لاحظت المياجر القديمة و وجود سؤالين او ثلاثة بالكثير\nليست صعبة او تعجيزية بقدر ما هي جديدة تماما على الطالب\nو تحتاج إلى فكرة من بنات افكار المختبر …\n\nالشاهد أن الكل كان يجب ان يكون مستعد لإختبار من هذا المستوى !\nهذا كلام يشهد الله اني اقوله حتى افيد و اكون صادق مع الجميع\n\n/\n\nاخيراً الجبل مليء بأمثلة لا اقول فشلت في ميجر\nبل اقول فشلت في النجاح ترمين متتاليين\nفي الجبل امثله تقسم ان الكسور و القسمة و ضرب الحدود\nكانت من الصعوبة بما كان …\n\nو في الأسبوع الماضي كانوا يدرسوننا\n\nذهبت 20 درجة و 10 درجات من الكلاس وورك\nو بقية 70 و الكورة في ملعبك !\n\n/\n\nالريستيشن حلها و افهمها اسبوع باسبوع\nو الكويزات حاول تجيب درجة مع مدرسك\nو لكن من وجهة نظري دكتور احمد الزعبي \" دكتوري\"\n^^ لا احد يحسبه كويس هذي حسنته الوحيده … لا شرح لا اخلاق ميييح 😆\nهو الوحيد الي كويزاته تفيد في الميجر\nلأن مستوااه قريب من الميجر\nاما البقية اصعب و اكثر تعقيد\n\n/\n\nافهم دروسك و الريستيشن\nحل كويزات الزعبي و المياجر القديمة\nو فالكم كسر الأفريج في الميجر الثاني\n\n/\n\nآسف على الإطاله\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/97848/27", "user": "user7305", "ts": 1289098303000, "tid": 97848, "pn": 27}}', 1289098303000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p257993-math001', 'stk-satellite_ise', 'MATH 001', 'info', '{"desc": "إذا كان مستواك في ماث001و002 +c ومافوق فأعتقد بإمكانك تبدع في ماث 101 في الصيفي بشرط المذاكرة المضاعفة من أول أسبوع لأنه سيكون عندك هناك كل يوم كلاس لكتشر وكل أسبوع كلاسين ريسيتيشن والكورس بشكل عام هو حساب التفاضل والإشتقاق وتطبيقاته اللي سبق لك دراستها في الثانوية العامة Calculus 1 وكمان لازم تبحث عن الدكتور الجيد الشريح إذا كان منزل صيفي هذا أولا\nوثانيا عندك خيارين من خبرتي إما تزل معها اسلامي أو عربي أو بي إي لكي ترفع ال Gpa\nوبالتوفيق ،،،،", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math101/62533/3", "user": "satellite_ISE", "ts": 1207323942000, "tid": 62533, "pn": 3}}', 1207323942000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p781518-math001', 'stk-user7158', 'MATH 001', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته\n\nالجهة المشرقة :\nانت كذا كانك معدي انجليش 001 و 002 وعايد ماث 001\nيعني أفضل بكثير من غيرك والحمد لله … غيرك عايد المادتين\nالماث 001 … سهل جداً جداً جداً فوق ما تتصور\nكل اللخبطه والصعوبة اللي في المنهج تكون في الأسئلة على r6 و r7\nاما بقية المواضيع فهي سهلة فوق ما تتصور …\nنصيحه : حمل نوت خان من هنا … لأنها تختصر لك الدروس وتعطيك الزبدة واسئلة قوية نسخة من اسئلة الاختبارات مع طريقة الحل … يعني باب في الكتاب تلقاه مشروح في 7 صفحات\nخان يعطيك هي في 3 صفحات … ويعطيك الزبد واساليب في الحل مع امثلة من الاولد اكزام\nالشي اللي انا تاكدت منه … هو انه باب كامل يشرحوه طول الاسبوع\nانت تقدر تذاكره من خان في يوم واحد … وتصير فاهم الموضوع وكل شي عنه …\nتقدر تخلي كلاس الماث ترفيه عن النفس او مراجعة … واصلا لانك فاهم\nبتصير متقدم على اللي معاك في الكلاس وتشارك كثير وشوف كيف بتصير نظرة المدرس لك !\nثاني شي … اشتري نوت أيمن … تلقاها في مكتبة الجمعية بـ 25 ريال\nهذي خليها للدروس اللي ما تفهمها من خان … وكذلك عشان وقت كلاس الماث شيلها معاك\nوذاكر منها وقت الكلاس الساعه … افتح النوته قدامك وتابع المدرس فين يوصل\nوانت ذاكر معاه من النوته وتفهم ان شاء الله\nانا عن نفسي استفدت منها في الابواب من بعد 2.2 الى نهاية الكتاب\nكنت اذاكر الباب من ايمن … وافهم الدرس كامل منه …\nواروح لخان اقراه من جديد … واخذ الامثله منه … لأن خان يحاكي لك الميجر …\nالكتاب … هذا ممتاز جداً … ولكن مشكلته يطول في الشرح ويعطيك أمثله سهلة …\nانا عن نفسي … ما استخدمه إلا اذا جاني درس مافهمته من خان ولا ايمن\nاستخدم الكتاب … وأركز مع الشرح وتوصلك صافيه بإذن الله\nوالاولد اكزام … مر عليه مرور الكرام … قرايه وشوف اذا شفت سؤال غريب او مسالة صعبه\nشوف طريقة حلها … واذا عندك وقت تقدر تتدرب عليه … لكن بشكل عام\nاذا انك مذاكر نوت خان … ما راح تلقى لك في الاولد اكزام إلا مسالة او مسالتين بالكثير اللي صعبه\n\nملاحظة أخيرة : ادري انك طوال الاسبوع بتسوف مثل ما صار معاي وغيرنا كثير من الطلاب\nبسبب طول الدوام + التعب …\nهذي لها حلين … جربتهم الثنين وكلهم مفيدين والحمد لله\nالأول : يا اما انك ترجع تنام الى الساعة 2 الليل ( تشبع نوم ) وتقوم تحل واجباتك وتذاكر وتتسلى بافلام والنت\nالى ان يبدا دوامك اليوم الثاني وترجع وتكرر نفس الطريقة .\nالثاني : خلي ايام الاسبوع لحل الواجبات فقط بدون مذاكرة والويكند … نام زي الناس\nوبتقوم مصحصح ان شاء الله … ذاكر الأبواب اللي اخذتوها الاسبوع اللي راح\nمذاكرة … كانك تذاكر لميجر … بالطرق اللي ذكرتها فوق\nوفالك الدرجة العالية ان شاء الله وترى ما بتاخذ الويكند كامل …\nيمديك تذاكر 4 ساعات وتاخذ لك بريك فلم … او تقلب في النت او اي شي\nوترجع وهكذا …\n\nنقطة أخيرة مهمة جداً …\nانا ما كنت اذاكر طوال السمستر … ادخل الكلاس مدري وش الطبخه\nبس قبل الميجر بـ 5 ايام\nاقسم المنهج على الخمس ايام … وافهمه بالطرق المذكورة بالاعلى\nوالحمد لله مافي ميجر من مياجر الماث جبت فيه اقل من 14\nوتمنيت لو اني مذاكر من قبلها وفاهم المنهج وبعدين قبل الميجر اخذت الـ 5 ايام مراجعة اكثر\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/101992/6", "user": "user7158", "ts": 1296840238000, "tid": 101992, "pn": 6}}', 1296840238000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p211553-math001', 'stk-user3269', 'MATH 001', 'info', '{"desc": "http://a11w.jeeran.com/alsalam.gif\n\nاول شي هذا جدول توزيع الدروس ومواعد الاختبارات\nhttp://www.kfupm.edu.sa/mathprep/pages/Math001/syllabus.htm\n\n=======\n\nمن هنا نزل حلول الـ Homeworks\nhttp://www.kfupm.edu.sa/mathprep/pages/Math001/homework.htm\n\n=======\n\nمن هنا نزل الـ Old exams\nhttp://www.kfupm.edu.sa/mathprep/pages/Math001/old_exams.htm\n\n=======\n\nمن هنا نزل الـ Recitation\nhttp://www.kfupm.edu.sa/mathprep/pages/Math001/Recitation.htm\n\n=======\n\nمن هنا نزل ترجمة كلمات Chapter P + أخطاء شائعة\nhttp://www.kfupm.edu.sa/mathprep/pages/Math001/resources.htm\n\n=======\n\nمن هنا تواريخ مهمه\nhttp://www.kfupm.edu.sa/mathprep/pages/others/important_dates.htm\n\n=======\n\nمن هنا جدول الـ office hours للمدرسين\nhttp://www.kfupm.edu.sa/mathprep/pages/faculty/office_hours.htm\n\n=======\n\nمن هنا جدول الكلاسات لجميع المدرسين\nhttp://www.kfupm.edu.sa/mathprep/pages/faculty/schedules.htm\n\n=======\n\nوبس هذا اللي عندي\n<<<<< ياقالك جايب شي جديد@4@\n\nع العموم ان شاء الله اكون فدتك شوي\n\nواذا تبي شغلات زيادة مر الجمعية\nهناك في نوتس لاكثر من مدرس\nوانا انصحك بنوت ايمن\nوبعد راح تلقى ترجمة لتشابتر 1 و 2\nوكم شغله حلووه بعد\n\nوبالتوفيق لنا ولك ان شاء الله@46@\nhttp://a33w.jeeran.com/smilies/107.gif", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/59220/2", "user": "user3269", "ts": 1192965651000, "tid": 59220, "pn": 2}}', 1192965651000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1027997-math001', 'stk-kudoes', 'MATH 001', 'info', '{"desc": "السلام عليكم …شوف يوم كنت اوريا عدت ماث 001 …والسمستر اللي بعده حاولت اجتهد وطلعت بالميجر الاول ب 15 من 20 طبعا … وبصراحة تحطمت لاني ذاكرت وتعبت لكن الحمدلله على كل حال …\nوجبت في الميجر الثاني 9 نفسك …لكن لاحظ مجموع مياجرك اعلى مني …المهم خذت 18 كلاس ورك …(حرصت اني ما اترك ولا واجب سواء اونلاين او بيبر ) …وذاكررت للفاينال عدل والحمدلله جبت اعتقد 30 او فوق …وطلعت بالمادة كلها ب b …انت ماشاء الله درجاتك مو سيئة بس هالله هالله في الكلاس ورك وبتضبط", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/124669/23", "user": "Kudoes", "ts": 1335293991000, "tid": 124669, "pn": 23}}', 1335293991000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1411288-math001', 'stk-user10282', 'MATH 001', 'info', '{"desc": "*\n\nوكّل الله يا رجال واهدأ 🙂\n\nالحمدلله ما دام أمورك ماشية تمام في باقي المواد ، أعطي الماث تركيز أكبر وحافظ على مستواك في الباقي ، ولا تيأس ولا تتحطم وتقول ما راح أفهم … المسألة مسألة جهد ووقت وتركيز. والجامعة ما حطت برنامج التحضيرية إلا أنها تبي تهيئ الطلاب للجامعة ، وأنا أضمن لك أن فيه طلاب أسوأ منك بكثييير ، على الأقل أنت ما شاء الله 02 وتفهم ، وش حال الي 00 وما يدرون ما الذي يدور حولهم ومتورطين في كل المواد.\n\nأنصحك توفّق بين الدروس الي تاخذها الحين + تستدرك الي فاتك ، والحمدلله الي فاتك ماهو شي صعب أبداً …\n\nبالنسبة لي التدرج الأنسب كالآتي (بدون نوتات ولا ملخصات ولا هم يحزنون):\n\n* ركّز في الكلاس وحاول تستوعب قد ما تقدر ، وإذا رجعت الغرفة راجع الي أخذته في نفس اليوم.\n\n- اقرأ أمثلة الكتاب ، إذا فهمتها حل المسائل الي يطلب منك حلها في آخر المثال.\n- روح للأونلاين هوموورك وحله.\n- إذا خلصت الدرس وحسيت أنك فاهم مضبوط ، حل الريسايتيشن ؛ إذا ما كانت عندك تلقاها في الموقع.\n- إذا حليت الريسايتيشن وفهمت المسائل ، هنا وضعك إن شاء الله في السليم، ويجي وقت الأولد إكزامز.\nطبعاً الأولد إكزامز الي منزلينها في الموقع مرتبة بالتدريج حسب الدروس ، فتقدر تلقى المسائل الخاصة بالدرس بسهولة. طبعاً مو لازم تضغط نفسك وتلتزم بحلها يومياً ، لكن خصص لها وقت قبل الميجر.\n\nوإذا صعب عليك شي لا تتردد بأنك تستغل الأوفيس آورز …\n\nتمنياتي لك بالتوفيق 🙂 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/167128/2", "user": "user10282", "ts": 1415712095000, "tid": 167128, "pn": 2}}', 1415712095000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1411531-math001', 'stk-senator', 'MATH 001', 'info', '{"desc": "درست عند نفس المدرس ، شرحه كويس لكن في الميجر الأول ذاكرت الكتآب فقط وحليت أغلب تمارينه وتفأجأت بنتيجة سيئة وأخذت 10 من 20 !\n\nأحد الطلآب نصحني وقال طنش الكتاب وذاكر أولد كزام فذاكرت الأولد اكزام للميجر الثاني والحمد لله أخذت 18\n\nنصيحتي ذاكر أولد اكزام ، ركز عليه كثير هو أهم شيء أهم من الكتآب ومن أي شيء ثاني لأن فكرة الأسئلة تكون منه ، صدقني لو بتجتهد للميجر الثاني وتذاكر من الأولد كزام راح تجيب درجة ترضيك …\n\nأنا الحمد لله ومن بعد ما بديت أذاكر الأولد كزام لكل ميجر دائم درجاتي فوق الأفرج بفآرق مريح …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/167128/3", "user": "Senator", "ts": 1415786085000, "tid": 167128, "pn": 3}}', 1415786085000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1411590-math001', 'stk-_20161', 'MATH 001', 'info', '{"desc": "ابدأ المذاكرة من الآن وشد\nلا تستعجل بالمذاكرة ذاكر درس درس ، مسألة مسألة\nعندك الآن حوالي 13 يوم عن كلاس تيست و بعدها بأسبوع الميجر\nيعني عندك وقت كافي على ما أظن\n\nايضاً لو تتابع مع التيشر وتكتب معاه أفضل\nذاكر النوتات و اللي كتبته و الامثلة\nوبعدها تدريجياً ابدأ بحل الاسئلة و الاسئلة\nو أنا أنصحك ما تكتفي بالمذاكرة العادية خاصة اذا كنت تريد درجة ممتازة\nاضغط على نفسك كل يوم و حل أمثلة الكتاب و ارجع لها مرة ثانية ايضاً\nو اذا ما فهمت مسألة اسأل أي أحد من فصلك أو الدكتور\nصدقني اذا اجتهدت و كرفت راح تحصل على درجة كويسة حتى في اسوء الظروف أضمن لك تجيب نصف الدرجة او اكثر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/167128/5", "user": "_20161", "ts": 1415797984000, "tid": 167128, "pn": 5}}', 1415797984000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1414958-math001', 'stk-ak-95', 'MATH 001', 'info', '{"desc": "حسب تجربتي ، الطريق نحو درجة كويسة في الميجر يمر برحلتين : 🤓\n\nأولا :\nبالنسبة لفهم الدرس :\n\nحاول تفهم من شرح المدرس في الكلاس ، إذا ما عرفت فقط اكتب اسم الدرس في اليوتيوب وبتطلع لك عشرات الشروحات ، اختر واحد وركز معاه …\n\nثانيا : حل المسائل :\n، وهي الخلطة السحرية في الرياضيات ، ثق تماما إنك كل ما تحل مسائل أكثر كل ما تتمكن أفضل ، الرياضيات مادة ( حل مسائل ) 👍\n\nوحل المسائل له طريقتين اختار أحدهما حسب الدرجة اللي تبيها ، - وأكيد تبي درجة عالية - :\n\n1- مرحلة درجة الأفرج أو حوله :\n\nوتكون من الدراسة من الكتاب فقط …\n\nالكتاب عنده ميزة رائعة جدا ، وهي التدرج في صعوبة الأسئلة ، تبدأ الأسئلة سهلة ثم تزداد صعوبة … قبلها إقرأ الأمثلة وافهم الطريقة ثم اتجه للأسئلة وحلها …\n\nطبعا ربما تكون الأسئلة كثيرة ، لذلك اكتفي مثلا بحل الأسئلة الفردية ( 1 ، 3 ، 5 ، … ) ، وحلولها موجودة في نهاية الكتاب …\n\n2- مرحلة فوق الأفرج أو الدرجة الممتازة ( 17 ، 18 ، 19 ، 20 ) :\n\nطبعا زي ما قالوا الشباب هي من الأولد اكزامز ، بعد ما تحل أسئلة الكتاب روح للاولد اكزامز ، الأولد اكزامز تعطيك أفكار كثييييرة وجديدة عن طريقة الأسئلة ، لا تتحطم لو ما عرفت تحل إلا كم سؤال في الأولد اكزام الأول ، كمل للي بعده واللي بعده بتلاحظ انك تحسنت …\n\nوهنا أشير لملاحظة مهمة :\n\nلما تحاول تحل سؤال الأولد اكزام وما تعرف ، لا تروح تشوف السلوشن على طول ، بل حاول فيه قدر المستطاع … لأنه مافيه فايدة انك مجرد تقرا السؤال وما تعرف ثم تنتقل للجواب مباشرة ، هاذي صارت مطالعة مو رياضيات … 😞\n\nوإذا انتقلت للجواب ، لا تقراه بس وتروح للي بعده ، بل حاول تحل السؤال مرة ثانية بنفسك حتى تتمكن من الطريقة ، برضو مافي فايدة من قراءة الجواب فقط ، ولا تخدع نفسك بأنك مجرد قرأت الطريقة إنك عرفتها ، لازم تحل عليها بنفسك … 👏\n\nبالنسبة للميجر القادم ، حاول تنظم المذاكرة في جدول - اكتبه - ، خلي هذا الجدول أو هاذي الخطة على مدى أسبوعين مو مشكلة ، مثلا يوم 19 بخلص 2.1 و2.2 ، يوم 20 مثلا عندي اختبار ثاني غير الماث بكون مشغول فيه ، لذلك بخلص 2.3 بس …\n\nطبعا اقتراحي ان هاذي المذاكرة تتم من الكتاب - حل أسئلة الكتاب أو الفردية فقط على الأقل - ، ثم خصص أخر يومين أو ثلاث أيام قبل الميجر لحل أولد اكزامز فقط …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/167128/10", "user": "AK-95", "ts": 1416816114000, "tid": 167128, "pn": 10}}', 1416816114000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p492491-math001', 'stk-soorf', 'MATH 001', 'info', '{"desc": "السلام عليكم ورحمة الله وبركااااته …\n\nاخبار الشباب واخبار طلاب السنه التحضيرية بكلية المجتمع …\n\nاول شي االصرااحه ماتوقعت الميجر بيكون كذا يعني انا ذاكرت وحليت امثلة الكتاااب وماقصرت بالنسبة للمذاكرة …\n\nلكن انصدمت يووووم شفت الاسئلة كذا يعني اسئلة ماشفتها من قبل وماتم شرحها في كلاس المااث لكن الشي الوحيد الي يربط بين الشرح والميجر هو الفكرة بس …\n\nيعني اذا جيت تحل مسألة لازم يكون عندك جميع الافكار الي في المسالة الواحدة يعني علشااان تقدر تحل وقت الميجر حتى لو اختلفت الاسئلة واختلف شكلهااا …\n\nثاااني شي الميجر الي راااح كان عليه 22 درجه من 100 واغلب الطلاب الي شفتهم بعد الميجر يقولون ما حلينا شي والي يقوول هذا وجهي اذا حولنا للجامعة والي يقوول ابسحب من الكلية وكلام واجد صار بعد هالميييجر …\n\nالسؤال الي ابي اقووله هل في امل الطلاب يجيبون c حتى لو انهم مابدعوا في الميجر هذا هل لهم فرصة يشدوون حيلهم ولا خلااص فاتهم القطااار …\n\n______________________________________________\n\nصااااحبكم : SOORF…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/80116/1", "user": "soorf", "ts": 1258154198000, "tid": 80116, "pn": 1}}', 1258154198000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1461091-math001', 'stk-user9306', 'MATH 001', 'info', '{"desc": "طبعا دائما ميجر 1 في ماث 001 يسبب صدمة لكثير من الطلاب( الاوريات ) ويجعلة يدخل في حديث نفسي وساوس وانه الجامعة صعبه عليه وانه مايقدر يكمل و إنه لو راح جامعة ثانية كان الوضع بيكون أحسن… ومن هالكلام لذلك انا اقولك انت كويس وممتاز ومتفوق ولا ماكان قبلتك الجامعة زي ذي من الاساس لذلك يجيب عليك تضبط طريقتك في المذاكرة فقط اتبع هذي الطريقة وبإذن الله ماراح تنزل عن B+\n\n1] إجعل تركيزك في الكلاس مو 100% خله 200% وركز في كل كلمة يقولها الدكتور بل في كل حرف وحاول تتابع خطوات الحل اول بأول ولا تجعل اي شيئ يفوت عليك.\n2] وبس ترجع البيت افتح الكتاب وارجع افهم الكونسبت الاساسيه وحل الامثلة علشان تتأكد انك فهمت تماماً.\n3] انتقل الى اسئلة الكتاب اللي نهاية الشابتر وحل الاسئلة الفردية وشيك حلك في مع الاجوبة اللي نهاية الكتاب وبكذا تكون تقريبا انهيت 67% من المذاكرة.\n4] الباقي عليك تروح تفتح الاولد اقزامز وتبدا من 152 و151 وانت نازل وخل القديمة بعدين اهم شي تحل اوبلد اقزامز جديدة علشان الافكار بتكون قريبة نوعا ما (مومثلها بس قريبة) .\n5] حل الريسايتيشن وبكذا تكون جاهز لأي سؤال مهما كان صعب .\n\nطبعا الخطة ذي تحتاج تعطيها وقت اول بأول وبالتوفيق\nطبعا ممكن البعض يقول الطريقة طويلة ,انا اقل اتبع الطريقة ذي وراح تدعيلي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math001-1/175155/2", "user": "user9306", "ts": 1477473354000, "tid": 175155, "pn": 2}}', 1477473354000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1461198-math001', 'stk-user10520', 'MATH 001', 'info', '{"desc": "here is the point\nالاختيارات المتعددة تلخبط وتخليك تجيب العيد جداً مع أنك فاهم جداً\nروّق في الاختبار،\nوابدأ بالأسهلة السهلة،\nوانتبه للاشارات (وضح حلك وخطك عشان تقدر تراجعه في آخر الاختبار بسهولة وتتأكد من الاشارات)\n\nوان شاء الله ما تغلط مثل هذي الأغلاط في الاختبارات الجاية…\nالميجر الثاني يمديك على ال20 يا وحش ، والفاينل 36 …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math001-1/175155/11", "user": "user10520", "ts": 1477593222000, "tid": 175155, "pn": 11}}', 1477593222000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p739678-math001', 'stk-user5900', 'MATH 001', 'info', '{"desc": "والله شووووف بما أن خبرتي في ماث 001 وخصوصاً مع الشرقاوي\nكبيرة على النحو التالي …\n1- أهتم في الهومورك وحل كل الهوموركات …\n2- الكلاس تيست والكويزات … تحاول تضبط فيها …\n3- حل أسئلة الأود نمبر في الكتاب وأعطها أياه في المكتب ( عشان يعرف أنك مهتم )\n\nوصدقني أعرف ناس كثير يستحقون 17 و 18 أعطاهم فُل مارك في الكلاس وورك لأنهم مهتمين معاه\n\nتحياتي …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/98751/2", "user": "user5900", "ts": 1290872961000, "tid": 98751, "pn": 2}}', 1290872961000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1321228-math001', 'stk-medoalkebsi', 'MATH 001', 'info', '{"desc": "وعليكم السلام ورحمه الله وبركاته.\n\nاخوي الغالي ,\n\nانت تعرف قدراتك اكثر من اي شخص ثاني . وانت تعرف مستواك في الماث 001 .\n\nاذا كان ادائك كويس في ماث 001 وماتعبت فيها كثير , اشوف انه كويس تنزل كمستري 101 + اسلامي 111.\n\nالكمستري من وجهت نظري اسهل من الماث , سهله جدآ اذا تابتعتها يوميا وماتتركها تتراكم عليك…و السلامي 111 هو كورس \" اولد اقزامز\" تحفظهم تاخذ a+ .\n\nاما اذا كنت ضعيف بالماث 001 , انصحك انك تنزل اسلامي + عربي , او اسلامي + انجليزي 101 . انجليزي 101 سهله جدآ مماثله للاوريا ,لكن العيب هو في المدرسين , قريدات دايم طايحه…فإذا تبي تبدع في انجليزي 101 وتجيب قريد , لازم تهتم فيها شوي + تكون صديق الدكتور بالمكتب…تخليه يحفظك وتحسسه انك مهتم وراح تجيب قريد كويس ان شاء الله.\n\nونصحيه اخيره , لاتسيب نفسك فاضي , الواحد اذا خلص الانجليزي يبقى فاضي ماعنده شي واكثر الشباب الي اعرفهم الفضاويه هذي انعكست عليهم سلبيا في الدراسه.\n\nوبالتوفيق … ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/155596/10", "user": "Medoalkebsi", "ts": 1390340277000, "tid": 155596, "pn": 10}}', 1390340277000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1434945-math001', 'stk-abdullah-1', 'MATH 001', 'info', '{"desc": "والله العظيم يمدييييييييييييييييييييييييك\nبس لا تحط في راسك انها صعبة\nذاكر من الكتاب (إذا الانجليزي عندك كويس)\nأو عندك النوتات واليوتيوب … وحل اكبر عدد ممكن من الأسئلة\nانشب للدكتور فالاوفيس اورر واسأله عن كل شيء\n\nلكن بإذن الله راح اعيده وابدا اشد حيلي من اول كلاس\n\nهذا الكلام لا يودي ولا يجيب\nشد حييييلك الحين\n\nياخي حتى لو ما عديت على الاقل سويت اللي عليك وطلعت بـ d+ مهوب f\nالحيين اشتغل على الــ c+ … بالتوووفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math001/171031/9", "user": "abdullah-1", "ts": 1448863434000, "tid": 171031, "pn": 9}}', 1448863434000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p735224-math001', 'stk-omar.a', 'MATH 001', 'info', '{"desc": "حبيبي بهاء … انا انقل لك تجربة اوريوية عشتها في 091\n\nMath001 major1 9 out of 22 … طبعاً هذاك اليوم ما نمت وقعدت اسبوعين مصدوم نفسياً\n\nوياريت كان في أحد يشجعني … حتى مدرسي قال املك في النجاح ضئيل اذا واصلت على نفس المستوى…\n\nطبعاً كان اول احتبار لي في الجامعة وبالتحديد في المصلخ الجميل (B-54) >> خوف وقلق ونعاس … الخ\n\nمن بعدها قررت اني أجيب Major 2 & The Final …+ A\n\nاستعديت لميجر 2 من قبل الميجر باسبوعين … وجبت 19/22 مع ان الاختبار كان صعب على كلام الطلاب\n\nلكن انا شفته موية وسهل وتافه واغلاطي كانت في الاشارات … الفاينل استعديت له بقوة وباجتهاد اكثر من\n\nالمجير الثاني … وجبت 34 من 36 واغلاطي كانت في الاشارات برضوا … والكلاس وورك 20 من 20\n\nفصار المجموع 9 + 19 + 34 + 20 = 82 يعني B وكان باقيلي على B+ درجتين بس\n\nيعني مهما كان قريدك سئء صدقني في فرصة للتعويض … ودائماً خليك واثق من نفسك\n\nفي الجامعة خذها مني نصيحة ( لا تسمع كلام احد أياً كان ) الاشاعات عن الاختبارات والصعوبة\n\nكلها كلام فاضي … انت اذا اجتهدت فصدقني حتصير اونر … انا على فكرة كنت اونر في كل من 091 &092\n\nيعني يمديك على الاونر اذا شديت حيلك … وماث 001 ترا مرررررررررة تافه صدقني اعتمد على الكتاب\n\nالاختبار ما راح يطلع من الكتاب وعادة يكون من الاكزامبلز المحلولة … واحياناً يكون في اسئلة من الريسايتيشن\n\nوسؤال من افكار اولد اقزامز … لكن تقدر على قريد عالي من الحين … والخطة كالتالي\n\n* Odd numbers of the textbook حلها كلها بلا استثناء … لا تخلي شي منها ولا تشوف الحل الا بعد ما تخلص\n\n* The Examples of the text book\n\n* ـ Homework questions حلها بتمعن وتركيز\n\n* Recitation Questions\n\n* وآآآآآآآآآآآخر شي Old Exams لا تعتمد عليها كثير لكن خليها آخر شي وحل الافكار الجديدة اللي فيها\n\nيعني طقطق عليها\n\nانا الآن Freshman ولله الحمد … وعديت الاوريا بنهاية 092 بسلام مع مرتبة الشرف\n\nلا تسمع كلام المحبطين والمخذلين … اعتمد على نفسك وخلي هدفك وطموحك عالى واسأل الله التوفيق\n\nوصدقني … الكارثة هي انك تستسلم وتصاب بالكسل …\n\nولا تظن ان الطريق الى الجبل مفروش بالورود … لازم تشد حيلك حتى تطلع الجبل على خير بإذن الله\n\nتمنياتي لجميع احبابنا الاوريات بالتوفيق …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/98032/6", "user": "Omar.a", "ts": 1289417195000, "tid": 98032, "pn": 6}}', 1289417195000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1306388-math001', 'stk-user7950', 'MATH 001', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nامتدادا لملفات الاكسل المفيده 🥰 ~\nجبت لكم ملف بسيط وهو فقط بدايه لمشروع كبير ان شاء الله بعد الفاينل .\nهذا الملف يحسب مجموعك والقريد تبعك وهل انت ناجح او عائد للماده . 🌹 ❤️ 🥰\n\nالملف ~\n\nhttps://www.dropbox.com/s/mov3eyzksma2j42/Math%20Cal..xlsx\n\nوانتظرني ي عمر 🥰 ❤️ 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-001/153990/1", "user": "user7950", "ts": 1387297667000, "tid": 153990, "pn": 1}}', 1387297667000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p483428-math001', 'stk-yasar', 'MATH 001', 'info', '{"desc": "يا اخوان اللينكات التالية فيها نوت الدكتور خان للماث 001 و 002\n\nونصيحة مجرب\n\nمن افضل النوتس اللي بتمر عليك ولو عنك شك اسأل\n\nمفيدة جدا\n\nوطبعا كل تشابتر في لينك لحاله لاني اعلم انو الكثيرين بيحتاجوها قبل الميجر او الفاينل وما بيكون في وقت للتحميل الطويل فلما تكون موزعة بتكون اخف و اسرع\n\nاللينكات\n\nhttp://www.ziddu.com/download/7134706/2.22.pdf.html\n\nhttp://www.ziddu.com/download/7134707/1.3.pdf.html\n\nhttp://www.ziddu.com/download/7134708/1.1.pdf.html\n\nhttp://www.ziddu.com/download/7134709/1.5.pdf.html\n\nhttp://www.ziddu.com/download/7134710/1.2.pdf.html\n\nhttp://www.ziddu.com/download/7134711/2.1.pdf.html\n\nhttp://www.ziddu.com/download/7134712/2.1...pdf.html\n\nhttp://www.ziddu.com/download/7134713/1.4.pdf.html\n\nhttp://www.ziddu.com/download/7134714/2.1graphs.pdf.html\n\nhttp://www.ziddu.com/download/7134715/2.21.pdf.html\n\nhttp://www.ziddu.com/download/7134735/2.5a.pdf.html\n\nhttp://www.ziddu.com/download/7134736/2.4.pdf.html\n\nhttp://www.ziddu.com/download/7134737/3.2.pdf.html\n\nhttp://www.ziddu.com/download/7134738/2.6.pdf.html\n\nhttp://www.ziddu.com/download/7134739/2.52.pdf.html\n\nhttp://www.ziddu.com/download/7134740/2.3.pdf.html\n\nhttp://www.ziddu.com/download/7134741/2.2a.pdf.html\n\nhttp://www.ziddu.com/download/7134742/2.5b.pdf.html\n\nhttp://www.ziddu.com/download/7134743/3.1.pdf.html\n\nhttp://www.ziddu.com/download/7134744/2.2b.pdf.html\n\nhttp://www.ziddu.com/download/7134752/4.3LogarithmicFunctions.pdf.html\n\nhttp://www.ziddu.com/download/7134753/4.1b.pdf.html\n\nhttp://www.ziddu.com/download/7134754/4.1a.pdf.html\n\nhttp://www.ziddu.com/download/7134755/3.5.pdf.html\n\nhttp://www.ziddu.com/download/7134756/4.2ExponentialFunctions.pdf.html\n\nhttp://www.ziddu.com/download/7134757/4.11.pdf.html\n\nhttp://www.ziddu.com/download/7134758/3.2.pdf.html\n\nhttp://www.ziddu.com/download/7134759/3.4.pdf.html\n\nhttp://www.ziddu.com/download/7134760/4.12.pdf.html\n\nhttp://www.ziddu.com/download/7134761/3.3.pdf.html\n\nhttp://www.ziddu.com/download/7135163/6.1VerificationofTrigonometricIdentities.pdf.html\n\nhttp://www.ziddu.com/download/7135164/4.5ExponentialandLogarithmicEquations.pdf.html\n\nhttp://www.ziddu.com/download/7135165/4.4PropertiesofLogarithms.pdf.html\n\nhttp://www.ziddu.com/download/7135166/5.4TrigonometricFunctionsofRealNumbers.pdf.html\n\nhttp://www.ziddu.com/download/7135167/5.7GraphingTechniques.pdf.html\n\nhttp://www.ziddu.com/download/7135168/5.6GraphsofOtherTrigonometricFunctions.doc.html\n\nhttp://www.ziddu.com/download/7135169/5.1AnglesandArcs_2.pdf.html\n\nhttp://www.ziddu.com/download/7135170/5.2RightTriangleTrigonometry_4.pdf.html\n\nhttp://www.ziddu.com/download/7135171/5.5Slides.pdf.html\n\nhttp://www.ziddu.com/download/7135172/5.3TrigonometricFunctionsofAnyAngle_3.pdf.html\n\nhttp://www.ziddu.com/download/7135262/6.5InverseTrigonometricFunctions.doc.html\n\nhttp://www.ziddu.com/download/7135263/6.2SumDifferenceCofunctionIdentities.pdf.html\n\nhttp://www.ziddu.com/download/7135264/8.1Parabola.doc.html\n\nhttp://www.ziddu.com/download/7135265/9.1SystemsofLinearEquationsinTwoVariables.doc.html\n\nhttp://www.ziddu.com/download/7135266/8.2Ellipse.doc.html\n\nhttp://www.ziddu.com/download/7135267/8.3Hyperbola.doc.html\n\nhttp://www.ziddu.com/download/7135268/6.6TrigonometricEquations.doc.html\n\nhttp://www.ziddu.com/download/7135269/7.3Vectors.pdf.html\n\nhttp://www.ziddu.com/download/7135270/6.3DoubleandHalfAngleIdentities.pdf.html\n\nhttp://www.ziddu.com/download/7135271/6.4Functionsoftheform....pdf.html\n\nhttp://www.ziddu.com/download/7135307/3232077768.pdf.html\n\nhttp://www.ziddu.com/download/7135308/3232077769.pdf.html\n\nhttp://www.ziddu.com/download/7135309/10.4Determinants.pdf.html\n\nhttp://www.ziddu.com/download/7135310/10.2AlgebraofMatrices.doc.html\n\nhttp://www.ziddu.com/download/7135311/9.3NonlinearSystemsofEquations.doc.html\n\nhttp://www.ziddu.com/download/7135312/10.1GaussianElimination.pdf.html\n\nhttp://www.ziddu.com/download/7135313/10.3InverseofaMatrix.pdf.html", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/001-002/67084/21", "user": "Yasar", "ts": 1256855440000, "tid": 67084, "pn": 21}}', 1256855440000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p209389-math001', 'stk-_99_98', 'MATH 001', 'info', '{"desc": "يارجال … تتسلح ولا ماتتسلح …\n\nوصيتي لك اللي استفدتها من تجاربي السابقه … ( هذا اللي بيخربكم )\n\nماافكر بالاختبار … الين قبل الاختبار ب24 ساعه … اقفل علي الغرفه وأبدأ ( مو بمذاكرة الكتاب ) الا بأكل الكتاب صفحة صفحة … وباذن الله تجيب احلى درجه …\n\nبس معلومه صغيره … لو سويت حركتي ذي … صحيح راح تجيب درجه اكثر من الحلوه … بس اتحداك تذكر شئ بعد الاختبار … ليش ؟؟؟ انا نفسي ماادري …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/001-002/59047/13", "user": "_99_98", "ts": 1191939091000, "tid": 59047, "pn": 13}}', 1191939091000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1497518-math001', 'stk-anas_alghamdi', 'MATH 001', 'info', '{"desc": "اول شي ابدا ب مذاكرة الكتاب لا احد يقلك لا تذاكره من جد مفيد بعد ما تفهم الدرس وتحل تمارين الكتاب انتقل الى اسئلة الاولد اقزام حل اسئلة اخر خمس سنوات كل سنه في اختبارين ترم اول و ترم ثاني بعد ما تخلصه حل اسئلة الشرقاوي المسؤول عن قسم الرياضيات في الاوريا شخص جدا مهتم ب الطلاب ب يحط لكم اسئلة في البلاك بورد حله كله\nوكذا مهما صار ما راح تنزل عن B+ يعني شي مستحيل تنزل عن هذا القريد الا لو مذاكرتك تسليكيه !!\nشي جدا مهم بعد ما تخلص السؤال اذا حليته صح تمام بس لو غلط مو تروح للي بعده زي الاهبل !! لا افهم فكرة السؤال وحله ب يدك من جديد ب يفيدك جدا\nطبعا بيكون سهل تسويه لو ما عندك انجليش او مستواك عالي فيه بس لو عندك انجليش ودوامه لوحده بس 20 ساعة و حسيت ان وقتك ضيق ولا يمديك تخلص الكتاب معى اسئلة الاولد اقزام واسئلة الشرقاوي\nذاكر سلايدات الدكتور احمد مقبل سلايداته شامله وجيده جدا في شباب بعد ما ذاكروه اهي بس طلعو ب A+\nان شاء الله اكون افدتك بشي وبتوفيق ب اذن الله يا اوريا 👏", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-001/179898/2", "user": "Anas_ALGhamdi", "ts": 1533994097000, "tid": 179898, "pn": 2}}', 1533994097000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1484878-math001', 'stk-mr.a1', 'MATH 001', 'info', '{"desc": "وعليكم السلام\n\nما أدري هل ما فهمت كلامك وإلا أنت ما اعطيت معلومة كافية عن اللي صاير معك ، لكن أنت اجمع درجات مياجرك مع درجتك المتوقعة في الكويزات والكلاس تست والهومورك ، وشوف كم يطلع معك المجموع من ٦٤.\nاطرح مجموعك من ٦٠ وشوف كم تحتاج في الفاينل عشان تنجح ، الفاينل عليه ٣٦ درجة. إذا تحتاج ٣٦ درجة أو أقل فأقدر أقول لك أنه ما زالت عندك فرصة أنك تنجح\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-001/178334/2", "user": "Mr.A1", "ts": 1513866650000, "tid": 178334, "pn": 2}}', 1513866650000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p316811-math001', 'stk-jokerz', 'MATH 001', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nMATH 001\n\n-بسام العبسي : افضل دكتور مر علي في الجامعة إلى الآن , دكتور أخلاق و بشووش و شرحه زيين ( يشرح باسنخدام سلايدات على الكمبيوتر يعني ما تحتاج نوت بوك الا لو تبغى تسجل نوتس من عندك 😉 و السلايدات حقته تقدر تحملها من موقعه بعد ما يشرحها في الكلاس )\nأعطيه A+ و بقوووووووووووووووة 😆\n\n- دكتور Balarabe yushau : هذا الدكتور شرحه جبااااااااااااااااار , إنسان يحب الماث و يحب يدرسها\nو يخش جو مع الطلاب اللي يسألون و يروحون له الأوفيس أورز كويزااته تقريبا حول صعوبة الإختبارات يعني لو تحل زين في كويزاته تجييب درجة زيينة في الإختباراات ان شاء الله\nو بالنسبة للكلاس وورك يعطيك على قد شغلك بالضبط ما تزيد و لا تنقص حتى لو رحت الأوفيس أورز و قعدت تناقز فووق رااسه :d\nأعطيه A+هو بعد\n\n-حسام شرقاوي : دكتوور أخلاااااااااااااااق و دايم يبتسم و يمزح مع الطلاب و شرحه رهييييييييييييييييييييييييييييييييييييييب , يحط أسئلة على الWeb CT إذا داومت على حلها يعطيك زياده في الكلاس وورك . أعطييه A++\n\nPhysics\n\nدكتور ثامر العيثان ( اللي سأل عنه JUST 4 U) : هذا دكتور حبيب و يحب يحرك جو الحصه لأنه يدري ان الفيزياء تجيب الملل \\ النوم الكلااس وورك عنده تاخذ أكثر من حقك اذا أنت تشارك معه على خفييف و تسلم عليه برا الكلاس 🤣 أعطيه B+\n\nPE 001 & 002\n\n- كوكب ( هندي ) : هذا الدكتوور حق كمال أجسام أصلا يعني لو أخذت عنده WEight lifting فهو أكثر من جثد من ناحية الإفادة أما الكلاسات الباقية الله يعينك علييها :ninja:لأنه بيخلييك تسوي push ups قبل أي كلاس يدرسك فيه\n\n- mr.Adijumo: دكتور حبيب و شديد في نفس الوقت و يعطيك على قد جهدك عنده و الحضوور عنده مهم جدا\n\nو الانقلش أخذت بروموشن فما أقدر أفيدكم 😆 << مبسوط فيها يعني 🤣\n\nهذولي كل اللي أذكرهم و أتمنى إني أكون أفدت أحدهم أو ريحته من هم المدرس 😉\n\nو دمتم 😎 😆", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/54933/63", "user": "jokerz", "ts": 1223721148000, "tid": 54933, "pn": 63}}', 1223721148000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p908831-math001', 'stk-ahmadonline', 'MATH 001', 'info', '{"desc": "شوف اخوي نوته خان حلوا بعد مرا ، بس مدري احسس انه مصعبها شوي زياده عن اللزوم ، بس اذا ذاكرتها وفهمتها بعد ، بيكون شي حلو وبيكون فاهم الماده ، وبتجيب قريدات عاليه مرا\n\nومثل ما قلت بالاول والاخير كل واحد ورايه يمكن لو تشتري ايمن ما تعجبك مثل خان ، ويمكن العكس صحيح\n\nموفق لكل خير 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/112723/15", "user": "ahmadonline", "ts": 1317023201000, "tid": 112723, "pn": 15}}', 1317023201000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1256902-math001', 'stk-abo_yazeed6', 'MATH 001', 'info', '{"desc": "كيرماني\n\nحاول تعتمد على نفسك أكثر من اعتمادك عليه,أحد أخويائي أخذ عنده a بدون ما يعتمد عليه\n\nوالكورس سهل جدا لكن يحتاج منك متابعة وحل تمارين أول بأول خصوصا وأنه أول كورس ماث لك\n\nوالشيء الثاني شيء طبيعي يمرون عليك مدرسين سيئين ولهذا لازم تعتمد على نفسك ولا تعتقد أنه الدكتور بيشرح لك كل شيء ,هو بيعطيك الأساسيات ويحاول يبسط لك الدرس لكن تحتاج تتدرب على مسائل الكتاب الفردية +الاختبا رات القديمة عشان ما تواجه صعوبة في المياجر , خذها من واحد خلص خمس كورسات ماث\"والمدرسين كلهم من جنبها ما عدى واحد\",وأخذ قريدات طيبة فيهم كلهم\n\nكيرماني ما ظنتي له تقييم ,له سنتين ودايم الطلاب يسألون عنه وللأسف للحين ما نزلوا له تقييم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/148468/2", "user": "abo_yazeed6", "ts": 1377813758000, "tid": 148468, "pn": 2}}', 1377813758000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p784294-math001', 'stk-guest', 'MATH 001', 'info', '{"desc": "بحكم اني واحد من طلاب سورنسن في الماث 001\n\nاقولك حط في راسك حاجة وحدة وهي انك تعتمد على نفسك وحصته لا تتعب نفسك فيها\n\nالسمستر الماضي كان اول سمستر له في الجامعة\n\nالامثلة الا يشرحها = نفس امثلة الكتاب\nوكويزاته نفس الهومووركات\n\nلو شفته يمدحك لا تصدق حالك وتقول بيعطيك 24 ترى مايعرف احد والتحضير اغلب الكلاس غايب واحنا نحضر اخويانا … ومرده الكلاس وورك ماراح يعطيك اياه على جهدك في الصف او الاوفس اور لأنه مايعرف احد ولا يسأل عن اسم احد … كل الا عليك اشتغل صح وسلم الهومووركات اول باول وجيب كويس في الكوزات والكلاس تست وان شاء الله تلقى كويس … السمستر الاول بحكم انه كلاسنا افرجه ضعيف في المياجر قام يقحط علينا في الكلاس وورك … اعلى واحد عندنا عطاه 22 والا بعده 19 وانا واحد منهم الا عطاهم 19 … واهم حاجة انك تحضر الدرس قبل لا تحضر الكلاس لأنه بيقول شغلات بتخليك تتعقد وتحط في راسك انه المنهج صعب … عن نفسي كنت اروح الكلاس واحط راسي وانام واذا رجعت البيت مسكت الكتاب وقعدت اذاكر\n\nوحسب ماسألناه انه تخصصه ماهو ماث اصلا هو مهندس كهرباء … يعني مو متعمق في المنهج حاله حالك يقعد يحضر الدرس قبل لا يشرح واغلالالالالاطه عد واغلط في الشرح في الجمع والطرح والضرب والقسمة وفيه اشياء في الدرس مايدري عنها احيانا نقوله ويفتح الكتاب يشيك عليها\n\nانا مااحبطك او اخوفك بس الا ابغى ابينه لك انك تشد على نفسك مثل مانا سويت في السمستر الاول وفالك الـa+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/david-sorensen/102289/3", "user": "Guest", "ts": 1297193132000, "tid": 102289, "pn": 3}}', 1297193132000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1404350-math001', 'stk-user10207', 'MATH 001', 'info', '{"desc": "عندك الكتاب مهم جداً. ذاكر الدرس بهدوء وإستيعاب، وبعدها حل جميع التمارين سواء اسئلة الأرقام الفردية أو الزوجية، وبكذا تفهم الدرس بإذن الله.\n\nأنصحك بإستغلال أول ميجر وتفهم دروسه لأنها مهمة وراح تستعمل المفاهيم في دروس ميجر 2 والفاينل والكورس القادم 002. حاول تذاكر بشكل جيد علشان تكون مرتاح طوال الترم على الدرجات الطيبة الي حققتها.\n\nبالتوفيق لك ولجميع الطلاب.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/166027/5", "user": "user10207", "ts": 1412859224000, "tid": 166027, "pn": 5}}', 1412859224000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1080829-math001', 'stk-exuse_me', 'MATH 001', 'info', '{"desc": "وعليكم السلام …\n\nلا تشيل هم ، ماث 001 هو عباره عن : مصطلحات رياضيه فقط …\n\nيعني أصعب درس ب يمر عليك . تحصله ف كتاب الماث للمتوسط …\n\nانصحك تجيب كتاب \" تحصيل1\" لانها نفعني واجد ب الفيوياء والكيمياء … ، ل صعوبه المصطلحات خصوصاً ان مدرسنا كان اجنبي “امريكي” ولا ييجيد اللغه العربيه …\n\nوشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math/130199/10", "user": "Exuse_Me", "ts": 1345696148000, "tid": 130199, "pn": 10}}', 1345696148000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1404355-math001', 'stk-_11101', 'MATH 001', 'info', '{"desc": "السلام عليكم\nاخوي ترا عادي جدا’ تحس انك فاشل في البداية وانك ما تقدر تحل لانه هذا الشئ يعطيك دافع انك تذاكر وتتحسن من نفسك لكن لا وثقت بنفسك هنا المصيبه الدكتور عبدالرحمن الشلالي كذا يحطمك عشان تذاكر وتجيب درجات فا الوضع سهالات كل اللي مطلوب منك الحين لانه ما بقى وقت على الميجر انك تذاكر من الكتاب الاساس وتفهم الدرس يتكلم عن ايش والفكره العامه وبعدها تمسك الريسايتيشن وتبدا تحل الاسئله اللي فيها وتتاكد من حلك بانك تروح للدكتور بالاوفس اور وبعدها اللي هو قبل الميجر باسبوع تمسك الاولد اكزامز وتحاول تحلها كلها واللي ما تفهمه روح للدكتور بالاوفس اور ولو ما كان موجود ادخل على اي دكتور وهو باذن الله راح يساعدك والاولد اكزامز حاول تاخذ حقت ادهم لانها مرتبه وكويسه وانتبه لا تضيع نفسك حاول توازن مع المواد الثانيه.\n\nاتمنى اني افتدك ولو بشئ بسيط وبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/166027/6", "user": "_11101", "ts": 1412862431000, "tid": 166027, "pn": 6}}', 1412862431000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1404843-math001', 'stk-rockyz', 'MATH 001', 'info', '{"desc": "لا تيأس ولا تخاف\nانا رسبت في ماث 001 ولما عدته جبت درجه جدا عاليه وانا تأسيسي نفس تأسيسك عادي جدا مع ان درجاتي كانت عاليه بالرياضيات في الثانوي\n\nغلطي الوحيد كان المصدر او الاستيعاب انا ايش اللي قاعد اخذه\n\nالفصل الاول ذاكرت من الكتاب مذاكره جدا عاديه ونوتات الدكتور وماعديت\n\nمو يعني ان الكتاب سيء او لا تذاكر نوتات الاستاذ\n\nذاكر نوتات ادهم مهمه جدا جدا في 001 ومعها نوتات دكتورك , افهم الاساسيات من نوتات دكتورك والكتاب واختبر نفسك في نوتات ادهم , لا تشوف نفسك انك ماتقدر وكذا الموضوع جدا سهل وما بتستوعب انه سهل الا بعد ماتخلصه وتشوف بنفسك , بالتوفيق في مسيرتك الجامعيه", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/166027/7", "user": "Rockyz", "ts": 1413189798000, "tid": 166027, "pn": 7}}', 1413189798000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p987885-math001', 'stk-so_lost', 'MATH 001', 'info', '{"desc": "الله يعافيكم يا شباب …\n\nانا جتني اسئلة بخصوص الوقت ,\n\nالوقت راح نتناقش فيه مع اول كلاس ونحاول انه يكون مناسب ومريح لكل الطلاب\n\nالكلاس الواحد ما راح يزيد عن 10 طلاب ولا يقل عن 5 … عشان يكون التركيز اكثر 🙂\n\nالماث 001 و 002\nراح يكون اغلب الوقت حل مياجر وتدريب على الحل بأقل وقت ممكن 2.5 الى 3 دقائق للمسألة الواحدة\nوحصر الافكار اللي راح تجي في الميجر بحيث ان الطالب من اول ما يشوف شكل السؤال يعرف طريقة الحل\nيعني الفل مارك غصب عن اللي حط الاسئلة لووول\n\nالانقلشما فيه تحديد … راح نركز على القواعد (قرامر) والتحدث بشكل كبير جدا…\nبحيث ان الطالب يستطيع التحدث بدون اخطاء وبسرعة وطلاقة ونطق سليم…\nايضا راح نركز على الكتابة …واذا سمح الوقت راح نمر على باقي المهارات والهوموركات 🙂\n\n==========\n\nاخوكم ابو ناصر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a/121122/11", "user": "so_lost", "ts": 1329438781000, "tid": 121122, "pn": 11}}', 1329438781000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p370575-math001', 'stk-alb7ar1', 'MATH 001', 'info', '{"desc": "بالنسبة للماث 001 انا كنت اذاكر من نوت ايمن وجبت درجة حلوة\n\nلكن ما أنصحك فيه 002.\n\nانا عن نفسي كان يدرسني خالد سيف الله ,فكنت اذاكر من نوته واحل مسائل محمد خان\n\nهذا افضل شي, لأن المسائل اللي يجيبها محمد خان فيها تركات والمام للدرس من كل جوانبه\n\nوالأفضل من هذا كله زي ماقال الأخ اللي قبل ذاكر من الكتاب لأن بعدين فوق الجبل\nفي مواد لازم تذاكرها من الكتاب.\n\nوبالنسبة للأنجلش بالنسبة لي 002 اسهل من 001 فشد حيلك أكثر وفالك +a\n\nوبالتوفيق…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-002/70772/3", "user": "alb7ar1", "ts": 1235222265000, "tid": 70772, "pn": 3}}', 1235222265000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p218311-math001', 'stk-user2728', 'MATH 001', 'info', '{"desc": "أنا أول أوريا يشيل مادة . . .\n\nأحلى F و الله يعين الترم الثاني . . .\n\nاعوذ بالله من الشيطان الرجيم\n\nياخوك\n\nلسا فيه 15 درجة حق ميجر 2\nولسا باقي كلاس وورك من 10\nولسا باقي فاينل من 35\n\nيعني يكفي الفاينل والميجر 2\n\nوبيني وبينك\nترى الميجر 2 بيجيك بلحاله\n\nيعني ما راح يحي معه في نفس الاسبوع ميجر لمادة معينة\n\nاستغل ذاك الاسبوع وحاول انك تجيب فيه اعلى قريدات\n\nوعود نفسك على الحل\n\nواذا حصل عندك بريك في دوامك غير بريك الغدا\n\nتراها تكفي والله انها تكفي انك تذاكر فيه درس الماث بشكل يومي\n\nيعني الدرس اللي خذته هالكلاس\nوحصل لك بريك في ذاك اليوم\nحاول انك تذاكر النوت اللي كتبته معه او الكتاب اذا كنت تجيبه او نوت تشتريه من الجمعية\nوبعدها حل التمارين عن الدرس اللي خذته بعد كل تشابتر في الكتاب\n\nلسا باقي 60 درجة\n\nاسال الله لنا ولكم التوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/59708/6", "user": "user2728", "ts": 1194981697000, "tid": 59708, "pn": 6}}', 1194981697000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p218336-math001', 'stk-user3171', 'MATH 001', 'info', '{"desc": "* الاختبار سهل مقارنة بالماضي لكنه يعتبر أصعب من الميجر من ناحية الأفكار و سرعة الحل\n\n*الأفكار في الاختبار كانت بسيطة و ليست بذلك التعقيد و يمكن لأي شخص مهما كانت قدرته إيجادها .\n\n* المشكلة التي واجهتني و هي عامل الوقت في بداية الاختبار أول 15 سؤال خلصتها و كان باقي حوالي ساعة و ثلث قلت خلاص براجع حللولي على الأقل أضمن 15 سؤال .\nو بعدها بربع ساعة بديت احل باقي الأسئلة لكن تفاجأت أن الأسئلة الأخيرة أصعب مقارنة بالأسئلة الأولى و ما قدرت أخلص إلا على الوقت", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/59708/12", "user": "user3171", "ts": 1194986262000, "tid": 59708, "pn": 12}}', 1194986262000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p218360-math001', 'stk-adidas', 'MATH 001', 'info', '{"desc": "@66@\nعظم الله أجركم يا عيال دفعتنا\n@66@\n\n25 درجة وراحت …\n\nوالله يستر من الجاي …@66@\n\nالإختبار مو سهل أبدا حتى لو كنت طابع ابو المادة …\nوالدرجات راح تحكم…\nشباب ترا الـmcq والله تلحس المخ تحل غلط وهم يعطونك على قد عقلك ويحطون لك الاختيار اللي بتغلط فيه …\n\nلكن اللي من جد مستغرب منه فيه ناس خلصو قبل الوقت باكثر من نص ساعة@24@\nلو انقل الحل نقل ما اخلص بهالسرعة ما شاء الله تبارك الله ما شاء الله اللهم لا حسد …\nشوي شوي على الأفرج تكفى انا اعطيكم مكافئة الـ500 مو لازم اونر @66@\n\nويوم قالو باقي نص ساعة وانا لسا عند سؤال 14 @24@@24@\nوالله قمت احل سريع سريع … لكن على مين تلعبها جتك الأسئلة اللي بعدها شغل نظيف@56@\nخلص الوقت وانا عند سؤال 19 والباقي حطيتها ديات وربك يستر … عسى ما اخذ دي @48@\nزبدة الكلام مافيه كل سؤال بفكرة معينة يعني تلقى سؤال عن شابتر ون يعصر لك شابتر بي كله من اوله الا آخره بالسؤال هذا\n\nالموووهم مشكوور اخوي على الموضوع ويعطيك الف عافية", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/59708/13", "user": "Adidas", "ts": 1194989369000, "tid": 59708, "pn": 13}}', 1194989369000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p218396-math001', 'stk-abu_faisal', 'MATH 001', 'info', '{"desc": "أشكر كل من شارك بالموضوع …\n\nأما عن رأي في الاختبار\n\nالاختبار كان سهل بنسبة 75%\n\nيعني تقريبا 20 سؤال كانوا سهلات …\n\nبس 5 اسئلة كان فيها تفكير بزيادة …\n\nانا خلصت قبل الوقت ولله الحمد …\n\nوأمداني اراجع …\n\n*** ماشاء الله تبارك الله ***\n\nلكن الله يستر من الدرجة …\n\nعموما … مثل ماقالوا الشباب … يمدينا نعوض … في الجاي …\n\nتحياتي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/59708/16", "user": "Abu_Faisal", "ts": 1195017132000, "tid": 59708, "pn": 16}}', 1195017132000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p210048-math001', 'stk-user902', 'MATH 001', 'info', '{"desc": "السلام عليكم\n\nالسلام عليكم وكل عام و أنتم بخير\n\nأنا درست مع أحمد الزعبي في أول سيمستر لي في الجامعة math 001\n\nالمادة هذي و 002 لو تشوف المواضيع اللي فيها فهي مواضيع المرحلة المتوسطة والثانوية إلى\n\nثاني ثانوي و لكن الفرق أن الثانوي والمتوسط كان حتى الرياضيات يحفظونك إياه ويطلع الواحد مصدق نفسه دافور في الماث وإذا جا للجامعة شاف أسئلة الفهم وجاب العيد لأنه متعود يلقى أسئلة من نوت المدرس .\n\nنصيحة:\n\nالماث يمديك تذاكر من الكتاب وأنا عارف أنه صعب لأن حديث التخرج من الثانوي مصاب بفيروس النوتات ولكن ذاكر من كتاب الأوريا وحاول تفهم لا تحفظ وبعدين …( النصيحة الذهبية قادمة ) :\n\n.\n.\n.\nلا ثم لا ثم لا تدخل الميجر بدون ما تحل إختبارات قديمة وخاصة ميجر ون حتى تعرف كيف تكون طريقة الأسئلة\n\nعلى فكرة اذكر الرجال كان راعي سوالف وفيه سالفة دايما يعيدها سالفة الأمريكية اللي درسها وتفوقت بعد ما كانت جايبه العيد على ما اذكر\n\nدمتم بخير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/58862/25", "user": "user902", "ts": 1192306901000, "tid": 58862, "pn": 25}}', 1192306901000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p338303-math001', 'stk-user3783', 'MATH 001', 'info', '{"desc": "يا شباب لاحد يخلي طموحه C الي يقول خد 63 وتجيب الافرج وتمشي من شب على شي شاب عليه يعني بيسي دا نهجك في مواد الجبل كمان\nفالي جاب قريد حلو والي ما جاب الكل ينسى الي فات ويتعلم من اغلاطه وانتو شفتوا نوعية الاسئلة وطريقتها شدو حيلكم في الميجر التاني والفاينل وحاولوا انكم تحلوا الاسئلة الفردية لانه حلولها موجودة والهومورك والامثلة\n\nوالله يوفقكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68151/39", "user": "user3783", "ts": 1227746116000, "tid": 68151, "pn": 39}}', 1227746116000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p750094-math001', 'stk-user5882', 'MATH 001', 'info', '{"desc": "اسمع تجربتي وان شاء الله تعرف ان اسهل حاجة انك تعدي الماث وما يحتاج تقلق بس يبغالك شووووووووووية شغل الرغبة لوحدها ما تنفع ,\nانا ماث 001 اخذت في الميجرالاول 11 والثاني 12 ومجموعي كذا 23 …\nجاني احباط وقلت اني راح اعيد وخفت وووو الخ\nطبعا في الميجرين كلها ما كنت اذاكر الا قبل الاختبار بيومين وكان مذاكرة دلع احل مسألة والعب سوني واطقطق على النت واروح لمسألة ثانية وهكذا\nاخذت كلاس وورك 11 عند خان وكنت اقل واحد في السكشن وصار مجموعي 34 ويبغالي عشان اضمن نجاحي حسب الافرج وكلام الناس تقريبا من 20 الى 25 درجة\nقلت انها كثيرة وما راح اقدر قبل الفاينل اجيبها وحاولت قبل الفاينل بـيومين بعد ما شفت الكلاس وورك ( لأني كنت معتمد اني انجح بالكلاس وورك لكن خذلني ) اذاكر منهج ماث 001 كااامل بالاولد اكزام لأن مذاكرة المياجر ما كانت مذاكرة فاعتبرت نفسي اذاكر من جديد\nططبعا ما لحقت لأني متأخر جدا جدا وجبت في الفاينل 23 وصار مجموعي 57 درجة\nتعرف النجاح كم كان في الترم 091 ؟؟ كان اعلى درجة نجاح في تاريخ الجامعة , 58\nرسبت بدرجة بسبب اهمالي وكان يمديني لكن للاسف متأخر جدددددا\nوعدتها في الترم الثاني وعديتها بسهولة بالغة واخذت 002 صيف وانا الان جبل والحمدلله كله تمام\n…\nالشاهد من التجربة , ان لا تعتمد اعتماد كلي على الكلاس وورك زيي وتنصدم بعدين بدرجة ما تتوقعها وتحبط امالك , خلي نجاحك بيدك وخلي الدكتور اعتبر درجات الكلاسوورك هدية\nجات حياها الله باخذ قريد ,\nما جات مع السلامة انا انجح بدرجاتي\nجيب درجة حلوة اليوم على الافرج او فوق والله يوفقك\nوصدقني شد حيلك في الفاينل … لو كان باقيلك 30 درجة راح تنجح مهما كانت درجاتك في المياجر\nلأن الفاينل مرة سهل وتافه وبتشوف بعينك ويمكن تطق الفل مارك بسهولة بس ما يجي سهل كذا\nلازم تذاكر له خلاص في الفترة الجاية تقعد على الماث ساعة ونص او ساعتين يوميا ارجع عيييد كل اللي اخذته + اللي بتاخذه دحين وبتشوف كيف تتسهل معاك الامور\nوانجح بدرجاتك لا تنتظر كلاس تيست ولا تنتظر رحمة مدرس يعطيك حسب افرج الكلاس\nشد حيلك وفالك a+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/99535/5", "user": "user5882", "ts": 1293092967000, "tid": 99535, "pn": 5}}', 1293092967000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p940791-math001', 'stk-user8219', 'MATH 001', 'info', '{"desc": "السلام عليكم\nاعرف واحد كان زي حالتك …وعدى\nسورنسن …سييييييييييييييء لابعد حدود ولا الومك …لكنه يعلمك شي تحتاج تعرفه قبل ما تطلع الجبل وتورط\nالي هو …\nلا تعتمد على الدكتور ابدااااااااا اعتمد على الله ثم على نفسك ذاكر من الكتاب روح الاوفس اور لدكاترة غيره …اذا كان الدكتور تمام استفيد منه وذاكر بنفسك كمان\nترى الباس ما ضاع …ابدا اجتهد وتقدر تعدي\nولو لا قدر الله ما عديت …مو مشكلة عندك الترم الثاني…لا تخاف…ان يارب تعدي\nوترى الانجلش اهم من الماث …*", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/115979/2", "user": "user8219", "ts": 1322757791000, "tid": 115979, "pn": 2}}', 1322757791000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p940796-math001', 'stk-user7485', 'MATH 001', 'info', '{"desc": "في الكوزات أفرجك 9 من 15 لكن في الكلاس وورك الكوزات لها 8 درجات يعني بتاخذ 4.8 من 8\n\nالكلاس تيست بتاخذ 2.3 من 10\n\n4.8 + 2.3 = 7.1 من 18\n\nفي الكلاس وورك عندك الهوموركات 6 درجات كمان + عندك فرصة ترفع درجاتك في الكوزات الجاية والكلاس تيست لو فيه كلاس تيست\n\nهذي عن كلاس وورك من 24\n\nأما المياجر ،، الأول أخذت 10 والثانية لنعتبر إنها 9 صح\n\nخلينا نجمع بالتقريب\n\n7.1 نقول 7 حقت الكوزات والكلاس تيست + 3 في الهومورك يعني لنفترض جايب 10 في الكلاس وورك\n\n+ 10 الميجر الأول\n+ 9 الميجر الثاني\n\nمجموعهم 29\n\nباقيلك من النجاح 60 - 29 = 31\n\nهذا أسوأ الإحتمالات ،،\n\nحالتك الحين ، باقي عندك فرصة تضبط نفسك في الهوموركات والكوزات وصدقتي راح تفيدك + إبدأ تجهيز للفاينل من الآن ،، من الآن\n\nوبإذن الله راح تعدي الكورس ، بالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/115979/6", "user": "user7485", "ts": 1322758183000, "tid": 115979, "pn": 6}}', 1322758183000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p941639-math001', 'stk-nar_7ubk', 'MATH 001', 'info', '{"desc": "اول شي الله يكون ف عونكـ وتقرّب ل الله اكثثثر وخلي الوآلد والوآلدهـ يدعون لكـ\nثآنيًآ : مجموعك ف الميجرين خلنآ نقول 20 بمآ آنه ثلاث قسيتهآ م تدري صح ولـآخطآ\n\nكآن معآي وآحححد عندهـ دكتور لووح , جآب الميججر الـآول 6 من 20 , مسك الكتآب دفففر فيه وحل كل الـآود نمبر \" الاعداد الفردية \" ف اسئلة الكتآب وطلع ف الميجر الثاني ب 18\n\nيعني السسسالفة ي طويل العمر ابدآ من الحييين ولاتخلي ولا سؤال فردي الا تحله صح كثيرة بس رآح تفهمك صححححححح ان شاء الله\n\nاما سآلفة انك ب تعيد ولـآ لـآ , هالسؤال م ينسأل\nكل شي ب يد الله ثم ب يدكـ\n\n20 ميآجر , خلنآ نآخذ ع اسوأ الـآحتمآلـآت الدكتور عطآك 8 كلاس وورك < هذي 28\nكم بآقي لك ع الـ 60 !! 32 درجة من 36\nوطبعًا الافرج العاده اقل من 60 بس تاخذ اسوأ الاحتمالات\nوترى 32 الفاينل والله ب يدك\nانا دخلت الكتاب ب مجرد نظرة ع الكتآب وطلعت ب 26\nواعرف وآحد مستوآه متسوط بس م شاء الله جاب 35\nيعني هالششي ب يدك\nشد حييلك واترك عنك الدكتور م يشرح ومدري وش , وان شاء الله فآلك السي بلس 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/115979/31", "user": "NAR_7ubk", "ts": 1322881767000, "tid": 115979, "pn": 31}}', 1322881767000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p923293-math001', 'stk-with_your_self', 'MATH 001', 'info', '{"desc": "الحمد لله على كل حال الاختبار كان بسيط صراحة وما توقعته كذا لكني من زود العجلة حليت الأسئلة الصعبة والسهلة لخبطت فيها أوووووه هذا القهر بعينه والله من كثر الصعوبة في الكلاس تست وفي الكويزات قلت في نفسي الميجر بيجي صعب مرة وذاكرت أصعب الأسئلة لكن لم يحالفني الحظ في الدرجة الكاملة وإن شاء الله أعوضها في الميجر الثاني … موفقين شباب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/solution-math-001/114220/18", "user": "with_your_self", "ts": 1319211604000, "tid": 114220, "pn": 18}}', 1319211604000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1089607-math001', 'stk-user8975', 'MATH 001', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nالسلام عليكم ورحمة الله وبركاته …\n\nأورياتنا الحلوين 🥰 😁 تحية طيبة وبعد 🤠 :\n\nمعلومات مهمة /\n\n* فيه اختبارات حلوة عندنا بالجامعة اسمها ميجر 🥊\n\nالميجر هذا يكون مثل طريقة القدرات 😆\n\nعندكم ميجر 1 و ميجر 2 … كلكم بتختبرون بنفس الوقت ونفس القاعة ونفس النموذج وكل الأسئلة اختيارات وتصحيح كمبيوتر … أول ميجر بعد شهر تقريباً ، وثاني ميجر بعدها بشهر ونص … وآخر شي فاينل\n\nالميجر 20 سؤال ، والفاينل 35-40 سؤال …\n\nالمهم …\n\nمهما كنت فاهم الماتيريال ، إذا ما تدربتم على الأولد إكزام وحليتم أمثلة ، باختصار ستندمون 🤠\n\nومن باب التعاون على الخير ،\n\nأقدم لكم ملف أولد إكزام مقسم بالشبتر + نوت ، وكتبهم ونقحهم د. قيصر إمام 🤴 🌹\n\nوبالملف أيضاً الكوزات الي اختبرتها معه ، وغير ذلك 🤠\n\nهذا ملف ممتاز جداً جداً ونفعني كثيير 😎\n\nأنصح به بشدة 🙂\n\nرابط الملف في ميديافاير : هنا\nرابط الملف في فورشيرد : هنا\n\nملاحظة : أرجو إبلاغي في حالة عدم عمل الروابط ، لأن سيرفر الجامعة يسوي مشاكل مع مواقع التحميل 🤪\n\nوفالكم التوفيق 😎 🥊", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-001/131560/1", "user": "user8975", "ts": 1347202401000, "tid": 131560, "pn": 1}}', 1347202401000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1107493-math001', 'stk-chelsea_21', 'MATH 001', 'info', '{"desc": "من اليوم استعد لميجر 2\n\nكيف تذاكر لماث 001\n\n{ مذاكرة عامة } نجاح بـ c ، c+ في الغالب\n\n1/ بعد الكلاس ذاكر الدرس الي اخذته ولا تأجل مذاكرته \" خلاص اخذته السبت ، السبت المساء ذاكره\".\n2/ ذاكر لكل كويز او كلاس تست مذاكرة قوية جدًا\n3/ في حصة الريزينتايشن ، اسئل مدرسك الاسئلة الي مو عارف كيف تحلها.\n4/ اذهب الى مدرسك بالاوفيس اور عشان يحل لك او يعلمك الاسئلة الي ماعرفتها انت\n{ اسئلة الاكسرزاييس الي بالكتاب الي ماتعرفها جمعهّا من بين الدروس وجيبها لمدرسك }.\n5/ اولد اكزام\n6/ تمارين اونلاين { خاص بكل مدرس وسكشنه }\n\n{ مذاكرة خاصة } نجاح a+ ، a و b+\n\n1/ ذاكر الدرس قبل لاتجي الكلاس ، مع حل جميع الاسئلة الفردية والزوجية.\n2/ خل عندك دفتر خاص “بحلول” التمارين\n3/ ذاكر تمارين الدرس مرة ومرتين وثلاث ، تقريبًا هم حوالي 80 سؤال ! حلهم مرة ومرتين وثلاث واربع و…\n4/ لازم تذاكر بطريقة الكتابة ، لازم تكتب ، مش تقرأ ، خل عندك اوراق a4\n5/ لازم تسئل مدرسك سؤال في الكلاس \" فيها فوائد : 1 / الاولى بتعرف النقطة الي موفاهمها 2/ ثانيًا المدرس بيعرف انك مهتم\n6/ الويكند لازم تذاكر فيه ، { اهم نقطة } ذاكر فيه الاربعاء والخميس والجمعة\n7/ الاولد اكزام اطلع على واحد فقط في كل اسبوع بالاجازة { مطالعة فقط ، مع انه مو اجباري تذاكر اولد اكزام عشان اريحك ،ولكن مع هذا له فوائدة ، فقط قبل المياجر والفاينل }\n8/ حل الهوروركات بدري يعني قبلها بأسبوع تكون مخلص. { جربها مرة ، بتحس ان سعيد انك خلت شيء بدري }\n\nnote\n\n001 كله اساسيات وسهل ، مش لازم تستصعبه داخل نفسك بالتفكير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/133501/4", "user": "Chelsea_21", "ts": 1350121940000, "tid": 133501, "pn": 4}}', 1350121940000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1321286-math001', 'stk-exiled', 'MATH 001', 'info', '{"desc": "المواد الدراسية //\n\nالرياضيات\n\nMath 001,002,101,201,202,\nStat , numerical method\n\nماث 001 و 002 يتكلمون الجبر وجميع التخصصات الهندسية يدرسونهم ، و ماث 101 و 102 يتكلمون عن الاشتقاق و التكامل\nالتكامل هنا تكامل محدود يمكن حله رياضيا يسمى ( أنالاتيك )\nيعني تكامل بالتعويض ( by substation ) أو تكامل بالتجزئة ( by part ) وفيه طرق كثيرة لحل هذه مسائل التكامل ، بعض المسائل التكاملية معقد والبعض سهل ، والبعض الآخر لا يمكن حله إطلاقا بـ طريقة ( الإنالاتك )،\nطيب أنت مهندس كيميائي وفي المصنع ووصلت إلى مسألة تكاملية معقدة لا يمكن حلها بـ( الإنالاتك ) ماذا يفعل المهندس الكيميائي في هذه الحالة ؟\nيحلها عن طريق مادة نيوميركال ميثود ( numerical method ) يحل هذا التكامل عن طريق حساب المساحة تحت المنحنى وقيمة هذه المساحة هي نفسها قيمة التكامل …\nأما مادة ( stat ) البعض يعتقد أنها مادة ( إحصاء ) ، وهي تختلف تماما عن الإحصاء ، هذه المادة مهمة جدا ، بل من منظوري الشخصي أعتقد أن هذه المادة أهم مادة في الهندسة و في الرياضيات والعلوم أجمع… أهمية هذه المادة تكمن في تحويل المنحنى إلى معادلة ، مثلا لو عندي منحنى على إحداثيات س و ص ، ويحاول المهندس إيجاد المساحة تحت المنحنى ، لكي يوجد المساحة تحت المنحنى يجب أن يعمل تكامل لمعادلة المنحنى ، المشكلة هنا كيف يعمل تكامل لمعادلة المنحنى و أساسا لا يوجد معادلة بل يوجد ( منحنى ) ويوجد ( معطيات ) فقط ،\nفماذا يفعل هذا المهندس الآن ؟\nمن خلال دراسته لمادة stat\nيستطيع تحويل المنحنى إلى معادلة ،\nويستطيع تحويل المعطيات الرقمية إلى معادلة ،\nويستطيع أيضا تصميم برنامج على الكومبيوتر يتيح لنا تحويل المعطيات الرقمية إلى معادلة\n\nالكيمياء\n\nChem101,102,311,201,202\n\nكيمياء 101 و 102 هي أساسيات مهمة ليس فقط للمهندس الكيميائي بل لجميع التخصصات حالها كحال فيزياء 101 و 102 هي مجرد أساسيات مهمة لكنها في الغالب لا تدخل في عمق التخصص\n\nأما بالنسبة للكيمياء 311 هي أساسا أسمها الكيمياء الفيزيائية وهي في الحقيقة أقرب للفيزياء والهندسة ، وبعيدة عن الكيمياء ، هي أساسيات لخواص المواد الفيزيائية و الديناميكا الحرارية و أطوار المادة و الكهروكيميائية .\nومادة كيمياء 201 و .202 تتحدث عن الكيمياء العضوية وهي ممتعة جدا ، وبعيدة كل البعد عن الحفظ وتعتمد بشكل كبير على الفهم و حل المسائل بشكل مستمر وتعتمد على معظم أساسيات الكيمياء 101 و 102 .\nالكيمياء 323 هي كيمياء التحليلية إلى الآن لم ادرسها ولم أعرف خفاياها ولكن بحسب ما سمعت أنها تعتمد على الفهم وعلى التطبيق كثيرا .\nلو لاحظتم أن مواد الكيمياء في الهندسة الكيميائية تعتمد على الفهم بشكل كبير وهي مواد تثقيفية أكثر من كونها أساسية ، بمعنى أن لو المهندس الكيمياء لم يفهم مواد الكيمياء جيدا فهذا لن يؤثر على مستواه في مواد الهندسة الكيميائية الأساسية .\nلذلك من الممكن أن نجد مهندس كيميائي لا يفهم الكيمياء بشكل جيد ، ونجد هذا المهندس مبدع ومبتكر في مجال وهذا لا يتعارض مع ضعفه في الكيمياء.\n\nالفيزياء\n\nph101,102\nفيزياء 101 و 102 أسياسيات الفيزياء تنقسم إلى ميكانيكا الفيزياء و ميكانيكا الموائع و الفيزياء الكيميائية و الفيزياء الكهربائية … أساسيات مهمة ستساعد المهندس على فهمه لتخصصه أكثر سواء هذا المهندس كيميائي أو ميكانيكي أو كهربائي … أو … أو … الخ\n\nالهندسة الكيميائية\n\nChe201,204,203,303,300,304, ومواد أخرى\n\nهندسة كيميائية 201 هي أساسيات تعتمد على الرياضيات و الفيزياء، بالنسبة لرياضيات فهي جبر وحل معادلات مجهولين بمعادلتين وربما تصل إلى ثلاث مجاهيل و ثلاث المعادلات وتحل عن طريق المصفوفات ، أما بالنسبة للفيزياء فهي قوانين أساسية بإيجاد الضغط و الكثافة وغيرها\n\nهندسة كيميائية 204 هي ميكانيكا الموائع مادة ممتعة جدا وتطبيقية و عملية جدا وتدخل بتصميم المضخات و الصمامات و الخزانات ، بداية المادة تعلمك إيجاد الضغط و القوة ، ثم تتدرج نحو مفهوم هندسي مهم وهو ( قانون حفظ الكتلة ) ثم تنتقل إلى مفهوم أوسع وهو ( قانون حفظ الطاقة ) القانون الأول لديناميكا الحراري ، ثم ننتقل إلى مفهوم تطبيقي بحت وهو قانون بارنولي فكرة هذا القانون يعلمنا إيجاد سرعة المائع من خلال معرفة فرق الضغط و فرق الارتفاع هذا القانون تطبيقي ولكنه لا يمكن أن يكون عملي في الواقع لأننا في هذا الفصل نهمل الاحتكاك لكن في الفصل السادس يندرج الاحتكاك و الشغل في هذا القانون ويتعقد القانون كثيرا ويتعقد حله لكن في الأخير المهندس الكيميائي يحصل على معطيات صحيحة وحقيقية وعملية وهذا هو الأهم ، ويستطيع المهندس الكيميائي من قانون بارنولي أن يصمم صمامات ويحدد المضخات و يصمم قطر الإنبوب و سمك الإنبوب و يوجد التدفق الحجمي وسرعة جريان المائع وإيجاد قيمة الاحتكاك بسبب الصمامات وبسبب طول الإنبوب ويسمى هذا الاحتكاك بـ ( pressure drop ) ، هذا مختصر للكورس ومثل ما تعرفون الكورس هذا يعتمد على الفيزياء بشكل كبير وأيضا يعتمد على الرياضيات أحيانا تتعقد المسألة وتصل إلى التكامل الرياضي ويتم حلها .\n\nهندسة كيميائية 203 هي الديناميكا الحرارية 1 وتعتمد على الفيزياء و الرياضيات بنسبة 98% و على الكيمياء بنسبة 2% ، هذه المادة تنقسم إلى ثلاث أقسام//\nالقسم الأول : قانون الديناميكا الحراري الأول وهو KE+PE+H=Q+W قانون ممتع لكن للأسف كثير من الطلاب يفهمون تطبيقه الرياضي لكن لا يستطيعون فهمه فيزيائيا ولهذا السبب تحدث المشكلة ، نستطيع من هذا القانون حساب الشغل ( الورك ) لـ تربينه عندما نصب عليها مياه من البحر عند ارتفاع محدد و سرعة محددة ، ونستطيع أيضا معرفة درجة الحرارة من الــ H وهو المحتوى الحراري .\nالقسم الثاني : هو قانون الديناميكا الحراري الثاني هذا القانون أشد تعقيد من القانون الأول وللأسف الشديد كثير من الطلاب لا يفهمون هذا القانون مفهوما فيزيائيا ، وكثير منهم لا يفهم ماذا يعني بالإنتروبي ( ENTROPY ) سأحاول أنا أختصر المفهوم للقانون ،\nبالبداية لماذا وجد هذا القانون لديناميكا الحراري الثاني ؟؟ هذا القانون وجد عندما حاول المهندسين والعلماء تحويل الحرارة والضغط إلى الطاقة ، هنا حدثت مشكلة فيزيائية عجيبة ، وجدوا أن الحرارة صاحبة 100 جول عندما نحولها إلى الطاقة حركية مثل السيارة نجد أن الطاقة الحركية تساوي 40 جول فقط ، أي أن الحرارة لا تتحول كلها إلى طاقة حركية ، وهذا يخالف القانون الأول لديناميكا الحراري ويختلف عنه كثيرا ، لذلك العلماء أوجدوا قانون الديناميكا الحراري الثاني فتحويل الحرارة والضغط إلى طاقة كهربائية و حركية من العلوم المفيدة جدا للبشرية .\nالقسم الثالث : يتحدث عن تأثير الحرارة بدون تفاعل كيميائي ومع تفاعل كيميائي ،\nأ ) تأثير الحرارة بدون تفاعل كيميائي : مثلا أذا أردت تسخين ماء كم تحتاج إلى حرارة لترفع درجة حرارة الماء من 10 درجة مئوية إلى 80 درجة مئوية وهذا أبسط مثال عليها وتحل هذه المسألة عن طريق التكامل الرياضي أو عن طريق ( سي بي مييين ) ، وقد تتعقد المسألة كثيرا وبما يطلب منك إيجاد درجة الحرارة النهائية وتحل هذه المسألة عن طريق التجريب والخطأ ، ( TRY AND ERROR) .\nب) تأثير الحرارة مع تفاعل كيميائي : هذه المسألة من أعقد وأهم المسائل في الهندسة الكيميائية ولحلها تحتاج إلى وقت طويل لشرحها ويصعب شرحها عن طريق المنتدى .\n\nهندسة كيميائية 300. هي إنتقال الحرارة وهي مادة ممتعة جدا ، وتعتمد على الرياضيات كثيرا خصوصا ديفرنشل إكويشن MATH 202 وتعتمد أيضا على الفيزياء ولا تعتمد أبدا على الكيمياء ، تنقسم هذه المادة إلى ثلاثة أقسام :\nإنتقال الحرارة بالتوصيل وهو إنتقال الحرارة عبر جسم واحد أو جسمين جامدين ، مثلا لو كان هنا كتابين ملتصقين ودرجة حرارة الكتاب الأول أعلى من درجة حرارة الكتاب الثاني فإن الحرارة ستنتقل من الكتاب الأول إلى الكتاب الثاني عن طريق التوصيل ، وانتقال الحرارة بالتوصيل لها قانون محدد . النوع الثاني هو إنتقال الحرارة بالحمل وهو إنتقال الحرارة بين سطح الجسم و المائع مثلا كانتقال الحرارة بين الهواء والجدار أو الهواء و الكوب ، لو مثلا عندنا كوب حار جدا بعد مدة من الزمن نجد أن الكوب أصبح باردا وذلك بسبب إنتقال الحرارة من الكوب إلى الهواء قللت درجة حرارة الكوب . النوع الثالث هو إنتقال الحرارة للأجسام عبر الفراغ أو الهواء كـ إنتقال حرارة الشمس إلى الأرض ، وانتقال حرارة جدار المنزل إلى أجسامنا…المادة ممتعة جدا وتعتبر من أسهل المواد في الهندسة الكيميائية .\n\nالهندسة الكيميائية 304 هي إنتقال المادة وكما سمعت أنها من أصعب وأهم المواد في الهندسة الكيميائية ، لكن إلى الآن لم أدرسها لكي أضع بين أيديكم معلومات كافية عنها .\n\nأكتفي حديثي عن الهندسة الكيميائية هنا أسف على الإطالة وأتمنى وأرجو أنكم استفدتم ، وأشكركم على قراءتكم ، وأي استفسار أو ملاحظة أو نقد أو تصحيح لي في هذا الموضوع فأهلا وسهلا بكم ، أنا بانتظاركم\n\nفي النهاية من أراد أن ينسخ وينشر هذا الموضوع فله الأجر إن شاء الله لكن أتمنى أن يذكر أسمي كي لا يضيع الجهد\n\nكتب بواسطة / مالك التميمي\n\n- نقل للفائده", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/155608/2", "user": "Exiled", "ts": 1390371656000, "tid": 155608, "pn": 2}}', 1390371656000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p883531-math001', 'stk-amat_24', 'MATH 001', 'info', '{"desc": "الصراحة… السنة التحضيرية ما تحتاج فيها لا جهد مضاعف ولا شي\n\nمجرد انك تذاكر بنفس الجدية اللي كنت تذاكر فيها ايام ثالث ثانوي\n\nوهذا شيء جدا صعب، لانك حتلاقي المنهج شكله سهل فحتبدا تتساهل، لكن الاختبارات ابدا مو سهلة…\nاحد الافخاخ انه الmath 001 يعيدلك الرياضيات من الصفر، يعني عملية الجمع ابدالية وحل معادلات من الدرجة الاولى واشياء تافهة درستها من المتوسط، لكن مستوى الاختبارات عالي جدا\n\nوكثيرين يتساهلو ويقولو فلان ما ذاكر وجاب درجة حلوة، اجل اسوي زيه\nغير انه مافيه رقابة من الاهل وممكن تقضي الصباح في الدوام والمساء طلعات وسهرات مع الشباب وبلوت وفلة الخ…\n\nلا تفقد جديتك اللي ادخلتك الجامعة ، وباذن الله ما تشوف الا الخير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/110620/3", "user": "amat_24", "ts": 1313036676000, "tid": 110620, "pn": 3}}', 1313036676000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p922646-math001', 'stk-eng1', 'MATH 001', 'info', '{"desc": "اختبااااااااااار تاااااااااااافه … والله اني متحسف على الدرجات الي راحت 😦 نفسي اعرف ليش توهونا بالكويزات والكلاس تيست وجابوا لنا الشي الغبي ذا , الي نكنبي المراجعه قبل الميجر بيوم وغيره من عدم التنظيم وضياع الوقت, عاهدت نفسي انسى كل شي حصل وراح ابدا بداية جديدة من الاسبوع الجاي … لين ذحين وعلى حسب الدرجات الي حسبتها ان شاء الله فوق 12", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/1-001/114176/7", "user": "ENG1", "ts": 1319119833000, "tid": 114176, "pn": 7}}', 1319119833000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p922693-math001', 'stk-user8602', 'MATH 001', 'info', '{"desc": "شباب اختبااار والله ياهوو تافـه … تخيلو غلطت بالجزء التخيلي والمثلث بس >> 😆\n\nانشغلنا بالصعب ونسينا التافه … الحمدلله على كل حال كان اختبار سهـل للي مذاكر …\n\nجت اسأله طبق الاصل من نوته ناجي والاولد اكزامز الى 08 …\n\nاللي ماحالفه الحظ والتوفيق الله يوفقه بالجايات ان شاء الله ومو آخر المشـوار …\n\nاعرف لكم ناس جايبين تحت الخمـسه بالميجر وهم بالجبل الحـين 🤠 …\n\nبشـرونا انتـوو ماذا فعلتم من هوائل 🤪 !!", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/1-001/114176/10", "user": "user8602", "ts": 1319124555000, "tid": 114176, "pn": 10}}', 1319124555000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p922875-math001', 'stk-manunited', 'MATH 001', 'info', '{"desc": "الاختبار ايييييزي !! 😲\n\nبس عندي 3 اغلاط تافهه ! 🤪\n\nالصراحه قبل الميجر كنت اتمممنى اجيب +15 😆\nلكن يوم دخلت الاختبار طمعت بالعشرين 🤣\n\nاهني المدرسين على انهم يكرفووونا بالكلاس تست والكوزز 👍\nهالشي ساعدني كثيير وخوفني من الميجر وخلاني اركز بالمذاكره اكثر 👍\n\nوبالتوفــيــق لجميع الي جابو العيد وان شاء الله تعوضون ❤️\nومبرووك للي درجاتهم حلوه 😂\nولا يكبر راسكم وتفلونها باقي تونا 😛", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/1-001/114176/19", "user": "ManUniTeD", "ts": 1319151327000, "tid": 114176, "pn": 19}}', 1319151327000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p170764-math001', 'stk-user1962', 'MATH 001', 'info', '{"desc": "والله الشباب ما قصروا يا اخوي حموود …\nلكن الي حبيت أضيفه ، أنه الماث 001 سهل مو بهذيك الصعوبة ، وأنت ما شاء الله عليك ما اختارتك الجامعة وقبلتك إلا لأنك قدها …\nكل الي عليك الحين تعمله من مذاكرة وادعو من الله انه يوفقك واعتبر أنه 35 درجة موجودة عندك الحين وبإذن واحد أحد راح تجيبها هالدرجة …\nوحاول أنك بقد ما تستطيع تحل أكبر قدر من المسائل للمياجر السابقة واطلع لك بعد على نوت المسلماني زي ما قالوا الشباب ينفع ولا تعتمد على مسائل الكتاب كثير …\n\nوأسأل من الباري عز وجل أن يوفقك في دراستك وامتحاناتك …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/56456/9", "user": "user1962", "ts": 1179915265000, "tid": 56456, "pn": 9}}', 1179915265000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1121599-math001', 'stk-user9487', 'MATH 001', 'info', '{"desc": "وقت المذاكرة :-\nابدا من اليوم بحيث انه ما يخلص الاسبوع الجاي الا و انت مخلص شابتر ون\nو الاسبوع اللي بعده شابتر تو\nومن بعد الميجر ذاكر كل يوم بيومه\n\nمصادر المذاكرة :-\n1- الكتاب\nاذا خلصت منه روح ل\n2- الريسيتيشن و بعدها\n3- اولد اكزام\nيعني مثلا تمسك 1.1 تروح للكتاب و تقرا الشرح و تحل الاسئلة\nاذا خلصت روح للريسيتيشن حقه\nوزي كذا لبقية الدروس الين تخلصها كلها امسك الاولد اكزام\nاذا سويت زي ما قلت لك درجتك بالقلييييييييييييييل 18\n\nللمعلومية انا ما اخذت ولا درجة من اللي في العنوان\nلكن كل اسئلة الميجر كنت اعرف حلها ما عدا سؤال واحد\nلكن صارت لي لخبطة وقت الاختبار ضيعت تركيزي في بعض الاسئلة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math001-20-19-18-17/135206/4", "user": "user9487", "ts": 1353591966000, "tid": 135206, "pn": 4}}', 1353591966000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1121619-math001', 'stk-rsawi_mkawi', 'MATH 001', 'info', '{"desc": "أنا كنت أستعمل مذكرة خان … بس تراها صعبة شوي وتحتاج زود تركيز شوي … إذا أنت فاهم المنهج زين بس تبي تذاكر خذ مذكرة خان ، إذا تبي تفهم وكذا خذ لك مذكرة أيمن وإذا خلصتها خذ حقت خان … الكتاب ما راح يفيدك أبد ! دخلت وطلعت من التحضيرية ولا كد فتحته للمذاكرة … أهم شيء نوتة و أولد إقزامز !!! … فيه عيال كانوا يذاكرون الريسيتيشن ويمدحونه … عن نفسي كنت أذاكر الثلوث والربوع قبل الإختبار بس ودرجاتي ( 19 ، 16 ) 001 … و ( 17 ، 19 ) 002 … الكتاب ماله أي فايدة سوى إضاعة وقت …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math001-20-19-18-17/135206/6", "user": "Rsawi_Mkawi", "ts": 1353594962000, "tid": 135206, "pn": 6}}', 1353594962000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1121928-math001', 'stk-roronoa_zoro', 'MATH 001', 'info', '{"desc": "بكل بساطة انت الوحيد اللي تقدر تختار انسب طريقة لمذاكرتك\n\nاذا كان مدرسك ممتاز لدرجة انك تفهم منه الدروس بدون مراجعه فهذا شيء يريحك كثير\n\nاما اذا كان مدرسك على العكس فحاول انك تذاكر أول بأول\n\nوخل الكتاب هو مرجعك الرئيسي والاول اما بالنسبة للنوتات فهي مرجع ثانوي\n\nاذا انتهيت من كل شابتر رح حل اسئلة الــ(odd numbers ) فهي راح تساعدك كثير على فهم المنهج\n\nاذا خلصت استعن بالله وحل اكثر من old Exam عشان تاخذ خلفية عن الافكار اللي راح تجيك في الامتحان\n\nهذا وصلى الله على نبينا وحبيبنا محمد وعلى آله وصحبه الطيبين الأطهار", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math001-20-19-18-17/135206/16", "user": "Roronoa_Zoro", "ts": 1353633068000, "tid": 135206, "pn": 16}}', 1353633068000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p518765-math001', 'stk-user5944', 'MATH 001', 'info', '{"desc": "لا انكر عدم الحاجة لنواتات خان << رغم أني ما مرة رأيتها بس من كثرة الكلام عنها\n\nالمهم\n\nالاولد اكزام راجعته للميجر الأول وتعبت حالي في المذاكرة منه وفي النهاية شئ بسيط اللي جاني منه غذا ماكان صفر بالمئة\n\nالكلاس تيست الاخير للزعبي راجعت اكوزاته وكانت افكار صح 10/10 وجبت فل مارك\nوالميجر ان شاء بجمع اوراق الكلاس تيست وبحلها بفهم وبراجع الكوزات والكتاب خفايف (لأني هاضمة)\n\nوبكذا يكون ضمنت 95% من الميجر على كلام مدرسنا الدكتور أحمد الزعبي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/2-001/81789/12", "user": "user5944", "ts": 1262900059000, "tid": 81789, "pn": 12}}', 1262900059000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1293312-math001', 'stk-azoooozy', 'MATH 001', 'info', '{"desc": "يا ابوي تعوذ من ابليس , الاوريا عبارة عن حرب نفسية يسقط فيها اللي ماعنده عزيمة واصرار ومثابرة , شد على نفسك شوي وصدقني صدقني درجاتك النازلة مب عيب فيك ابد!!! , اردع لنفسك هل انت ذاكرت قبل الميجر بيوم يومين ثلاث ولا قبله باسبوعين ثلاث !!\n\nمحدثك جاب في اول ميجر له في الجامعة كان ميجر ماث 001 كنت احسبه زي اسئلة الكتاب اللي يحلها الدكتور في الكلاس وكنت اقول ايه سهالات يارجال وادخل للميجر انصدمت!!! كانت درجتي 6/20 !!!!!!!!!!!! وبعده الفزكس اتوقع كانت 9/20 وميجر2 كانت 3/20 في هالحدود!! لانه كان اهمال مني!!!\n\nصبرت واحتسبت وشديت على نفسي واستشرت اللي اكبر مني ونصحوني بالاولد اقزامز + مذكرة ايمن جيدة للمبتدئين\n\nدرجاتي “الزفت” كانت بسبب اهمالي واستهتاري وليس عيب فيني وفي استيعابي او “غباء” مني\n\nميجر2 للماث كان اصعب من ميجر1 اتوقع خذت 13 مدري كم كان باقي لي على النجاح! شديت حيلي وثابرت ودعيت الله ووفقني الله وجبت في الفاينل وارتفعت درجاتي لفوق الافرج بمراحل!!!!!! وعديت بسي+ وانا كنت اف !!!\n\nياحبيبي الغالي لاتتسرع باتخاذ قرارك انا وغيري وغيرك كثييييير جتهم نفسيات في الاوريا وكرهوا الجامعة , ياخي ليش تونا في البداية ليه تحكم عليها من اول شي , والجامعة ابد ابد مب صعبة زي مايقولون , تحتاج شوية مذاكرة وخفف من اللعب وتضييع الوقت\n\nوالله يوفقك وعقبال مانشوفك بالجبل ❤️\n\nتحياتي لك ❤️\n\nطالب210 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/152892/16", "user": "azoooozy", "ts": 1385311202000, "tid": 152892, "pn": 16}}', 1385311202000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1071595-math001', 'stk-ee211', 'MATH 001', 'info', '{"desc": "يختلف من طالب لطالب\n\nوانت وتجربتك , جيد تستفيد من تجربة غيرك وتاخد نصايح بس ما انصحك تطبق الي تقراه او تسمعه بالحرف 🙂\n\nانا عن نفسي 001 ما كنت اعترف بأي نوت وما كنت اذاكر الا من الكتاب وافهم اول بأول مع المدرس وقبل المياجر اذاكر الاختبارات السابقة ( تحصلها في موقع السنة التحضيرية ) وكنت جدا مبسوط ومرتاح ولله الحمد طلعت بقريد طيب\n\nاما 002 في البداية حاولت مع الكتب وحاولت افهم مع المدرس ( جاني مدرس سيء نوعا ما ) وصراحة كنت ضاااااايع في بداية الترم والحمدلله اني سحبت على طريقتي السابقة وجربت نوت خان ( خان هذا مدرس رياضيات للتحضيري ) وحصلت ضالتي في هذا النوت وطلعت بنفس قريد الترم الاول\n\nونصيحتي لك اهم شي تفهم الدروس اول بأول وتحل الواجبات وتحل اختبارات قديمة\n\nاما انك تعتمد في مذاكرتك على الكتاب او نوت مدرسك او نوت خارجي فهذا راجعلك وانا اشوف كلها جيدة\n\nوبالتوفيق\n\n🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/001-002/129223/13", "user": "EE211", "ts": 1343151515000, "tid": 129223, "pn": 13}}', 1343151515000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p139145-math001', 'stk-mr_fofo', 'MATH 001', 'info', '{"desc": "اوريا بس واللي من الجبل الله يحييه بادبه وان قل ادبه ترا بنزله من جبله\n\nساند مان\n\nانتبه لاتطيح من الجبل وبعدين تموت\nطيب احنا اوريا وكلنا فخر\nوبعدين اسئلة صعبه ولا سهله\nهذه شيء يخص الجامعه والاوريا\nيعني لاتكشخ انك في الجبل ترا قدامك هوا ووراك اوريا\nوبعدين هذه ساحة اوريات يعني اوريات@46@\nلا وكمان توك اوريا بالمنتدى ماكملت كم موضوع وجاي تهايض على الاوريات\nالله اكبر\nالله وين ايام ماكان يتجرأ على الكتابة الا الرجال\nلاحول ولاقوة الا بالله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-001-major-average/53888/9", "user": "Mr_Fofo", "ts": 1165507947000, "tid": 53888, "pn": 9}}', 1165507947000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p23518-math001', 'stk-user389', 'MATH 001', 'info', '{"desc": "شوف ياللي تتكلم عن خالد سيف الله\n\nانا اخذت ماث 001 ايام الاوريا مع خالد سيف الله\n\nترى الدكتور هذا درس قبلك اجيال قبل لا تولد انت و منهم اثنين من اعمامي و واحد من اخوالي\n\nانا جبت العيد معاه السمستر الاول لاني انا كنت منسم و لما طلعت النتيجة زي الزفت على طول قلت ان سيف الله افشل مدرس\n\nو سبحان من اعادني اليه الفصل الثاني\n\nالفصل الثاني لاحظت و الله تغير كبير جدا\n\nالسبب مش هو … السبب اني انا صرت اركز معاه\n\nو الله ملخص و لا حتى المسلماني يسوي زيه و شرح و اخلاق و الله !\n\nهو لك عليه اذا شاف واحد يتكلم و لا نايم\n\nلكن الشرح 100% ممتاز و يعطيك امثلة متدرجة الصعوبة و الله العظيم ان شباب قاعدين في آخر الصف و ما يتابعون و ما يخليهم يطلعون لين ما يفهمون الدرس كامل\n\nو بعد كل كويز اللي يجيب اقل من خمسة يستلمهم محاضرة داخلية سرية مغلقة وحده الله العالم ما الذي كان يدور خلالها\n\nيا اخي و الله طلاب الاوريا جاحدين ناكرين للمعروف\n\nالواحد منهم يفكر انه اذا طلع الجامعة بيحصل نفس مدرس الرياضيات المصري اللي مشمر اكمامه طول الحصة و اذا نمت طول السنة تعال قبل الاختبار النهائي بيوم و حط في يده الفين ريال و خذ الاسئلة\n\nيا شباب لازم تعرفون ان حالتكم بعد ما دخلتم الجامعة تغيرت تماما\n\nما تغير بس من ناحية حرية دخولك الحصة او الخروج\n\nو ما تغير بس من ناحية قربك من الراشد و كل ما طقت براسك رحت تدور فيه\n\nو ما تغيرت من ناحية ان المدرس ما بيوقفك قدام مكتب المرشد\n\nلكن تغيرت ايضا من ناحية المجهود اللي تبذله في دراستك\n\nالجامعة اعطتك مميزات عن المدرسة\n\nو بالمقابل حرمتك من مميزات اخرى\n\nفان لم تستفد من ما قدمته لك فلا تطالبها بما هو ليس من واجباتها (و اعني بذلك معاملتكم كالاطفال)\n\nتوقعوا المزيد من القسوة كلما تسلقتم الجبل … كلمة اخيرة لكم يا اوريات\n\nسفح الجبل يتسع للكثير\n\nلكن قمته لن تتسع لهم جميعاً …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-is-worse-than-death/21928/9", "user": "user389", "ts": 1054809603000, "tid": 21928, "pn": 9}}', 1054809603000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p607576-math001', 'stk-mr.abdullah', 'MATH 001', 'info', '{"desc": "دع المقادير تجري في أعنتها === ولاتنم إلا وأنت خالي البالي\n\nما بين غمضة عين والتفاتها === يغير الله من حال إلى حال ِ\n\nـــــــــــــــــــــــــــــــــــــــ\n\nالله يستر بس ويوفقنا يارب ياغفار\n\nياخي انا المرة الثانية االلي انصدم فيها >> لاتخافون مافيه اصابات ( زاحف في وقت لايمكن ان يضحك فيه اي احد )\n\nالميجر الاول حليت 15 ضامنا >> طلعت وجبت 11\n\nالثاني حليت 16 سؤال >> طلعت وجبت 12\n\nوش الحل والله متوهق المشكلة ان الدكتور يقول بعطيك الكلاس وورك على حسب درجاتك بالميجر\n\nلا واللي قاهرني اني حال كل الهومووركات والاونلاين ماشي فيها وكويزاتي يعني مقبولة ( اكثر من 7 وفوق ) لكن فيه تقريبا 3 او4 كويزات جبت فيها 4\n\nلكن اقول الحمدلله على كل حال\n\nويارب توفيقك … اللهم اكتب لي الخير أينما كان", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-001/88158/14", "user": "Mr.abdullah", "ts": 1273955969000, "tid": 88158, "pn": 14}}', 1273955969000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p521971-math001', 'stk-mr-3b0d', 'MATH 001', 'info', '{"desc": "على اني ما ذاكرت زيين ابداا\n\nوما خلصت المنهج الا اليوم بعد المغرب>>2.7&2.8 تمشيه حال\n\nوقراءة سريعة للاولد اقزام\n\nوكنت متوقع اني بجيب العيد\n\nلكن الحمد لله الاختبار كان سهل واسهل من المتوقع كثييير\n\nاتوقع اجيب 14 >>مع اني على مذاكرتي ما استاهل ابدااااا ولا 8\n\nوبالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/82106/15", "user": "mr-3b0d", "ts": 1263237145000, "tid": 82106, "pn": 15}}', 1263237145000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p523322-math001', 'stk-equal', 'MATH 001', 'info', '{"desc": "ياعزيزي نحن لا نحاول ان نحبطك او اي شيء من هذا القبيل … لكن المنطق والمعطيات التي لدينا تبشر بفاينل صعب نوعا ما … عموما انسى الميجر هذا واللي قبله وابدأ من اليوم عندك اسبوعين استلم الشباتر وركز على الثالث … والفاينل عليه 36 درجة حاول تحصل على 30 منها والامور ماشية … ترا كلنا في الهوا سوى … نعم الاختبار سهل لكن الخطأ موجود … والله يوفق الجميع …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/82106/57", "user": "equal", "ts": 1263481155000, "tid": 82106, "pn": 57}}', 1263481155000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p536800-math001', 'stk-eng.3booodii', 'MATH 001', 'info', '{"desc": "والله شوف ترا صح إنك بتعيد 001\n\nلكن صدقني بيكون لها تأثير نفسي حلو عليك الترم الجاي\n\nلأنك إن شالله تجيب فيها بالقليل b+ وبتحس إنك ماشي\n\nلكن لازم تذاكر تمام وتحل مسائل حلو\n\nبالنسبة لـ 002 بالصيف … ترا المادة سهله باستثناء شبتر 6 يبغاله فهم تمااام\n\nوترا 002 بالصيف يجي منه لكن لازم تذاكر يوميا مزبوط لأنك لو ما ذاكرت ترا بتروح زلطة\n\nالمنهج فيه معلومات ويحتاج له مذاكرة أول بأول وتمشي زي الفستق\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-001/83060/8", "user": "eng.3boOodii", "ts": 1265295121000, "tid": 83060, "pn": 8}}', 1265295121000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p620814-math001', 'stk-user4636', 'MATH 001', 'info', '{"desc": "^^^^^^^^^^\nلا لا صاحب البيت اصلا مسوي عرض البيت مع الاثاث كاملp:\n\nعزيزي\n\nانا بالاوريا ماث 001 و002 كلها c 😦\n\nيعني اسوأ منك\n\nلكن دخلت هندسه ميكانيكيه وللحين الحمد لله ماشي الترم الماضي عديت الماث 101 بc برضو\n\nمدري شيبي السي ناشب لي 😦\n\nوالماث هذا الحمد لله وضعي افضل ممكن اعدي ب c+\n\nوالفيزيا عالحفه صراحه عديت بd\n\nلكن الحمد لله اهم شي ماخذت f واهم شي برضو ماخذت وورننق\n\nفا من ناحية صعوبه لو تدخل الهندسه وبتذاكر صدقني ماراح تكون صعبه مره\n\nلكن بنفس الوقت مو سهله 🙂\n\nوبالاول والاخير اذا تحس انك فعلا بتبدع امش بالاداره على طول\n\nورواتبها ترا مو شينه ابد!!\n\nلو ابدعت فيها وجبت معدلات ممتازه جدا صدقني بإذن الله بتحصل وظيفه وبرواتب تعجبك\n\nالقاعده اللي لازم تمشي عليها باختيار التخصص\n\n((ادخل التخصص الي انت تحبه وبتبدع فيه))\n\nتحياتي 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/89245/6", "user": "user4636", "ts": 1275508156000, "tid": 89245, "pn": 6}}', 1275508156000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p464994-math001', 'stk-user2781', 'MATH 001', 'info', '{"desc": "دخلت ع الاختبار هذا\n\nhttp://www.kfupm.edu.sa/pypmath/pages/exam001/T081/Math001_e1_081.pdf\n\nالي هو الاختبار الاول في الترم الاول حق الدفعه حق السنه الي راحت\n\nوالله اشياء مررره سهله\n\nمستغرب والله\n\nع دفعتنا كانت هذي\n\nhttp://www.kfupm.edu.sa/pypmath/pages/exam001/T061/Math001_E1_061.pdf\n\nاصعب بشوي\n\nبس تلاحظ نفس الافكار\n\nيهني تذاكر المنهج حقك وتحل 3 او 4 اختبارات قديمه = A+\n\nوشوفة عينك يقولك من وين يجيبون السؤال\n\nوإذا الاسئلة صعبه = الافريج اقل\n\nفتصير القريدات اسهل ،،\n\nبعدين لا درست بتفهم قصدي تمام", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/77931/4", "user": "user2781", "ts": 1254094026000, "tid": 77931, "pn": 4}}', 1254094026000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1429825-math001', 'stk-madridista', 'MATH 001', 'info', '{"desc": "انا دخلت الجامعه ماعرف اجمع كسرين مع بعض … الان بالجبل ولا كورس ماث اخذت فيه اقل من B\n\nوايضا اذاكر بقراءة الدرس الذي كتبناه\n\nالماث مو انجلش ولا اسلامي عشان تقراه… الماث تطبيق، قد ماتطبق وتتمرن قد ماتتحصل بدرجاتك\nانا رسبت بماث 001 وندمان جداً اني اخذت صيفي بسببه… نوتات خان كويسه، حل كل تمرين بدوون ماتشوف الحل… اذا مره ماعرفت كيف تحلها (بعد محاولات عديده مو مجرد تناظرها وتستسلم) شوف الحل واعرف وين خطأك فيه (واضمن لك بعد ماعرفت خطأك بنفسك مستحيل تنساه ابداً ابداً)\nانا كنت نفسك بالضبط … احس أنك انا قبل سنتين ( الماث الصعب ودرجاتي السيئه! )\nحتى كنت أقول نفسك (ابي اروح itc هرباً من الماث) … لكن صبرت وتدربت والحمدلله انا سفمور الحين …\n\nالزبده الارتباك والضياع اللي انت فيه طبيعي، توك جديد على الجامعه ونظامهم … اهم شيء تحل 3 اولد اقزام اقل شيء قبل الميجر.\n\nوالمعذره على الاطاله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170275/2", "user": "Madridista", "ts": 1444182289000, "tid": 170275, "pn": 2}}', 1444182289000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p122489-math001', 'stk-user1526', 'MATH 001', 'info', '{"desc": "ياهلا بشباب الأوريا\n\nالأسئله سمعت أنها بين المتوسط والصعب …\n\nلكن المريح هو أن الأختبار الأول فقط عليه 15 %\n\nطبعا الأفضل لكل طالب أن يحرز فوق المعدل …\n\nعموما المعدل غالبا مايكون نسبته 58 - 60 % من 15%\n\nأي مايقارب 8 - 11 من 15 …\n\nعلى العموم … يا أوريات … ماعليكم …\n\nلاتنسون إنه هذا أول اختبار رسمي لكم في الجامعه … & … وأول اختبار باللغة الإنجليزيه … & … وأفكار جديده على أقدمية المواضيع والتي مرت معكم من قبل في الثانويه أو المتوسطه …\n\nالله يوفقكم جميعا … واللي نقص قدامه فرصه في الميجر الثاني والفاينل …\n\nيعني قدامك A+ بالراحه … لأنه A+ تبدأ من 91 - 92 الى 100 …\n\nبالتوفيق … 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math001-major-exam-i/52622/4", "user": "user1526", "ts": 1160315662000, "tid": 52622, "pn": 4}}', 1160315662000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p122617-math001', 'stk-user786', 'MATH 001', 'info', '{"desc": "يا جماعه\n\nلازم تتأقلمون على هذي النوعيه من الاسئلة\n\nترى البترول اغلبها من هذا النوع الى حد ما\n\nوتراكم في اول الطريق والاختبار ما عليه الا 15 في الميه\n\nيعني ولا شي بالنسبة للمادة\n\nيمديك تبدع في الكوزات والاختبار الثاني والهوموركات والفاينل\n\nوسعوا صدورك ولا تحزنوا وتراكم في اول المشوار", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math001-major-exam-i/52622/11", "user": "user786", "ts": 1160376163000, "tid": 52622, "pn": 11}}', 1160376163000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1458616-math001', 'stk-mohammed18', 'MATH 001', 'info', '{"desc": "والريسايتيشن اول ماينزل الدكتور اسئله على البلاك بورد احلها هذي شبه اسبوعيا . بس النوت\n\nلا انا قصدي اني اذاكر الدرس اول ما اخذه وبعدها اخذ عليه تمارين من الكتاب . واول مانخلص يونيت ون فرضا امسك اولد اقزام . والريسايتيشن تنزل بداية كل يونيت بس فيها اكثر من يونيت الظاهر . فا بخليها اخر شيء اذا اكتملت الدروس", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-001/174806/5", "user": "Mohammed18", "ts": 1474708641000, "tid": 174806, "pn": 5}}', 1474708641000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1405952-math001', 'stk-mohammed780', 'MATH 001', 'info', '{"desc": "الميجر مو بالكلاس\nالميجر يكون اغلب الطلاب بمبنى 54 وفي عدد قليل “احيانا” بمبنى 59 بالعادة بعد المغرب\nاما الانقلش بيقولون لكم بوقتها مو الحين وبالعادة يكون الرايتنق واللسننق بكلاس الثالث والرابع من يوم دراسي عادي والفاينل يكون بعد المغرب يحددونه بعدين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/166330/2", "user": "mohammed780", "ts": 1413661332000, "tid": 166330, "pn": 2}}', 1413661332000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p731622-math001', 'stk-user7691', 'MATH 001', 'info', '{"desc": "احم احم\n\nو الله تبغـون الصـراحـة أنا يمكن أزفت واحد في العالم في الدرجات حقت الكلاس تست و الهومووركات\n\nبس شديت حيلي في الميجـر ذا ، وامس من المغرب إلى الساعة 12:00 الليل و أنا اذاكر المياجر القديمة ، الأول و الثاني و الرابع و الثالث اطقطق عليه !!\n\nو الحمد لله فتح علي الله فتح غير طبيعي الحمد لك يا رب\n\nاعلمكم بالتفاصيل بعدين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/97708/14", "user": "user7691", "ts": 1288869341000, "tid": 97708, "pn": 14}}', 1288869341000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p731792-math001', 'stk-user6810', 'MATH 001', 'info', '{"desc": "بيدك تجيب c برااااحه\nبس لازم تشد حيلك وتكتشف الخطا في المذاكره اللى سويتها في هذا الاختبار\n\nاسمع الكلام وراح تدعيلي ان شاء الله\n\n1)اقرا الدرس على السريع قبل ما تروح المحاضره يعني اسم الموضوع ومقدمه على الدرس\n2)لا تتاخر على المحاضره وركز مع الدكتور\n3)لما ترجع من المحاضره اقرا الكتاب بتمعن وسيبك من كل النوتات والخرابيط لو النوت كتبه دكتور فالكتاب كتبه مجموعه دكاتره ومجموعه مراجعين ومصححين\n4) حل على قدر ما تقدر اسئله الكتاب الفرديه وتلاقي اجوبتها في نهايه الكتاب\n5)حل اسئله الرستيشن\n6)اي سوال ما تعرفه راجع الدكتور في الاوفس اور\n7)حل اسئله الواجب بنفسك\nاذا سويت كل هذا ابتداء من الان راح تقدر ان شاء الله براحه تجيب في ميجر 2 درجه فوق 17 وفي الفاينل 22 من 30 ومع الكلاس ورك 13 من 20 (ما اعرف تقسيم الدرجات بالضبطوفي عشره ما اعرف حقت ايش بس اسوا الحالات انك تاخذ 0 من العشره)\n6+17+22+15=60 من 100 C+\n\nوترى ما نقصك الين دحين الا 14 درجه من 100 يعني بيدك ان شاء الله 86\n\nموفق ان شاء الله\nتم كتابه كلمه “كتاب” باكبر خط لاهميته", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/97708/38", "user": "user6810", "ts": 1288887335000, "tid": 97708, "pn": 38}}', 1288887335000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p731961-math001', 'stk-user4492', 'MATH 001', 'info', '{"desc": "يعني اللي يحس انه جايب اقل من 15 ينسحب من الجامعة من الحين\n\n+\n\nياشباب اللي حس انه جاب العيد بالاختبار انصحه ينسحب من اللحين لان الافرج راح يكون فوق 15\n\nآلحمد لله ڪآن آختبآر حلۉ ۉسسسهل … ۉبآلتۉفيق للجميع …\n\nبس حبّيت آعلّق على بعض آلردۉد … لۉ آني حآل هۉمۉۉرڪ آۉنلـآين بدآل ۉقت آلرّد ڪآن آحسن =) …\n\nطبعآ ً مآ آتڪلم عن نفسي آلحمد لله درجتي ڪثير ممتآزة …\n\nآتڪلم عن آلشبآب آللي جآبۉآ درجآت نآزلة … آن شآْء آلله ربي يعۉّضڪم خير …\n\nآۉلـآ :\n\nهذآ آۉل ميجر ۉمآ تقدر تقۉل آني جبت درجة نآزلة خلـآص بسحب من آلجآمعة …\n\nثآنيآ :\n\nعليه 20 درجة من آصلآ 100 درجة … ۉقدآمڪم تعۉيض في آلميجر (2) ۉآلفآينل غير آلڪلآسس ۉۉرڪ …\n\nشدّۉآ حيلڪم ۉلآ عليڪم من آلمثبّطين … حآولوآ آنڪم تصحّحون آخطآئڪم اللي ارتڪبتوهآ بالميجر (1) … !\n\nبــــ آلتۉفيق 🌹\n\n=)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/97708/47", "user": "user4492", "ts": 1288903803000, "tid": 97708, "pn": 47}}', 1288903803000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p733026-math001', 'stk-mathematical', 'MATH 001', 'info', '{"desc": "يا شباب الاسئلة سهلة نوعا ما يعني على نفس مستوانا\nلكن سبب الاخطاء في الاختبار هي عدم ممارسة الرياضيات\nولو تلاحظون ان في كثير من الناس تعرف طريقة الحل\nلكن تخطى في اشياء بسيطة مثل الاشارة او حذف رقم او نسيان التربيع\n\nوالسبب باعتقادي انه احنا ما نحل مسائل الا الهوموركات وايام الاختبارات\nواذا تريدوا ما تخطؤوا في مثل هذه الاشياء البسيطة عليكم بحل المسائل\n\nوبنسبة لي طلعت من الاختبار توقعت اني اخذ 20 من 20 لكن بعد المراجعة وجدت عندي\nاخطاء بسيطة لكن ما ينفع كان مهما كان الخطأ بسيط فالخطأ خطأ", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/97708/71", "user": "mathematical", "ts": 1289057011000, "tid": 97708, "pn": 71}}', 1289057011000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p535331-math001', 'stk-moataz', 'MATH 001', 'info', '{"desc": "الاختبار كان متوسط\n\nلكن انا شايف ناس ذبحونا بالسنة اللي فاتت !! مافيه مقارنة بين اسئلة السنة الماضية والسنة هذي\nالسنة هذي اصعب !!!! مايسبب لي ازمة الا اذا جيت حليت الاولد اكزامز ولقيت انها تافهه\nفادخل الاختبار وانا راسي كبير على اساس اني فاهم كل شي كيف لا وانا لقيت الاولد اكزامز تافهه !!\nومع كم سؤال يلحس المخ في المياجر، اتمنى اني كنت من طلاب السنة الماضية!!\n\nلذلك رجاء بدون تهويل وتزييف ياطلاب 081 082 ، اسئلتكم اسهل بمراحل، ولكن دفعتنا تتميز بالدفرة المفرطة\nنظراً لكثرة المقبولين المتميزين ولنا موعد مع مواد 101 لنثبت ذلك\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/82999/32", "user": "Moataz", "ts": 1265158407000, "tid": 82999, "pn": 32}}', 1265158407000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p535523-math001', 'stk-_1148', 'MATH 001', 'info', '{"desc": "الاختبار كان متوسط\n\nلكن انا شايف ناس ذبحونا بالسنة اللي فاتت !! مافيه مقارنة بين اسئلة السنة الماضية والسنة هذي\nالسنة هذي اصعب !!!! مايسبب لي ازمة الا اذا جيت حليت الاولد اكزامز ولقيت انها تافهه\nفادخل الاختبار وانا راسي كبير على اساس اني فاهم كل شي كيف لا وانا لقيت الاولد اكزامز تافهه !!\nومع كم سؤال يلحس المخ في المياجر، اتمنى اني كنت من طلاب السنة الماضية!!\n\nلذلك رجاء بدون تهويل وتزييف ياطلاب 081 082 ، اسئلتكم اسهل بمراحل، ولكن دفعتنا تتميز بالدفرة المفرطة\nنظراً لكثرة المقبولين المتميزين ولنا موعد مع مواد 101 لنثبت ذلك\n\nبالتوفيق\n\nهذا اللي جالس اقوله من اليوم وهذا كلام اغلب اوريتنا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/82999/33", "user": "_1148", "ts": 1265183452000, "tid": 82999, "pn": 33}}', 1265183452000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p535783-math001', 'stk-dark_prince', 'MATH 001', 'info', '{"desc": "الاختبار للأمانة كان صعب واللي يقول غير كذا ينتظر النتيجة ويشوف…!!\n\nانا الحمد لله احس اني جاوبت يعني تقريبا اربع اسئلة اللي كانت تعجيزية نوعا ما اما الباقي من سهلة الى متوسطة\n\nالحمد لله السمستر الأول عدا على خير وان شاء الله تكمل في السمستر الثاني يارب…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/82999/39", "user": "Dark_Prince", "ts": 1265202931000, "tid": 82999, "pn": 39}}', 1265202931000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p878354-math001', 'stk-mo7amed', 'MATH 001', 'info', '{"desc": "لا تخاف بتبدأ من الصفر\nفي ماث 001 أول شابتر بيكون مراجعة على أساسيات الماث\nأهم شي تكون مهتم بالمادة وتستفيد منها\nذاكر وحل أسئلة على قد ما تقدر بإستمرار وبتدخل المياجر وإنت مرتاح إن شاء الله\nكلام المحبطين لا تهتم فيه وبتجي الجامعة وبتشوف إنه أغلبه خرطي ومبالغ فيه 🤠", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/110290/22", "user": "Mo7amed", "ts": 1312161969000, "tid": 110290, "pn": 22}}', 1312161969000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p622930-math001', 'stk-chemistry.eng', 'MATH 001', 'info', '{"desc": "اذا طانت المعادلة فيها مجهولين بس … فأنصح بحلها بواسطة الإليمينيشن ميثود أو السبستتيوشن …\n\nأما من ناحية انك عندك معادلة من الدرجة الثالثه وثلاث مجاهلي مثلا … فأنت مثلا وصلت للنقطة اللي تذكرتها فأنصح بأنك ترجع المصفوفه لمعادلة من جديد وراح يكون سهل التعامل معها كثييييير\n\nتقبل تحياتي 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/001-002/87959/117", "user": "Chemistry.Eng", "ts": 1275763390000, "tid": 87959, "pn": 117}}', 1275763390000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p762573-math001', 'stk-user5535', 'MATH 001', 'info', '{"desc": "لا يا Brave … أنا أخالفك الرأي\nلو قلنا إنه انقبل في البترول المفروض في الصيف يبدأ يستعد بالمذاكرة\n\nو من وجهة نظري كطالب ضعيف في القدرات و ( يمشي حاله ) في الانجلش أشوف إنه في الصيف يذاكر ماث 001 إلى شابتر 2.8 و يقوي لغته الانجليزية عامة فقط\n\nو في الأخير تبقى و جهة نظر و هذا اللي راح أسويه لو رجع فيني الزمن", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/100628/6", "user": "user5535", "ts": 1294903466000, "tid": 100628, "pn": 6}}', 1294903466000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p737468-math001', 'stk-postmaster', 'MATH 001', 'info', '{"desc": "السلام عليكم : حبيبي أنا عشت نفس مشكلتك تقريبا في أول ميجر للماث 001 جبت 6 من 22\nلكن بصراحه ما اهتميت في الماده بالقدر الكافي يعني ما ذاكرت الا قبل الميجر يمكن باربع ايام و ال 6 درجات هذي سببها شوية اهمال وغلطات بسيطه\n\nالماده والله صعبه والله يعينك لكن مافيه شئ صعب إذا كان فيه اهتمام يعني لو بذلت مجهود كبير شوي بتجيب درجه حلوه روح للمكتبه اللي عند السكن واشتري من عندهم الاولد اكزام وعلى فكره الاولد اكزام اهم شئ يعني مهم جدا جدا اذا تبغى درجه حلوه ايضا الهومورك والريسيتيشن لازم تحلها انت بنفسك ولازم تتأكد من الحل وصدقني ياعسل بجيب درجه حلوه بإذن الله أنا في الميجر الاول جبت 6 لكن في الميجر الثاني والله ذاكرت لمده اسبوعين تقريبا وذاكرت الاولد اكزام والريسيتيشن والهوموركات والحمدلله جاء الميجر الثاني وجبت 18 ونفس الطريقه هذي سويتها في الفاينال والحمدلله جبت b اعتقد انها درجة حلوه\n\nتأكد ان ربي مايضيع تعبك وشد حيلك والماده مو سهله والماده محتاجه مذاكره\nكلامي هذا كله تجربتي أنا وكلامي كله وجهة نظر فقط والله يوفقك ويوفق الجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/98032/17", "user": "postmaster", "ts": 1290195784000, "tid": 98032, "pn": 17}}', 1290195784000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p519877-math001', 'stk-pyp_math', 'MATH 001', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nالسلام عليكم و رحمة الله وبركاته …\n\nعزيزي طالب السنة التحضيرية في جامعة الملك فهد للبترول و المعادن… فإنه لا يخفى عليك مدى اهمية هذه السنة لانها تعتبر اللبنة الاساسية في حياتك الجامعية وكلما كان مستواك العلمي متميزاً وتحصيلك كبيراً في Math 001 كان لك هذا بمثابة القاعدة القوية والصلبة في حياتك الجامعية في الجبل وستجد اغلب مواد الرياضيات هناك مثل Math 102 ,101 تعتمد بشكل كبير على مدى قوتك في Math001 .\n\nوها قد اقترب موعد الاختبار الثاني في الـ11 و الـ12 من شهر يناير 2010. وهو يعتبر بحق فرصة لجميع الطلاب .\nفبالنسبة للطلاب المتميزين و المجتهدين فهو فرصة لتأكيد هذا التميز و الاستمرار عليه .\nو بالنسبة للطلاب الذين لم يوفقوا في تحقيق درجات جيدة في الاختبار الاول ، فهذه فرصة ذهبية لن تعوض فالاختبار يزن 22% اي بما يعادل قرابة ربع الوزن الكلي للمادة . فالله الله بمذاكرة الكتاب اولاً بأول و من ثم حل و مراجعة الاختبارات القديمة (( اضغط هنا )).\n\nو احب ان انبه ايضا على اخذ هذه السنة مأخذ الجدية لانها سنة فاصلة في حياة الطالب ، و من الجد في ذلك ان يأتي الطالب للاختبار و هو مستعد … و من الاستعداد :\nاتباع التعليمات الموزعة على الطلاب في Exam Ticket او Seat Ticket .\nبحيث يكتب الطالب اسمه , #ID#, sec بدون خطأ.\nوان لا يترك اثرا عندما يريد ان يمسح اجابة ( و ذلك بإستخدام ممحاة جيدة … ) .\n\nhttp://www.up-00.com/s3files/2a942223.bmp\n\nhttp://www.up-00.com/s3files/8hb42881.bmp\n\nواخيرا ارجو من الله العلي القدير ان يوفقكم في الاختبار القادم .\n\nاخوكم /\nد.خالد الشمري .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/81996/1", "user": "PYP_Math", "ts": 1263042938000, "tid": 81996, "pn": 1}}', 1263042938000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p769593-math001', 'stk-m_o_h_a_n_d', 'MATH 001', 'info', '{"desc": "الحمد لله كنت أبي 5 درجات فقط علشان أضمن النجاح وذاكرت الميجر الأول فقط لا غير وبصراحة الأسئلة كانت صعبه جدا وحتى لو اجتهدت أكثر فيه أسئلة ما قد شفت نفس طريقتها … ولكن ولله الحمد مع الحل والترقيع والقس والحظ جبت أضعاف الدرجة اللي كنت أبيها … وبصراحة اليوم ما قابلت أحد يقول الإختبار سهل ( بالنسبة للمياجر الإختبار نااااااااااااااااار ) … وفق الله الجميع وأنصح بعض الأخوه أن يخلوا أملهم بالله قووووي ويتذكرووون أن فيه الآلاف عادوا وما زالوا يعيدون ولا يقطع الأمل لمجرد رسوب في مادة في أووووول سمستر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/101136/38", "user": "M_O_H_A_N_D", "ts": 1295711459000, "tid": 101136, "pn": 38}}', 1295711459000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1484209-math001', 'stk-abdullah2015', 'MATH 001', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته\n\nدرجة النجاح عادة تكون 60\n\nالكورس كله حسب ما أتذكر توزيعه كالآتي:\n\n20 % ميجر أول\n20 % ميجر ثاني\n18 % كلاس وورك\n6 % أونلاين هوموورك\n36 % فاينل\n\nأنت تقول مجموعك في الميجرين 27\n\nوالكلاس وورك تقول درجاتك أفرج، يعني لنفرض إنها 10 من 18\n\nالأونلاين هوموورك أفترض إنك جبتها كاملة 6 / 6 …\n\nفيصير مجموعك (الافتراضي) قبل الفاينل 27 + 10 + 6 = 43\n\nيعني محتاج (تقريبًا) تجيب 17 من 36 في الفاينل عشان تنجح\n\nعادة فاينل الماث يكون أفرجه حول ال24 من 36، فإنك تجيب 17 من 36 تعتبر سهلة نسبيًا\n\nعمومًا شد حيلك في اللي جاي والله يوفقك 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math001/178235/2", "user": "Abdullah2015", "ts": 1512413930000, "tid": 178235, "pn": 2}}', 1512413930000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p924549-math001', 'stk-a_dulaziz', 'MATH 001', 'info', '{"desc": "الأفرج الي يحدد القريد هو الأفرج النهائي لكل الدفعه وغالبا يجي 60 أو حولها وهو مجموع أفرج الميجرين + الكلاس ورك + أفرج الفاينل\n\nوكل ما صار أفرج الكلاس بالميجرين أعلى من الأفرج العام يخذون الطلاب زياده درجات بالكلاس ورك يعني بيستفيد صاحب سكشن الدوافير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/114310/18", "user": "A_DULAZIZ", "ts": 1319407219000, "tid": 114310, "pn": 18}}', 1319407219000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p318642-math001', 'stk-user3166', 'MATH 001', 'info', '{"desc": "الزعبي وما ادراك ما الزعبي << ذكريات بداية الاوريا ههههههههههههه << احلى ياللي ذكريات خخخخخ\n\nالمهم 🙂\n\nالزعبي… هذا عادي يا أخي …انا يوم قالوا مصيبه هالمدرس… قلت رحت فيها 😦\n\nبس طلع ماث 001 سهل… يعني بدون الزعبي اعتمد على الكتاب واقصد الاسئله اللي باخر كل سكشن …مع الهوم وورك طبعا\n\nوقبل المياجر اهم اهم اهم اهم اهم اهم شئ تحل الاولد قزام ترا مهم مهم مهم مهم …الخ < ههه\n\nواذا ما فهمت من الكتاب فيه نوت ايمن << انا ما استخدمته لا بـ001 ولا 002 بس الشباب يمدحونه 🙂\n\nواذا ما فهمت احضر مع مدرس ثاني < على انها صعبه شوي 😦 بس ان شاء الله تنظم وقتك وتقدر 🙂\n\nطبعا الحلول اعلاه ابدأ فيها بالترتيب اذا ما نفع الاول رح للثاني وهكذا 🙂\n\nطبعا نصيحه اذا تبي تسأل الزعبي قل له دكتوور الزعبي وشف شلوون يجاوب يصير فنان هههههههههههههههه\n\n🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/66815/11", "user": "user3166", "ts": 1224088519000, "tid": 66815, "pn": 11}}', 1224088519000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p331833-math001', 'stk-karam', 'MATH 001', 'info', '{"desc": "يابن الحلال انا اعلى درجة جبتها في الفيزيكس 6 من 10\nوالكثير 2,3ومرة خذت 0\nوالماث اذكر اني خذت مرة وحدة 9\nوالباقي تتراوح من 4الى 7\nوالحمدلله عديت الفيزكس بي بلس والماث001سي\nو002عدته اضطرارا صيفي وباقي لي درجة على الايه خذت طبعا بي بلس\nوانا الحين ماخذ التخصص الي ابيه ولله الحمد\nفيعني لاتشيل همها انت ماعليك الا تذاكر واهمشي تحل مسائل والهوموركات\n\nويتعدي ان شاء الله\nوادع ان الله يسهل عليك\nونصيحتي لاتسحب\nلانه جتني نفس الوساوس انا غبي هم اذكياء مااقدر اكمل\nلكن بترتاح عقب\nوعسى الله يوفقك ويعينك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/kfupm/67737/4", "user": "karam", "ts": 1226520253000, "tid": 67737, "pn": 4}}', 1226520253000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p612196-math001', 'stk-l7ani', 'MATH 001', 'info', '{"desc": "أخوي أنا أبي أتكلم لك من واقع تجربتي الشخصية\n\nأنا لما كنت أوريا كان المدرس حقي من جنوب أفريقيا وأنا أساسا متعقد منهم عندهم اللهجة صعبة بالنسبة لي وما قدرت أفهم عليه وإلى يومك هدا ما أفهم على أي واحد من جنوب أفريقيا\nوالله بلاني إني أخد ماث 001 و 002 كلهم عند مدرسين من جنوب أفريقيا\nفي كورس 001 كنت جايب العيد كان في الهوم وورك والا الكويزات ولا تنسى المياجر بعد\nوالله العظيم كانوا كلهم تحت الآفرج فتحطمت وقعدت أشكي للطلاب اللي معاي في نفس السكشن وقعدت ألوم المدرس بحجة إنه ما يعرف يشرح ولا يعرف كيف يوصل المعلومه فضحكوا علي الشباب وقالوا لا والله هو من أفضل المدرسين وهو شرييح ولكن الظاهر إنك إنت اللي ما تفهم\n\nوحزت في خاطري هالكلمه وقعدت أقول بيني وبين نفسي هل صحيح إني ما أفهم\nبس قلت لو إنك ما تفهم ماكان قبلتك هالجامعه العريقة\n\nفتحديت الشباب وقلت لهم إني راح أعدي هالكورس بدون مساعدة المدرس أو أي شخص آخر\nفقالوا مستحيل إنت يبغالك على شان تعدي الكورس لازم تجيب فل مارك تحسبا للآفرج\nفبدأت رحلت التحدي مع الماث وكنت ما أداكر إلا من الكتاب ولما أخلصه أحل المسائل اللي في نهاية كل تشابتر\nولله الحمد والمنه عديت الكورس وكانت درجتي قريبه إلى حد كبير من الفل مارك مما أدى إلى إنبهار كل الطلاب مع المدرس\n\nفأنا أقولك وأنا أخوك ما فيه شي مستحيل\nوحط في بالك انك تستطيع أن تهزم المستحيل\nحط في بالك\nI Can Do it\n\nعيش المغامرة وحول تفكيرك من إنك تدرس على شان تنجح إلى إنك تدرس و تتحدى كل الكورسات مهما كانت\n\nولا تنسى روح التحدي مطلوبه في هالجامعة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/88362/6", "user": "l7ani", "ts": 1274454076000, "tid": 88362, "pn": 6}}', 1274454076000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p494992-math001', 'stk-user6147', 'MATH 001', 'info', '{"desc": "شف يا اوريا\n\nانا درست ماث 001 مع الاستاذ الياس الشاويش الله يذكرهـ بالخير\n\nجبت بالميجر الاول 10 والثاني 10 والكلاس وورك مع ان درجات الكويزات عندي كانت مثلكـ واردى بعد الا انه والله ما قصر ودفنا كلنا… اعطاني 14\n\nالحين مجموع درجاتي 34 والمطلوب للنجاح 53 على ماذكر\n\nطبعا ما راح يعطوكم درجات الفاينل … على طوول يعطوكم القريدات\n\nوالحمد لله عديت بـ c\n\nيعني لا تخاف تتيسر ان شاء الله والشاويش دائم يحب يعقدها بدايه السمستر عشان يخوف الطلاب لكن بالاخير راح يدفكم ويتساخل معاكم في الكلاس ووركـ حتى الهوموركات بيقولكم في نهايه السمستر اللي جاب 7 هوموركات او اكثر راح اعطيه درجه الهومورك كامله\n\nيعني تعوذ من بليس ولا تخاف وانا اقولكـ انكـ ناااجح من الحين باذن الله\n\nواذا عندكـ اي شي تعال عل الخاص\n\nتحياااتي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/80248/5", "user": "user6147", "ts": 1258589233000, "tid": 80248, "pn": 5}}', 1258589233000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p359328-math001', 'stk-user5114', 'MATH 001', 'info', '{"desc": "كيفكم اورياااااااااااات وكيف الاختبارات معاكم\nالمهم وماابي اطولها عليكم لان قدامكم اختبارات\n\nانا ابيكم تقولون الى وشو افضل شي لمذاكرة math 001\nمن الكتاب او من الدفتر او من مذكرة ايمن\n\nنصايحكم شباب ومو طولو في الرد ياشباااااااااااااااااااااااااااااب المستقبل 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-001/70012/1", "user": "user5114", "ts": 1233533892000, "tid": 70012, "pn": 1}}', 1233533892000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p359334-math001', 'stk-user4647', 'MATH 001', 'info', '{"desc": "العفو اخوي\n\nغريبة تشوف شي انا ما اشوفه\n\nانا مرتاح لمذكرة ايمن لانه يجيب كل فكرة في بالك\n\nبس لو تذاكرها لحالها منت فاهم شي\n\nلازم تاخذلك old exams محلوله وتقعد تحلهم او تشوف الحل وراح تفهم ان شاء الله\n\n(كل هالكلام بوجهة نظري )\n\nيعني انا ارتاح لما اذاكر كذا يمكن في ناس ثانين يرتاحون بمذاكرة الكتاب . او الدفتر\n\nوشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-001/70012/4", "user": "user4647", "ts": 1233534884000, "tid": 70012, "pn": 4}}', 1233534884000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p359342-math001', 'stk-m.s2008', 'MATH 001', 'info', '{"desc": "بصراحه شباب انا ذاكرت في ميجر ون مذكره ايمن وجبت العيد :d\n\nوفي ميجر الثاني مذكره خان وجبت العيد :d\n\nفقررت في الفاينل اذاكر مذكره المسيلماني للشابتر 3 بالخصوص وشويات من شابتر 2 لانا الثالث يعتمد عليه\n\nوبقعد احل اولد فاينلز احس انا هذا هو المهممم والله اعلم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-001/70012/5", "user": "m.s2008", "ts": 1233536045000, "tid": 70012, "pn": 5}}', 1233536045000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p359465-math001', 'stk-user4510', 'MATH 001', 'info', '{"desc": "و الله بالنسبة لي يا شباب …\n\nانا اراجع من الكتاب أولاً و أقرأ بتمعن و أحاول افهم الفكرة العامة أولاً ( يعني وش السالفة )\n\nبعدين أقرأ مرة ثانية أفهم الأفكار الدقيقة\n\nبعدين احاول ابحث عن التركات ( المطبات : الحاجة الدقيقة اللي تحوس ام السؤال لو ما تنتبه لها )\n\nبعد ما أخلص الكتاب أروح احل في ((( الشابتر رفيو ))) يا شباب تراها مهمة جداً حتى انه فيه أسئلة جت منها\nبالنص في المياجر اللي راحت .\n\nفي النهاية احل في الأولد اكزام …و على فكرة عادي اذا طلع لك 3 - 4 أسئلة ما تعرف تحلها …\n\nبالنسبة للنوتات … الظاهر ان الشباب اللي راجعوا النوت المياجر اللي راحت جابوا العيد ( مو كلهم ) … لأن النوت\nفيها الافكار العامة او الاساسية( يعني اذا عجزت تفهم من الكتاب ، ترجع للنوت ) . لكن يا شباب لا تهملون الكتاب نصييييييييييييييييحة .\n\nو في النهاية أعيد على الشابتر رفيو اللي في نهاية كل شابتر ، تراها و الله مهمة .\n\nو على فكرة ترى فهم الرياضيات يعتمد بشكل كبيييييييييييييييييييييييير على المدرس ، يعني لو فيه حاجة\nما فهمتها مرة ، حاول تسأل واحد من اخوياك عنها يكون يدرس عند مدرس صح ،\n\nو الله الله الهمة يا شباب ، خلونا نبغى نأدب الفاينل هذا ( لأنه رافع ضغطي و مسبب قلق ) و نعلمه الأدب\n\n((( أنا داري الخميس الشباب داخلين الاختبار معهم عجاري ))) هههههههههههههه\n\nالله يوفق الجميع ،،، و تمنياتي للجميع نشوفهم بـ 002\n\nادعوا لنا بالتوفيق يا شباب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-001/70012/12", "user": "user4510", "ts": 1233564243000, "tid": 70012, "pn": 12}}', 1233564243000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p606002-math001', 'stk-_z_o_y_d', 'MATH 001', 'info', '{"desc": "أصلاا لو ان احنا مو مزفتين\nكان الأفرج بيكون حول ال 17…\nلأن السمستر اللي راح (001)الطلاب اللي جايبين درجات نازلة هم اللي ينزلون الأفرج…\nلكن هالسمستر الطلاب ذولا تم عزلهم وأخذوا ماث 001 (لاا أقصد الاهانة )\nفما بقى الا الطلاب اللي جابوا درجات كويسة …فلذلك مو مستغرب ان يكون الأفرج بهالمستوى\nوشي ثاني…كون الاختبار صعب مايعني ان مانحل…\nيعني انا اختبارات السمستر اللي راح كنت أحل وكان عندي وقت للمراجعة…\nلكن الميجر الأول 002 حليت لكن ماكان عندي وقت للمراجعة…فهذا معناه ان الاختبار صعب ولكن مو معناه اني ماحليت^^…(طبعا انا أتكلم عن الميجر الاول وليش كان الافرج مرتفع)\nأتمنى ان الفكرة وصلت…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/88072/7", "user": "_Z_O_Y_D", "ts": 1273832851000, "tid": 88072, "pn": 7}}', 1273832851000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p827547-math001', 'stk-abu_omar', 'MATH 001', 'info', '{"desc": "انا عايد الماث 001 وتوقعت أني أبدع في هذا الميجر ولكن كانت المصييبة لما قارنت السيليوشن بحلي و آخذ 7 من 20 😭 😭 😭 😭 😭 😭 والله ماتوقعتها كذا مالعلم أن كويزاتي تعبانة وهذه آخر فرصة لي لهذا الكورس إما البقاء وإما الوداع وذهاب تعب 12 سنة من المعاناة الله المستعان", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/105878/1", "user": "Abu_Omar", "ts": 1301424883000, "tid": 105878, "pn": 1}}', 1301424883000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1105191-math001', 'stk-a.atiq', 'MATH 001', 'info', '{"desc": "استعدوا للميجر الثاني يا اخواني الفضلاء يقولون ان الميجر اللي فات اسهل ميجر فيزكس بيمر علينا\n\nما أخوفكم … لكن أبلغكم … عشان تشدون حيلكم\n\nأتذكر في الأوريا في ماث 001 جبت في الميجر الأول 9 وجاني نفسية ما يعلم بها الا الله\n\nقالوا لي الميجر الثاني صعب ومدري ايش\n\nجبت 18 الحمدلله\n\nنفس الكلام في 002\n\nقالوا الميجر الثاني كله قوانين ومعقد ووو\nجبت 19 الحمدلله\n\nفيوجد بعض الأمل عندي بالعوض في الميجر الثاني ان شاء الله\n\nتوكلوا على الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/1-phys-101/133255/56", "user": "A.Atiq", "ts": 1349721166000, "tid": 133255, "pn": 56}}', 1349721166000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1433149-math001', 'stk-_3111', 'MATH 001', 'info', '{"desc": "درسني كثير من الدكاترة الممتازين لكن في 4 دكاترة أعتبرهم الأفضل وأصنفهم من طبقة الأساتذة الفاخرة وهذا ترتيبهم حسب السنة اللي درست فيها معهم:\n\n1- معاذ أبوجيا (ماث 001) هذا الرجل أقل ما يقال عنه بأنه شخص عظيم، أفضل مدرس ماث عدا علي في الجامعة بلا منازع وأخلاقه لا تقل أبدا عن شرحه\n2- فهد الدوسري (اسلامي 212) أخذت عند اسلامي عند 4 أشخاص والوحيد اللي ما كان دكتور هو فهد الدوسري ومع هذا أشوفه يفوقهم جميعا! شخص متعلم ومثقف ويجيد محاورة الشباب والاستماع لهم، ما أنسى موقف رائع منه لما حضر إلى البيت لعزائي في أحد الأقارب مع أن هذا الشي حصل ثاني أسبوع في السمستر ومعرفتي به كانت سطحية جدا ومع هذا قالي سمعت عن الوفاة ولاحظت تشابه الأسماء فحضرت.\n3- باسم أبوالسعود ( che 201 ) المميز في الدكتور الفاضل باسم أبو السعود هو حرصه الشديد على مصلحة الطالب، شرح من أفضل ما يكون وأخلاق من أعلى ما يكون وحرص شديد على مساعدة الطالب، انتقدته في التقييم بعد نهاية الفصل لأنه تأخر في تسليم الدرجات وأتفاجأ بأنه يرد عبر البلاك بورد برسالة عنونها: توضيح للأخ أبو خلدون، وذكر سبب التأخر! ونشرت الرسالة في موضوع التقييم بعدها مباشرة\n4- نايف الصيفي (che 202) هذا الرجل له فضل كبير علي، قابلته أول مرة لمن رحت آخذ ابروفل منه لتسجيل الفريشمان وتوقعت الشغلة بتاخذ دقيقة لأنه لسى أول فصل وما عندي معدل، تفاجأت يقولي اجلس وفتح درجاتي في الأوريا وجلس يناقشني! وما أنسى نصيحته ذاك اليوم لمن قالي احرص على الأذكار وشد حيلك أكثر. بعدها بسنة درسني وكان نعم المعلم من حيث الشرح والاهتمام والتمكن من المادة وبكل ثقة أقول بأنه أكثر شخص متمكن من مادته قابلته في الجامعة. لمن تكلمه تشعر فعلا بأنك تكلم عالم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/120018/176", "user": "_3111", "ts": 1447381998000, "tid": 120018, "pn": 176}}', 1447381998000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p714389-math001', 'stk-user5800', 'MATH 001', 'info', '{"desc": "3-الماث 001 صعب او 002 اصعب انا فاهم بس الاستاذ يقول الاسئلة صعبة صعبة مو زي ما تحلوه في الفصل\n4-في استاذ ابغى اسأل عنه الاول اسمه اونيل مدرس ورك شوب كيفه مع الطلاب\nوالثاني اسمه تريسي انجلش\nوالثالث يوسف العريان كمبيوتر ساينس\nوالرابع جون هونغ بي اي\nوالاخير ابوجيا ماث\n\n001 mathتااافه جدا ، لكن هذا لا يعني انك ما تذااااكر !!\n002 math ،، من متوسط إلى صعب … من الله ومن الشابتر … ويبغا لها انتباه ومتابعة اكثر .\n\nاونيل ، استاذ له سمعة طيبة من الطلاب اللي كانوا حريصين على المادة .\nتريسي ، ما اعرفه .\nيوسف العريان ، من افضل مدرسي الكمبيوتر في الاوريا …\nجون هونغ … لا تغيب وفالك جريد حلو …\nابوجيا ،، احمد ربك … واسجد سجود شكر ،، امنية كل طااالب .\n\nتحية طيبة .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/92665/2036", "user": "user5800", "ts": 1286221931000, "tid": 92665, "pn": 2036}}', 1286221931000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1283126-math001', 'stk-user9305', 'MATH 001', 'info', '{"desc": "انت خلصت الانجلش صح ؟ يعني عندك وقت طويل تقدر تذاكر فيه وتجيب فيه قريد بالراحة , ترى كتاب الماث حق التحضيرية مبسط وسهل ويشرح افكار كثيرة , فيه السلوشن حقه كل أسئلة الكتاب تلقاه بالتراكر حمله ثم حل الأسئلة الفردية واولد اكزاكز وصدقني تبيترسخ الافكار براسك\n\nفي الكتاب كل سؤالين متتالين يحملون نفس الفكرة , عشان كذا يقولون حلوا الاسئلة الفردية لأن الزوجية مثلها بالضبط اللهم انهم غيروا الارقام بس والافكار هي نفسها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/151698/7", "user": "user9305", "ts": 1383667365000, "tid": 151698, "pn": 7}}', 1383667365000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1107413-math001', 'stk-m7md_a', 'MATH 001', 'info', '{"desc": "لازم تشد حيلك للميجر الثاني\n\nلأن إذا كان الميجر الأول على كلامكم سهل أكيد المعدل راح يكون مرتفع\n\nوعلى كذا غالباً راح يصعبون الميجر الثاني\n\nأحسبها إذا بغيت زي كذا\n\nخلنا نقول جبت بالكلاس وورك 15\n\nراح يكون مجموع الميجر الأول والكلاس وورك 25\n\nيعني تحتاج من الميجر 2 + فاينل =35 درجة على الأقل للنجاح\n\nوهذي تراها ليست سهلة ولا مستحيلة\n\nيعني قد ما تجيب درجة حلوه لميجر 2 وكويزات مدرسكم(الكلاس وورك) قد ما يسهل عليك الفاينل\n\nبس هذي مو معناتها أنك تزلب بواحد وتذاكر لواحد\n\nاعرف واحد باقي له 6 درجات يجيبها بالفاينل من 36 على النجاح ورسب!!\n\nأنا ما أبي أخوفكم بس أبعرفكم بالواقع\n\nعلى العموم تراهم ما حطوا لكم ماث 001 وماث002 عبث\n\nإذا بدعت فيها الحين راح تسهل عليك بعض مواد الجبل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/133493/49", "user": "m7md_A", "ts": 1350092369000, "tid": 133493, "pn": 49}}', 1350092369000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p908467-math001', 'stk-_s3', 'MATH 001', 'info', '{"desc": "^^\n👍 + أتمنى لو كان اسمي محمد لكن اسمي مهند مو محمد … 🙂\n\nلا يا أخوي أنت تفهم من النوته … لأن النوته شرحها مبسط وتحل الأسئلة اللي في النوته (لأنها ضرورية جداً جداً وبتصادف كثير منها في الكويزات والمياجر لأن أيمن ما يحط إلا أهم الأسئلة) … وبعد ما تفهم الدرس 100% … حل أسئلة الكتاب (كلها) … وأبد بكذا تكون ضامن درجة الأسئلة اللي بتجي من هالدرس … وقبل المياجر حل الأولد إكزام (فيه لخان ولأيمن وفيه واحد ما عليه اسم دكتور) كلها ممتازة أنا عن نفسي كل مرة أجرب واحد وكلها ممتازة … وبكذا أضمن لك A+ بشرط أنك تجتهد وتسوي اللي قلت لك عليه …\n\nأما عن النوتات فلا تأخذ نوتة خان أبداً … أنا درست عنده أول سمستر والمدرس ما فيه زيه بس النوتة معقدة جداً وفرق شاسع بينها وبين نوتة أيمن … فلا أنصحك بها نهائياً … أنا نوتة ناجي إبراهيم فهي جيده وأعرف ناس كثيرين يذاكرون منها لكن أنا عن نفسي ما أعجبتني …\n\nالخلاصة: نوتة أيمن + حل أسئلة الكتاب + (حل الأولد إكزام قبل المياجر والفاينل) = A+", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/112723/6", "user": "_s3", "ts": 1316989495000, "tid": 112723, "pn": 6}}', 1316989495000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p338571-math001', 'stk-user4649', 'MATH 001', 'info', '{"desc": "شباب انا جبت 5 في هذا الميجر ؟؟ تتوقعون أقدر أ‘وض في الميجر والفاينال ؟ ولا NO WAY ؟؟\n\nمع إني شديت حيلي و ذاكرت لكن الوقت قصير و 5 اسئلة حليتها اي كلام لأن ما بقى وقت 😦\n\nانا دايم في كل اختبار استعمل ساعة جوالي عشان أوقت لنفسي لكن قطونا في مبنى 59 والكلاس ما فيه لا ساعة ولا شي\n\nالمدرس يكتب الساعة على السبورة : 8:25 وينتهي الاختبار في 9:25 وانا قاعد أحل على راحتي وشوي و يروح يمسح 8:25 و يكتب 9:10 انا وجهي صار كذا 👀 🤪\n\nاختبصت ما ادري وش اسوي الحين طوفت كم سؤال أنا عارف حلها والله إني عارف حلها لكن من العجلة حطيت أي كلام وغلطت بكم سؤال بس وش نقول خلها على ربك 😢", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68151/56", "user": "user4649", "ts": 1227806828000, "tid": 68151, "pn": 56}}', 1227806828000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p339211-math001', 'stk-abdulaziz1', 'MATH 001', 'info', '{"desc": "السلام عليكم …\n\nأبي أعرف … هل فيه نظام جديد إن الي يعيد المادّة يدسمس ؟!\n\nما أظن فيه إشكال أساساً إن الشخص يعيد …\n\nأنا على سبيل المثال …\n\n6 ونص من 15 بالميجر الأول … 9 من 25 بالمدتيرم … 8 ونص من 15 بميجر 2 … 7 بالكلاس وورك … 18 بالفاينل … وبقالي 4 درجات عالنجاح … في الأخير …\n\nعلى إني مقتنع مسبقاً بإعادتي للكورس … 🙂\n\nالترم الأول تحديداً … لا تشيلون هم كبير فيه … ولا تهملون … حتّى إذا الواحد لا قدّر الله حمل كل الموّاد … بإمكانه التعويض …\n\nيعني مافيها دسمسة بإذن الله … وفيه مجال لمراجعة الحسابات … ولكن …\n\nحاولوا تجتهدون … لسبب بسيط … وهو إنك قد تنجح … وقد تعيد … لكن تكون خلفيتك قويّة … وفي الترم الجاي … تكون من المتفوقين … ولا تحتاج جهد مضاعف …\n\nوعليكم بالأولد إكزامز في الدراسة … 🙂\n\nلا تستلم للإعادة … ولكن كن واقعي … 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68151/57", "user": "abdulaziz1", "ts": 1229273505000, "tid": 68151, "pn": 57}}', 1229273505000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1301289-math001', 'stk-sabfas', 'MATH 001', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته …\n\nأختبرت الكلاس تيست ؟\n\nإذا ماأختبرته ففرصتك كبيرة جدا جدا … وتعتبر ممتازة !\n\nطبعاً انا أيام الأوريا … نجحت في 001 و002 على الحافة … وكنت مثلك أحسب كم لازم أجيب في الفاينل عشان أعدّي !!\n\nعموماً مجموع الميجرين 40% …\nأنت جبت فيهم 21 … يعني أعلى بحبه من النص … شئ طيب\n\nالكلاسوورك عليه 24% …\nالأفرج ناسي … بين 16 و18 …\nفيعني إن شاء الله بتجيب درجة أعلى مما تتوقع …\nإن كانك أختبرت كلاس تيست وخبصت … فأتوقع بتطلع بـ 13 أو 12 !\n\nخلنا نقول 12 … مجموعك قبل الفاينل :\n\n12 + 21 = 33\n\nالنجاح من 60 … احتمال أحياناً ينزل إلى 58 … على حسب الأفرج … لكن خلنا نقول 60 …\n\nيبقى لك 27 درجة في الإختبار النهائي من أصل 36 !!\n\nترآآها جداً بسيطة …\nفيه ناس كان النجاح من 34 … ونجحوا !!\n\nوأنت 27 … والله بسيطة جداً …\n\nطبعاً هذا الكلام في حال خبصت بالكلاس تيست ( يعني جبت 3 من 10 مثلاً !! )\n\nطبعاً كلامي كله المقصد منه أنه مايحتاج تقلق … اللي أبيه منك بس تشتغل شووي …\nذاكر … افتح اولد اكزامات وذاكرها …\nيعني حاول تفهم الكونسبت … ثم حل عليه أولد اكزام !\n\nوترآآ ماث 001 يعتبر بسيط … يعني لو تضغط على نفسك أسبوع … راح تفهم الكونسبت 100% …\n\nوفيه نقطة مهمة جداً … إن كانك إلى الأن ماأختبرت الكلاس تيست … فأتمنى أتمنى منك … أنك تذاكر للكلاس تيست كأنه فاينل !!\n\nلابد تطلع بأعلى درجة ممكنة من الكلاسوورك …\n\nوإذا فيه كويزات الأيام القادمة … اجتهد قدر المستطاع …\n\nوالله يوفقك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/153456/15", "user": "sabfas", "ts": 1386324755000, "tid": 153456, "pn": 15}}', 1386324755000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p922745-math001', 'stk-user8715', 'MATH 001', 'info', '{"desc": "تكفون يالشباب بانهبل\nالاختبار كان سهل\n\nبس اخطات يمكن 9 اسئلة 😲 😲 بسبب الاستعجال بسبب التوتر\n\nمثل المثلث جبت قيمة x ونسيت اطرح 12\n\nوكل اخطائي زي كذا\n\nتكفون نصيحة نفسيتي معدومة والله كان ناقصني تركيز\n\nحليت الصعب واخطيت بالسهل بنجن 🤪 🤪 🤪\n\nوالله منقهر بشكل ما تتصورونة\n\nتكفون اي كلمة منكم بتهدين\n\nصرت خايف من الجاي 😞 😞 😞 😞 😞 😞 😞 😞 😞 😞 😞 😞 😞\n\nالحمد لله على كل حال", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/1-001/114176/11", "user": "user8715", "ts": 1319131325000, "tid": 114176, "pn": 11}}', 1319131325000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p922944-math001', 'stk-bin_saeed', 'MATH 001', 'info', '{"desc": "تكفون يالشباب بانهبل\nالاختبار كان سهل\n\nبس اخطات يمكن 9 اسئلة بسبب الاستعجال بسبب التوتر\n\nمثل المثلث جبت قيمة x ونسيت اطرح 12\n\nوكل اخطائي زي كذا\n\nتكفون نصيحة نفسيتي معدومة والله كان ناقصني تركيز\n\nحليت الصعب واخطيت بالسهل بنجن\n\nوالله منقهر بشكل ما تتصورونة\n\nتكفون اي كلمة منكم بتهدين\n\nصرت خايف من الجاي\n\nالحمد لله على كل حال\n\nهذا رزق وتوفيق من الله … فاحمد الله اول شي انك فاهم وماعندك الا اخطاء بسيطه\n\nوهذا امر ممتاز جدا وراح يفيدك في الميجر الثاني والفاينل\n\nولاتنسى ان الميجر عليه 20 فقط وباقي قدامك 80 درجه في يدك\n\nحاول ان تبتعد عن الارتباك والرهبه وراح تروح معاك في الاختبارات القادمه باذن الله\n\nاهم شي انك فاهم وراح تعدي الكورس بالراحه\n\nوالله يوفقك ان شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/1-001/114176/20", "user": "Bin_Saeed", "ts": 1319157253000, "tid": 114176, "pn": 20}}', 1319157253000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p522239-math001', 'stk-_2131', 'MATH 001', 'info', '{"desc": "السلام عليكم\n\nولله الحمد الاختبار كان متوسط الى سهل المستوى والدرجات انشاء الله زينه بس عندي سؤالين الله لا يهينكم.\n\n1_ هل يقدر الاستاذ يزود على كيفه في الكلاس وورك (كويز + كلاس تست + هووم ووركز) .واللي يعرف استاذ اسمه (العالمية) يقوولي اذا كان يزود والا لا.\n2_ انا جبت بالميجر الاول 5 والثاني انشاء الله اتوقع 12 <<<واثق من نفسه . هل في امل اني اعدي ؟؟؟ تكفون ابغى رد.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/82106/46", "user": "_2131", "ts": 1263285184000, "tid": 82106, "pn": 46}}', 1263285184000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p732707-math001', 'stk-b_r_o_k_e_n', 'MATH 001', 'info', '{"desc": "المثبطين ما ينعطون وجه صراحةً …\n\n… كيف متحملين انفسهم ؟\n\nيعني لو اخذو بالميجر الثاني اقل من 15 …\n\nاعتقد راح ينسحبون … لانهم راح يثبطون انفسهم بأنفسهم …\n\nاستغفر الله العلي العظيم …\n\nانا صراحة احس الاختبار فيه صعوبة … لكن مو صعب على اللي مذاكر صح …\n\nلكن حبايبي اللي اخذو درجة نازلة … لا تفقدون الامل بسبب هالأشكال …\n\nترى والله العظيم انه ميجر … ولا بعد والله العظيم انه من 20 …\n\nوترى والله العظيم ان فيه فرص كثيرة لك …\n\nشوف اخطآئك بنفسك … وشوف انت راجعت صح قبل الميجر …\n\nوالمثبطين اشكال النكتة <<< ضيعت اسمه !\n\nشايف نفسه مع احترامي الشديد …\n\nوترآنا في بداية الطريق … لا تفقد الامل …\n\nلكل بداية محرقة نهاية مشرقة …\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/97708/66", "user": "B_r_o_k_e_n", "ts": 1288991268000, "tid": 97708, "pn": 66}}', 1288991268000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p535248-math001', 'stk-abo.5aled', 'MATH 001', 'info', '{"desc": "وضع الماث السمستر هذا غريب … ؟!\n\nمعقولة كل البلاوي اللي كانت بسبب العساف !!\n\nع العموم …\nان شاء الله يستمر الوضع كذا …\nلأن الوضع سابقا ً كان عذاب ويأدي لنتائج و آثار سيئة نفسية وعقلية تستمر حتى بعد الصعود لـ الجبل 😆 …\n\nالاختبار كان من المتوسط الى الصعب … واللي يقول سهل>>>مادري ما قلت شي\n\nبس انا عندي سؤال بسيط جدا ؟ انا الحين باعيد 001 ماث هل يؤثر على اختيار التخصص. اذا خلصت 002 في الصيف انشاء الله؟\n\nلا ما يأثر ان شاء الله …\nمحسوبك متخرج في الصيف ولا كان فيه أي تأثير علي ولا على باقي اللي تخرجوا معي بالصيف …\n\nالوضع من سعة ان شاء الله 🌹 …\n\n،،،،،،،،،،", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/82999/30", "user": "abo.5aled", "ts": 1265149542000, "tid": 82999, "pn": 30}}', 1265149542000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p940589-math001', 'stk-user7909', 'MATH 001', 'srcU', '{"html": "هنا سليوشن ماث001<br><br>من المرفقات<br><br>لا تنسونا من صالح دعائكم<br><br>​<span data-fid=\"stk-f940589-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f940589-0": {"name": "Math001_e2_111.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/11fbd8c22683f32f352e1fb0e8de2f69a5b2f5a984e65baffad67633f7d4248b"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/115957/1", "user": "user7909", "ts": 1322736562000, "tid": 115957, "pn": 1}}', 1322736562000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1477252-math001', 'stk-lord_k_a', 'MATH 001', 'srcP', '{"html": "وعليكم السلام ورحمة الله وبركاته<br><br>انا ما عندي المقرر ( الكتاب ) ولكن عندي أفضل منه … وهو نوته ( ناجي )<br>هي شرح للمقرر math 001 مختصر مع تمارين تساعدك على رسخ المعلومة<br><br>​<span data-fid=\"stk-f1477252-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1477252-0": {"name": "Math001 notes without solutions.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/ce7c34c04d1366b9ead4f3d7347bcd02d8a60b0c7736ec7ecff5a34427ab41df"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/177188/3", "user": "LorD_K_A", "ts": 1500851632000, "tid": 177188, "pn": 3}}', 1500851632000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p749784-math001', 'stk-khalid-f10', 'MATH 001', 'srcU', '{"html": "اخوي افضل طريقة شفتها لتوحيد المقامات طريقة خان<br>طريقة راااااااااااائعة<br>وانا حملتها لك وهي في الصفحة الثانية<br>والله يوفق الجميع<br><br>​<span data-fid=\"stk-f749784-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f749784-0": {"name": "r.5.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/753af6d9b0d6b834ce0f391315154c98e0dbe8e168bdf0a638189eaa7c9e755c"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-001/99349/35", "user": "khalid-f10", "ts": 1293037209000, "tid": 99349, "pn": 35}}', 1293037209000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
