INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p121159-math001', 'stk-user2105', 'MATH 001', 'srcU', '{"html": "هذه بعض الكوزات قي p3.p4.p5.p6 في math001<br><br>وانشالله تنفعكم والله ولي التوفيق…@46@<br><br>​<span data-fid=\"stk-f121159-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f121159-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f121159-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f121159-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f121159-0": {"name": "ACE Practice Test3.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/e2a5278c73c2ffb79f0f59b76ac19639d24050c73652ec3d35f63899e7b67254"}, "stk-f121159-1": {"name": "ACE Practice Test4.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/53ed13ad5cea1fb2f9c82debbeffce4d29af0bcef870866014b1a530ae4b7801"}, "stk-f121159-2": {"name": "ACE Practice Test5.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/d87dd4b6f3a751f459aef37c84013672eed5e5a8d8ae606c807c9ca61d71ef25"}, "stk-f121159-3": {"name": "ACE Practice Test6.doc", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/a25fb3030dcc2832a3ddf4f38495d8459274f38356286830197ef7b331b68d42"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/52519/1", "user": "user2105", "ts": 1159745179000, "tid": 52519, "pn": 1}}', 1159745179000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p940908-math001', 'stk-user7794', 'MATH 001', 'srcU', '{"html": "السلام عليكم أخوي بإمكانك تتأكد من عدد الدرجات اللي تنقصك للنجاح عن طريق ملف الإكسل هذا في المرفقات…<br>حط درجاتك بالمياجر والكلاس تستز وبالتوفيق… 🤴<br><br>​<span data-fid=\"stk-f940908-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f940908-0": {"name": "classwork.zip", "v": "data:application/zip;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/115979/24", "user": "user7794", "ts": 1322770542000, "tid": 115979, "pn": 24}}', 1322770542000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p817864-math001', 'stk-alroosi', 'MATH 001', 'srcU', '{"html": "شوف هذا الرابط: http://www.kfupm.edu.sa/pypmath/pages/syllabus001/Math001_syl_102.pdf<br><br>و إذا ما قتح حطيتلك ياها بالمرفقات…!! 🙂<br><br>بالتوفيق 👍<br><br>​<span data-fid=\"stk-f817864-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f817864-0": {"name": "Math001_syl_102.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/55910368331a776b500dd20c8842b0aaa58825703eadb0f84d4111f7b0efe4d1"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/syllabus-math-001-term-102/105096/4", "user": "AlRoosi", "ts": 1300458554000, "tid": 105096, "pn": 4}}', 1300458554000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-computist-math001', 'stk-computist', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f68392", "n": "Dr. Ahmad Al-Zoubi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني Math001 في 111\n\nالصوت واضح والشرح جيدجدا ويحفزك تشتغل بنفسك \\ بس مرة سألته سؤال ما عرفت احله عصب علي شوي\n\nالمدرس يعطي كوزات وكلاس تست (Excellent بالنسب لي لأن بها الشكل اختبر قدراتي) لله الحمد طلعت بدرجة حلوة A+\n\nأنصح فيه بشدة| حتى لو تريد بس باس إن شاء الله مع هالأستاد راح تطلع بأفضل مما تتوقع", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1295955-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-zoubi/68392/69", "user": "Computist", "ts": 1385617680000, "tid": 68392, "pn": 69}}]}', 1385617680000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mhm14-math001', 'stk-mhm14', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f68394", "n": "د. محمد رضا عليميه", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 001 - term 131\n\nالتحضير: يوميا، ينادي بالسيريل نمبر\n\nطريقة الشرح: يستعرض أهداف الدرس و بعدها يشرح مثال و يحل مسائل، شرحه من النوت حقه كان جيد بس عنده صعوبة في توصيل المعلومة للطالب لكن يحاول قدر الإمكان إنه يفهم الطالب\n\nالكويزات: أسئلة سهلة لمتوسطة من الكتاب و النوت و آخر سؤال يكون من عنده و فيها فكرة و بعض الأحيان تكون صعبة\nكان عنده حركة حلوة إنه المسائل اللي غلطت فيهم ترجع تحلهم و تجيب له اياه و بيعطيك درجة زيادة و هالشيء يخليك تفهم المادة صح.\nالكلاس تست من أسئلة الكتاب\n\nالمياجر و الفاينلات: لا شي يُذكر\n\nالقريد النهائي: A\n\nالصوت: واضح جدا\n\nإضافات: أغلب التعليقات هنا غير منصفة، إذا إنت بتكون مهتم بالمادة و متابع أول بأول بتحصل درجة ممتازة بالكلاس وورك و الحمدلله عطاني كامل بالكلاس وورك لأن المياجر كانت عالية و كان يطلب هومورك غير الأونلاين و كنت أجيبه أول بأول و أروح الأوفس أور من وقت لآخر و ما قصر معاي … إذا شافك مهتم و جاد بيعطيك الدرجة اللي تعجبك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1370432-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68394/46", "user": "MHM14", "ts": 1400933697000, "tid": 68394, "pn": 46}}]}', 1400933697000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal_19-math001', 'stk-faisal_19', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f68415", "n": "Dr. Elyas Al-Shawish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math001 - 161\n\nالتحضير : يومياً، ممكن 5 مرات ما حضّر بس, عطانا يوم اوف بعد ميجر الماث الثاني 🙂\nطريقة الشرح : عنده نوت خاص فيه شامل و وافي, يحل الامثلة الي في النوت وبعدها يحط كم سؤال من عنده عشان يبين الاغلاط اللي ممكن يطيحون فيها الطلاب.\nالكويزات : متوسطة بشكل عام، اللي يركز معه ويفهم بتكون الكويزات بالنسبه له مووويه، الكلاس تيست 2 كل واحد من 4\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A+ قليلة في حقه، ولله الحمد طلعت من الكورس بـ A+\nالصوت: واضح جداً ما شاء الله، بعض الاحيان يتكلم عربي وما عنده مشكله يشرح بالعربي اذا ما فهمت.\n\nإضافات : الاستاذ من خيرة الاساتذة علماً وأخلاقاً، فيه قاعدة شرحها لنا في بداية الترم وقال الي بينفذها الى النهاية ما راح بيطلع بأقل من A وهي تفهم الشرح معه وتحل الاسئلة الفردية في الكتاب وتهتم في الريسايتيشن وقبل المياجر والفاينل تشوف الاولد اقزام، من بداية الترم الى نهايته وانا اروح له اوفس اور وكان متعاون لأبعد الحدود، في نهاية الترم يرفع افرج الكلاس ورك الى ما يتساوى مع افرج مياجر السكشن حقك ، فالبونص يعتمد على اداء سكشنك في المياجر، زادنا 4 درجات ، يرفع حلول الكلاس على البلاكبورد + حلول الريسايتيشن + النوت حقه، أكرر الاستاذ بطططططل استفد منه قدر المستطاع.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467471-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/elyas-al-shawish/68415/66", "user": "Faisal_19", "ts": 1486065669000, "tid": 68415, "pn": 66}}]}', 1486065669000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-math001', 'stk-guest', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f68415", "n": "Dr. Elyas Al-Shawish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الماده :Math001\nالترم: 191\n\nبالنسبه لي الدكتور الياس افضل دكتور في قسم الاوريا ككل حتى في ترم ١٩٢ كنت احضر عنده ك مستمع لان دكتوري حق ٠٠٢ كان سيء\n\nالتحضير: فوسط المحاضرة لاكنه يمشي على النظام مستحيل يمشي لك تاخير واذا دخلت بعد عشر دقايق يدخلك عادي بس بيحطك غياب\n\nالشرح: عنده سيرفس شابكه في البروجيكتور يفتح لك النوته على الباوربوينت ويبدا يحل على الون نوت الدكتور صوته واضح وعالي، النوته واضحه وتعطيك الاساس بشكل واضح والمسائل الي فيها جيده لاكن لازم طبعا تحل الريس و الاولد اكزامز اذا تبي قريد\n\nالكويزات: الصراحه صعبه نوعا ما ودايم فيها افكار جديده لاكنها تجهزك للميجر خاصة الكلاس تيستات عنده حريقة كان يقول لو عطيكم كلاس تيست اسهل من الميجر ف انا جالس العب عليكم كذا لان المطلوب مني اجهزكم الميجر بشكل ممتاز، الكويزات عيبها انها بس ٣ اسئله وقليل يخليها ٤\n\nالبونص: كان ٣ ونص لكل الطلاب\n\nالتعامل: الدكتور شديد الصراحه لاكنه ينكت كثير ف المحاضرة ويغير الجو\n\nالقريد النهائي: A+ ولو فيه اعلى يستاهل\n\nاضافات: الدكتور فيه ميزة مالقيتها ف الدكاترة الثانين وهو انه يشرح لك الكونسبت بعدين يخليكم تحلون المسائل (بس) ماعنده إزعاج والي يخلص يقول جوابه بشكل عشوائي، نظامه بعد كم دقيقه من السؤال يسأل مين خلص ويخليكم تقولون اجاباتكم بعدين يقول الاجابة الصح ويشرح ليه جت كذا واذا اغلبكم حليتوها غلط بيقولكم ايش التريك الي تحطوا فيه ويوضح لكم كل شيء\n\nنصيحة للي يجيهم الياس يمكن اول اسبوعين تكرهه لانه شديد واسلوبه ف التعامل مو افضل شيء لاكن بعدها بتتعود وتصير تضحك على اسلوبه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522276-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/elyas-al-shawish/68415/70", "user": "Guest", "ts": 1590207464000, "tid": 68415, "pn": 70}}, {"id": "stk-dr-m118572", "n": "Dr. Adel Moham Al-Mahdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 001 - 191\n\nالتحضير : يحضر يوميا نهاية الكلاس بالسريال نمبر\nطريقة الشرح : شرحه جدا ممتاز و واضح يعطي فكرة الدرس اول شي بعدين يحل عليه مسائل مهمه للفهم، ويوضح قد ايش الدرس مهم و وش التركات الي ممكن تجي بالميجر. النوته شامله\nالكويزات : اول كويز او كويزين سهلين، الي بعدهم شبيه بالأولد أقزام بس عليه بهارات شوي\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A+\nالصوت: واضح جدا و في حالة شخص مو فاهم شغله ممكن يتكلم عربي\nإضافات : الدكتور أعجز وانا اقول طيب جدا و أخلاقه عاليه. يرحب في الي يجون الاوفس اورز واذا درجاتك طيبه في الميجر يعطي بونص ممتاز. وفي شي احب اضيفه ان الدكتور عنده مجموعة اسئله في الكلاس نوت ممتازه جدا، لو تحلها كلها مع التدرب على الاولد اقزام اضمن لك فل مارك بالميجر.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1524619-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-moham-al-mahdi/118572/11", "user": "Guest", "ts": 1597212949000, "tid": 118572, "pn": 11}}, {"id": "stk-dr-m172448", "n": "Dr. Shadi Moham Alomari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "* Math 001:\n\n|| درست هذا الترم 201 اونلاين عند ( الدكتور شادي العمري ) .\n\n- طريقه الشرح: يقرأ الـ Concept ثم يعطي مثال ويشرح بسيط عليه، ثم ينتقل الى حل الاسأله مباشرة ويحل اسئله كثير عليه.\n\nأو ممكن يشرح الكونسبت خلال حل الاساله تلقائياً.\n\nالسلبيه الي ممكن يشوفها بعض الطلاب عليه أنه يسرع احياناً، ولكنه بالأغلب لما يسرع يسرع على الجزئيات السهله مثل ضرب كسور.\n\n- الكويزات: صعبة، وأتذكره شخصياً قال: “ماراح تستفيدوا لو اعطيتكم سؤال سهل بالكويز، لأن الاساله السهله موجوده بكل مكان وانا ابغا الطالب يستعد ويتدرب للمياجر والفاينل” وطبعا الكويزات كانت سؤال او سؤالين ببعض الاحيان.\n\n- التحضير: في تجربتي الاونلاين معه، مايهتم بالتحضير الا بعض الأحيان في اي وقت بالحصه يقول جملته الشهيره: شباب all of you raise your hand.\n\n+ ايضاً مايطلب فتح كام.\n\n- اللغة: طبعا الدكتور اردني الجنسيه، ويخلط بين الانجليزي والعربي اثناء الشرح والصوت واضح.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527571-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shadi-moham-alomari/172448/9", "user": "Guest", "ts": 1609781496000, "tid": 172448, "pn": 9}}, {"id": "stk-dr-m172444", "n": "Dr. Audu Johnson", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 001- term 201-online\n\nالتحضير : يحضر في النهاية\nطريقة الشرح : كان يستعمل نوتات ابو جيا، يشرح كل شيء ، ومن افضل الاشياء اللي فيه وقت الشرح انه يبتعد عن الامثلة البدائية السهلة ويشرح اسئلة متوسطة\n\n*عندك صعوبة للاولدات تروح ال office hours ويساعدك ويحله لك برضوا\nوهو يحط لك اولدات كثيرة لكل سكشن\n\nالكويزات : من متوسطة الى صعبة احيانا - في النهاية بعض الاسئلة صارت تتكرر من الريستيشن\nلكن كويزاته تعودك على الفاينل والمياجر\n\nالمياجر: سمستر ٢٠١ كان ميجرين اونلاين فاينل انسر. وميد تيرم حضوري كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A كويس جدا وانصح فيه بس خذ واعطي معاه\n\nالصوت: انجليزيته مع انها افريقية الا انها كويسة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527878-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/audu-johnson/172444/10", "user": "Guest", "ts": 1610654853000, "tid": 172444, "pn": 10}}]}', 1590207464000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chaos_is_a_ladder-math001', 'stk-chaos_is_a_ladder', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f68415", "n": "Dr. Elyas Al-Shawish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH001 - 211\n\nالتحضير : يوميا سيريل نمبر\n\nطريقة الشرح : من افضل الدكاترة في توصيل المعلومة، كلاس ممتع ويتقبل الاسئلة ويخلينا نحل بالكلاس العادية وايضا الريسيتيشن عكس اغلب الدكاترة، يعني ما افهم ليش بعض كلاسات الدكاترة بدون حل مسائل !\nالكويزات : صعبة ولكن مع مذاكرة الاولدات ممكن تجيب فل، زودنا درجة وشي ك بونص، الدكتور مو الافضل اذا تبي قريد عالي مره، لكن الاهم هو الفهم والدكتور شرييييح\n\nالمياجر: كومن .\n\nالفاينلات : كومن .\n\nالقريد النهائي: B+\n\nالصوت: واضح\n\nإضافات : التاخير ما يتغاضى عنه، يقبل ميكاب على اخر الترم، مستحيل يطلعك قبل الكلاس، متساعد في الاوفيس، اذا جاك الدكتور انت محظوظ بتنسى مذاكرة البيت يوم بيوم… فقط ذاكر للمياجر وحاول تفهم طريقة كويزاته وتجيب قريد طيب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533526-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/elyas-al-shawish/68415/75", "user": "chaos_is_a_ladder", "ts": 1642746621000, "tid": 68415, "pn": 75}}]}', 1642746621000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr_mohammed_al_ali-math001', 'stk-mr_mohammed_al_ali', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f68415", "n": "Dr. Elyas Al-Shawish", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 001 and MATH 002, TERM 222 and 221\nالتحضير: يعطيك 3 دقايق تتأخر فيها في حال السكشن ما فل أمها.\nطريقة الشرح: سيئة جدًا، يشرح بسرعة ونوتاته مو مرتبة كويس بالأفكار. وجرب تسأله سؤال، يمسح كرامتك في الأرض بالتسفيل.\nالكويزات: لو ما تعتمد على شرحه، فهي سهلة أول سؤالين وآخر سؤال بيكون أصعبهم (الأفضل تشوف الشرح برى وتحل أسئلة نوتاته لأن تقريبًا يجيب منهم).\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: D+\nالصوت: واضح.\nإضافات : بحكم أني درست الأوريا كلها عنده بالماث، هالدكتور سيئ بالتعامل مع الطلاب خصوصًا لما يجي أحد يسأله بالمحاضرة+ الشرح سيئ+ يغثك بالـ Rec ويجي فجأة يقول لك حله وجيبه بكرة. بـ 001 جبت C+ والسبب أني كنت ضايع مو عارف أحصل أحد يشرح كويس بسببه، لكن بـ 002 لما اعتمدت على شرح مقبل وحليت الأولدات أول بأول، جبت A بالرغم أن المنهج كان أصعب. لكن للأمانة بـ 002 تحسن شوي وقام يعرض مسائل من المياجر ويخلي الطلاب يحلون ويعطي بونص.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536918-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/elyas-al-shawish/68415/77", "user": "Mr_Mohammed_Al_Ali", "ts": 1693251884000, "tid": 68415, "pn": 77}}]}', 1693251884000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rapls-math001', 'stk-rapls', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f68468", "n": "Dr. Sayed Omar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "171 - Math001\n\nالتحضير : يحضر بداية الكلاس , ملتزم بالوقت وما يتاخر\n\nطريقة الشرح : يشرح بامثلة سهلة ويتدرج بالصعوبة , نوتاته PDF برقم سري 😛 لكن تقدر تفكها بمواقع 😆\n\nالكويزات : متوسطة مائلة للصعوبة\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A\n\nالصوت: واضح والاكسنت شوي لك عليه لكن ينفهم\n\nإضافات : كان كلاسي معه الساعة 8 الصباح وكنت افهي وانام بكلاسه , لكن في الاوفس ما يقصر ابد ومن أطيب المحاضرين .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498505-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sayed-omar/68468/37", "user": "Rapls", "ts": 1535724610000, "tid": 68468, "pn": 37}}]}', 1535724610000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alabama_s_alexander-math001', 'stk-alabama_s_alexander', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f68468", "n": "Dr. Sayed Omar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "181 - Math001\n\nالتحضير : يحضر بداية الكلاس او نهايته, ملتزم بالوقت واذا جيت متأخر دقيقة دقيقتين وهو ما حضر يسجلك بريزنت٫ لكن لو كان يحضر وتأخرت دقيقتين ليت\n\nطريقة الشرح : يشرح بامثلة منوعة٫ نوتاته رائعة٫ فيها أفكار الدرس واولد اقزامز و اديشونال اكرسايسز زيادة ترسخ الأفكار\n\nالكويزات : متوسطة مائلة للصعوبة\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: +A\n\nالصوت: واضح والاكسنت شوي لك عليه لكن ينفهم\n\nإضافات : حاول إن درجاتك يكون فيها نمو٫ يعني حاول تكون فوق الأفرج بالكويزات وبالكلاس تست حاول تكون درجتك الثانية أحسن من الأولى وقريب من الفل ويساعدك بالكلاس وورك. نوتاته مرتبة وممتازة. لو الخيار لي بماث ٠٠٢ إخترته،", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503979-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sayed-omar/68468/39", "user": "Alabama_s_Alexander", "ts": 1545603009000, "tid": 68468, "pn": 39}}]}', 1545603009000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hussain_haiyan-math001', 'stk-hussain_haiyan', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f68555", "n": "Dr. B Demir", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math001 - 141\n\nالتحضير :\n\nيحضـر نهاية الكلاس ، مو شديد مرة مرة في التأخيـر …\n\nطريقة الشرح :\n\nيكتب النوته على السبورة ، الشرح تقريباً مثل الي في الكتاب مجرد أساسيات\nويخصص كلاس لحل الريسايتشن …\n\nالكويزات :\n\nأغلب كويزاتهم فيها سؤال متوسط أو فيها شويت صعبة …\nيكتب الكويز سؤالين على السبورة و آحنا نكتبه في ورقه خارجية\nويحط كل سؤال عليه 50 درجة …\nأما تصحيحه مرة زفت !\nيا أما تحل السؤال كامل بالخطوات صح ولا يعطيك صفر !\nالكلاس وورك يعتمد على آفرج السكشن نفسه\nبس بالعادة سكاشنه أغلبها تحت الأفرج !\nفما بتحصل من عنده آي درجة زيادة …\n\nالمياجر: Common\nالفاينلات : Common\nالقريد النهائي: +D عشـان أخلاقه الطيبه فقط !\nالصوت: مو مرة مرتفع ولا مرة منخفظ …\n\nإضافات :\n\nالشرح لك عليه ما يوصل المعلومة بالشكل الصحيح\nحده أساسيات ولا مرة شفته يشرح أسئلة فيها أفكار مثل المياجر !\nيعني ما تستفيد منه شيء بالكلاس ، الواحد يعتمد على نفسه أفضل من أنه يعتمد عليه …\nأنا عدت الماث أخذت فيه D معاهـ\nأحمل نفسي جزء من المسؤولية ولكن أنا أحمله جزء كبير من المسؤولية !\n\nلا شرح ولا تصحيح ولا آختبارات مثل العالم ، وطول السمستر جالس معاه ما آستفدت شيء منه\nما حسيت آني جالس أدرس ماث أصلاً\n\nأنا نصيحتي للي بيدرسه يعتمد على نفسه في كل شيء من البداية\nولا يضيع نفسه معاه مثل ما سويت\nلأن ما تستفيد بكل صراحة …\nحتى الطلاب الي يجبون فوق الأفرج في السكشن حقي ، ما كانوا عاجبهم للآسـف !", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1424595-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/b-demir/68555/70", "user": "Hussain_Haiyan", "ts": 1439996276000, "tid": 68555, "pn": 70}}, {"id": "stk-dr-f94893", "n": "Dr. Q Imam", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math001 - 142\n\nالتحضير :\n\nيحضـر بالأكسـل بداية الكلاس بالسيريال نمبر …\nأذكر كانوا في جماعة من الطلاب بالسكشن غياباتهم كثيرة\nفي يوم نادى عليهم واحد واحد وقال لهم آني ما بعطيكم DN و تساعد معاهم كثير …\nعـن نفسي أنا ما أفوت كلاساته الرهيبه ، عدا يومين ما قدرت أحضر …\n\nطريقة الشرح :\n\nنوته ينزلها في البلاكبورك ويشرح عليها\nفيها شرح + آسئلة عادية + آسئلة فيها أفكار\nو ما يخلي شيء ما يشرحه ويحلـه ما شاء الله عليه …\n\nالكويزات :\n\nعنده 5 كويزات ويأخذ أفضل 3 منهم …\nأفكار الآسئلة أغلبهم من الهوم ورك حقه\nهو يعطي واجبات في البلاك بورد حقه\nوالي يعطيه ويحلهم يزيده في الكلاس ورك درجتين إذا حل الواجبات كلهم …\nأما آحنا ما سوى لنا كذا …\nكان يجيب في الكويزات سؤال من الهوم ورك والي يحله يآخذ درجات زيادة\nالي يحل أفكار الواجبات بيكون الكويز عليه سهل …\n\nالكلاس تيست صراحة جداً صعـب هههههههههههههه\nحتى بالفاينال ما يجي مثل آسئلته @_@\nآسئلته عبارة عن أكثر من فكرة في سؤال واحـد\nهدفه هو آن الطلاب يتعود و يمرن نفسه على هذي الآسئلة\nمستواي بالماث تطور كثير و الفضل يعود له … 🌹\n\nالمياجر: Common\nالفاينلات : Common\nالصوت: واضـح\n\nإضافات :\n\nقيصر آمام متعاون جداً مع الطلاب …\nوأنا بما إني عايد الماث أغلب الدروس مو فاهمها\nو كنت أنتظر الدرس يجي عشان أفهمه منه ، من أول مرة يشرح الدرس أفهمه\nأذكر في آشياء عقدتني بس معاه كل شيء صار سهلات …\nما قصـر في الشرح علينا بشيء جزاه الله خير\nهو يتأخر شوي عن السيلبوس وأذكر كم يوم خلانا نجي يوم الأربعاء < اليوم الي مافيه ماث\nبس يعطينا بدله يوم بدله آجازة …\n\nفي الكلاس وركـ جداً متسـاعد …\nكان يقول لنا أفرج كلاسنا في المياجر فوق الأفرج و أتوقع حتى باقي كلاساته\nحتى الأوراق الي يعطوها الإدارة للمدرسين حقت الطلاب الي يجبون تحت الأفرج\nكان كلاسي أول كلاس عنده وأشوفه يجي بذي الأوراق\nوأشوفها عدد قليل ما تزيد عن 10 لكل السكاشن حقه !\nأما مدرسي الي قبله ممكن 10 لسكشن حقي بس\nهذا أنا يكفيني أنه مـدرس بطـل … http://www.stkfupm.com/forum/images/smilies/biggrin.gif\n\nأنا في الكويزات حصلت 7 وشوي من 8\nأما الكلاس تيست كان صعب جداً\nمن شدة الصعوبة حقت الأسئلة ممكن في سؤال\nما قدرت أكتب شيء أو أحاول آحله حتى هههههههههههههههههههه\nيعني يا دوب آخـذ 4 من 8 فيه\nوهو قال لنا أنا بزيدكم كلكم أقصى شيء أقدر آزيدكم بعطيكم …\nوقبل آخر يوم تقريباً في الكورس راوانا درجاتنا …\nأنا ما توقعت الدرجة الي عطاني وياها مررة …\nعطاني الكلاس ورك كامل !\n\nلما عرضهم لنا في الآكسل عطانا نظرات وقال لنا …\n? Who is better Evaluation me or you\n\nصراحـة آحرجنا بكرمـة هههههههههههههه 🌹\nأيـام لن أنساها معاهـ ، شكراً لك على كل شيء …\n\nالقريد النهائي:\n\nفي تقييم الجامعة عطيته أعلى شـيء\n\nوهنـا هم بعطيه A+ ولو في أكثر عطيته كمـان … 🤠", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1424599-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/q-imam/94893/18", "user": "Hussain_Haiyan", "ts": 1439999546000, "tid": 94893, "pn": 18}}]}', 1439996276000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahm4d-math001', 'stk-ahm4d', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f68555", "n": "Dr. B Demir", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "141 - Math 001\n\nالتحضير\n\nيحضر اخر الكلاس بورقة\nو لو تأخرت يتذكر اسمك و يعطيك ليت و إذا تأخرت فوق 10 دقايق برضو يتذكر اسمك و يعطيك غياب اخر الكلاس\n\nطريقة الشرح\n\nعنده نوتة خاصة فيه يكتبها على السبورة\n\nالكويزات\n\nكويزاته جدًا بسيطة و تكون أسئلته قليلة\nيعني مثلًا يعطيك كويز على درسين ، حتلاقي سؤال على كل درس و خلاص\nيعني كويز بس سؤالين !\n\nالقريد النهائي\n\nB+\n\nالصوت\n\nواضح\n\nإضافات\n\nالأستاذ يعطيك الزبدة في محاضراته\nأنا اعتمدت على الله ثم على نوتته اللي كنت أكتبها و جبت قريد حلو ، ما كنت أذاكر شيء غير نوتته و أولد اقزامز\nسجل الكلام اللي يكتبه في السبورة و خلك متأكد إنك فاهمه و بتمشي أمورك سهالات في الكورس\nعيبه الوحيد مزاجي و لو سألته سؤال ما عجبه يسحب عليك أو يهزئك قدام الكل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1425574-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/b-demir/68555/71", "user": "Ahm4d", "ts": 1440487179000, "tid": 68555, "pn": 71}}]}', 1440487179000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11009-math001', 'stk-user11009', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f68555", "n": "Dr. B Demir", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 001, term:171\n\nالتحضير : يحضر اخر الكلاس, اولاً يحسب العدد اذا كاملين مايضيع وقت اما اذا ناقصين يحضر, فيه ايام مايحضر فيها, ويسمح بالميك أب وأحياناً يمشي الليت وأحياناً لا.\nطريقة الشرح : يشرح من سلايدات الشركة او الكتاب , فيها أمثلة وواضحة ويحط فيها الريسايتيشن ويحلها بعد مايخلص السكشن , شرح واضح يعلمك الأساسيات و السلايدات فيها كثيييييير أولد إقزامز يحل منها عدد مو بسيط. والباقي يمديك تتمرن عليه 👍\nالكويزات : كويزات نسخ لصق من السلايدات إلا واحد أو اثنين جاب من عنده مرة و جاب أولد إقزام مرة.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: أعطيه A او B+\nالصوت: صوت واضح ويحب ينطق المصطلحات المهمة بالعربي أيضاً\nإضافات : الدكتور يشرح أساسيات ويفهمك أغلب اذا مو كل اللي مفروض تعرفه والكلاس وورك بالجيب اذا تذاكر عالخفيف ,\nعاد المياجر والفاينلات أنت وضميرك و الأولد إقزام موجودة لهالسبب, عن نفسي أفضل تدرس سلايدات محمد مدري أحمد عوض لأنه كررريف ويحب الأفكار الجديدة للمياجر وذي , ماراح تندم صدقني", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1486304-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/b-demir/68555/75", "user": "user11009", "ts": 1516241204000, "tid": 68555, "pn": 75}}]}', 1516241204000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulmalik123-math001', 'stk-abdulmalik123', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f68555", "n": "Dr. B Demir", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 001 181\nالتحضير : اخر الكلاس والليت عنده الين ١٠ دقايق وما عنده ميك اب .\nطريقة الشرح : سلايدات خاصه فيه ويحط اولد اكزامز كثير نهاية كل درس نصيحة لا تطبعها لانه ما بيحلها كلها 😅\nويحتاج تشتغل بنفسك لا تعتمد عليه.\nالكويزات : بيجيكم فجأه وبيقلكم عندكم كويز بكرة ٥ دروس وفي الاخير يطلع الكويز سؤال واحد وبيختبركم ممكن ٨ او ٧ .\nالمياجر : كومن\nفاينل : كومن\nالقريد : +C\nالصوت : ممتاز يتكلم انجليزي و يقط كم كلمه عربي (مصطلحات)\nإضافات : لا تعتمد على شرحه ابداً لانه مو قد كذا لكن بيعطيك الطرق المختصره للحل ، كويزاته سهههههله لا تضيعها وحل الاسئله بطريقته لانه مزاجي في كم واحد حل الاسئلة بطريقة ثانيه و طلع نفس الجواب وما اعطاه الدرجه ، يحل اولد اكزامز كثير ، لو عندك سؤال اساله بعد الكلاس لا تروح اوفس اور لانه اخلاقه زي الزفت واذا سالته سؤال تافه بيزبدلك و يهينك ، بتسمع كلمة (شباب) كثير ، اعطاني بونص ٣ درجات .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1510113-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/b-demir/68555/77", "user": "abdulmalik123", "ts": 1558659781000, "tid": 68555, "pn": 77}}]}', 1558659781000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_khald-math001', 'stk-abu_khald', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f68675", "n": "Dr. Khaled Saifullah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": ".\n\nترم ١٦١ - MATH001\n\nالتحضير :\nمن الموقع يحضّر بدايه الكلاس، واقولها حرفيًا بدايه الكلاس، ما أذكر قد تأخر ابدًا 😆.\n\nطريقة الشرح :\nعنده نوت خاص فيه في البلاك بورد وتحصله في المول، جدًا جدًا خرافيهو ملخصه القوانين والاشياء المهمه\nبالإضافه إلى أن الاسئله اللي فيها عباره عن أولد إقزام، يعني انت قاعد تحل اولد اقزام طول الترم في النوت.\nيعرض النوت على السبوره ويشرح ويحل الاسئله. تحتاج تحل الاسئله معه عشان اذا جيت تذاكر.\n\nالكويزات :\nمستواها متوسط ونهايه الترم ما يقصر معك 😊.\nأغلب الطلاب يزيدهم إلى ٥ درجات وأكثر.\n\nالمياجر:\nكومن.\n\nالفاينلات :\nكومن.\n\nالقريد النهائي:\nA++++\n\nالصوت:\nواضح ومفهوم جدًا.\n\nإضافات :\nالدكتور إسطوري جدًا وما عمري شفت نفسه، مدري وش السر بس ما قد طلعت من كلاسه إلا وأنا فاهم ومبتسم 😄.\nحريص جدًا على مصالح الطلاب ودايم يقول مهما كانت درجاتك ويأسك من الماده، تعال للأوفيس اور كلمني.\nفيه عباره قالها وللحين اتذكرها، قال:\n\" I like to help you, I’m woried and concern about you, you’re like my sons \"\nيعني ما ادري وش اقول بعد هالعباره اللي كان صادق فيها من كل قلبه ❤️.\nبالنسبه لأسلوبه، هو فعلًا نفس اسلوب شيباننا تقريبًا، ما يحبون أحد يصحح لهم أو شيء زي كذا.\nجدًا فخور إني درست عنده 🌹.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1480046-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-saifullah/68675/48", "user": "Abu_Khald", "ts": 1505132245000, "tid": 68675, "pn": 48}}]}', 1505132245000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abood_alem-math001', 'stk-abood_alem', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f80396", "n": "Dr. I Naji", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math001 ترم 151\n\nالتحضير:\n\nيحضر يوميًا في آخر الكلاس.\nالتأخير عنده اذا جيت ومرت 10 دقايق من بداية الكلاس, اما لو جيب قبل عادي.\n\nطريقة الشرح :\n\nيشرح من النوت حقه. نوته رهيب ومرتب جدًا وبعض الأمثلة فيه تكون من اولد اقزامز.\nطريقة شرحه ممتازة ويفهمك الكونسبت مزبوط.\nمتجاوب جدًا لأسئلة الطلاب وما عنده مشكله يعيد النقطه الف مره لكن المهم ان الطالب يفهم.\n\nالصوت:\n\nصوته واضح جدًا والأكسنت حقه ممتاز ماشاء الله.\n\nالكويزات :\n\nأعطانا 5 كويزات. كويزاته تميل للصعوبة اكثر. نصيحة تدرب على اسألة النوت والأولد اقزامز والريسايتيشن.\n\nالمياجر:\n\nكومن\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\n\n+A وقليله بحقه\n\nإضافات :\nإذا نزلت عند هذا الدكتور بالأوريا فأنت مع احسن دكتور ماث 🤠\nالدكتور متعاون مع الطلاب ودفنا بونس 3 درجات نهاية السمستر بالكلاس وورك.\n\nاتمنى افدتكم. بالتوفيق 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437774-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/i-naji/80396/47", "user": "Abood_Alem", "ts": 1451749125000, "tid": 80396, "pn": 47}}]}', 1451749125000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11966-math001', 'stk-user11966', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f80396", "n": "Dr. I Naji", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني math 001-191,math 002-192\n\nالتحضير:شديد فيه،ومايقبل ميك أب.\nطريقة الشرح:يشرح النوته حقته بإستخدام البروجكتر،والشيء الحلو أيضا أنه يشبك جهازه اللوحي في البروجكتر فيكتب على السبورة وهو بعيد عنها ومافيه أحد من الطلاب تتغطى عليه السبورة.\n\nالكويزات:سهلة بشكل عام،وأحيانا متوسطة.\nالصوت:كلامه مفهوم جدا،والأكسنت حقه واضح.\n\nإضافات:الدكتور شرحه جميل جدا،ويتقبل الأسئلة في الأوفس أورز بصدر رحب.\nالقريد النهائي: A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525114-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/i-naji/80396/57", "user": "user11966", "ts": 1598467939000, "tid": 80396, "pn": 57}}]}', 1598467939000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_legend1-math001', 'stk-the_legend1', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f82373", "n": "Dr. A Elghanmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 001 ,002 ترم 101 و 102\nالتحضير : سهالات وما يركز على التاخير\nطريقة الشرح : اسوا ما تتخيل اذا كنت تعتمد على مدرس يفهمك ما انصح فيه لكن بالنسبة للطلاب اللي يحضروا الدرس قبل لا يجوا المحاضرة فهو كويس وميزته انه يحل اسئلة مياجر تقريبا كل ما يخلص الشابتر ويحل الريستاتيشن بس نصيحة لوجه الله لا تعتمد على حله لانه فيه الكثير والكثير من الاخطاء\nالكويزات :متوسطة الى صعبة\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: D+\nالصوت: واضح\nإضافات : If you don,t bractise you will get zero كلمة يقولها بالكلاس مليون مرة لا وعليه zero يعرفونها اللي درسوا معاه\nصراحة المدرس هذا طيب جدا لكن مرااات ينكبك بالكلاس وورك عشان مياجرك نازلة\n…\n__________________", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p883286-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-elghanmi/82373/20", "user": "THE_LEGEND1", "ts": 1312995779000, "tid": 82373, "pn": 20}}]}', 1312995779000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10387-math001', 'stk-user10387', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f82373", "n": "Dr. A Elghanmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : يحضر بالسيريال نمبر ، وبعد التحضير يعد الطلاب عشان يتأكد إن مافي أحد حضر خويه.\n\nطريقة الشرح : انسان جبار في الشرح ، يبين ولك وين الأخطاء اللي يقع فيها الطلاب في العادة ، يشرح من سلايدات ، يشرح جميع الأسئلة اللي ممكن تجيك في الميجر\n\nالكويزات :الكويزات من متوسط إلى صعب مع ملاحظة إن يقلل الوقت ، فمثلا السؤال يحتاج حله 5 دقايق يعطيك دقيقتين ونص.\n\nالكلاس تست : عبارة عن ميجر مصغَّر والوقت كافي بس مستحيل يكون الكلاس تست في وقت الحصة ، غالبا يكون يوم الخميس في الليل بعد صلاة العشا 😃\n\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: A+\n\nالصوت: واضح + أكسنت رهيب 😃\n\nإضافات :\n\n1- دائما يحل أولد اقزامز قبل المياجر والفاينل\n2- يحب ينكت كثير\n3- أخذت عنده math001 وطلعت بA وأخذت عنده Math002 وطلعت بB ومع ذلك لا زلت مقتنع باإنه من أفضل الدكاترة\n4- أبدا ما تحتاج تكتب معاه نوت ، بس عليك انك تحضر وتفهم وبتحل بكل سهولة في الكويزات والكلاس تست", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1424726-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-elghanmi/82373/33", "user": "user10387", "ts": 1440072673000, "tid": 82373, "pn": 33}}]}', 1440072673000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ekko-math001', 'stk-ekko', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f82373", "n": "Dr. A Elghanmi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 001 - 161\n\nدكتور طيب جدًا؛ وكلاساته مرحه ويحب يمزح ويضحك مع طلابه\nالتحضير ببداية الكلاس وبعدها يعد الطلاب\n\nبشكل عام المقرر كان سهل جدًا وشرحه كان عادي ويرد على اسئله الطلاب ويحب اللي يناقشه\n\nاعتقد لو عنده مذكره بدل مايشرح من سلايدات الكتاب احسن بس طبعًا هالشيء مايأثر كثير “بس للبعض عشان لايضيع لما يذاكر”\n\nيركز كثير على حل الاولد اقزام قبل المياجر والفاينلات ويحل كثير منها مع الطلاب؛ متساعد بالدرجات للي يستاهل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474427-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-elghanmi/82373/41", "user": "Ekko", "ts": 1496458769000, "tid": 82373, "pn": 41}}]}', 1496458769000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-majed.q-math001', 'stk-majed.q', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-m118561", "n": "Dr. Mohammad Algharabli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term:151, Math-001,\n\nالتحضير :\nالتحضير آخر الكلاس، وما يدقق، ويراعي ظروف الطلاب بشكل جيد.\nطريقة الشرح :\nالشرح كان سيء بالنسبة لي؛ لأنه بارد نوعًا ما، ويسبب النعاس احيانًا.\nلغته الانجليزية ممتازة. ويتسبب بأخطاء احيانًا في النوتات وفي السبورة بعض الاحيان.\nالكويزات :\nالكويزات صعبة.\nالمياجر:\nكومون\nالفاينلات :\nكومون\nالقريد النهائي:\nC+\nالصوت:\nيحتاج يرفع صوته أكثر ليجذب انتباه الطلاب.\nإضافات :\nإذا كان يدرّسك، احرص على التواجد في الصفوف الأمامية؛ عشان ما يتشتت انتباهك بسرعة.\n\nوبالتوفيق للجميع ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1453550-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-algharabli/118561/14", "user": "Majed.Q", "ts": 1468252118000, "tid": 118561, "pn": 14}}]}', 1468252118000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10843-math001', 'stk-user10843', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-m118561", "n": "Dr. Mohammad Algharabli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term:161, MATH 001\n\nالتحضير :\nاول اسبوعين كان يعطينا ورقة ونحضّر عشان نحفظ الارقام ، بعدين صار يحضّر نهاية المحاضرة بالارقام … متساهل بالتحضير ويحضّرك لو تجي قبل النهاية بدقيقة.\n\nطريقة الشرح :\nيكتب القوانين عالسبورة ويبدا يشرح فكرة الدرس ثم يطبق على الامثلة و دايم يقولنا بتفهمون اكثر اذا بدينا نحل امثلة … ويتدرج في صعوبة الامثلة لين في النهاية يعطيك سؤالين اولد اكزام … طريقته جدا جدا ممتازة ومستحل تطفش من المحاضرة ودايما يقعد يناقشنا بالمسألة ويصير الكلاس ممتع … و يرّحب بأي سؤال ومستعد يشرح لك اكثر من مرة عشان تفهم الفكرة … طبعا شرحه من النوتة ويرسلها بالبلاكبورد … نوتته جدا ممتازة.\n\nالكويزات:\nعطانا ٥ كويزات ويحدد موعدها بالتشاور معنا … ماعنده مشكلة يأجل الكويز يومين مثلا لو فيه تعارض مع اختبار انجليزي \" سواها مرتين معانا \". كويزاته متوسطة الصعوبة ويعطيك درسين ثلاثة مع بعض ويحطها وقت المحاضرة كاملة … دايما يحط لنا سؤال نسخ لصق من نوتته.\n\nالصوت:\nصوته جدا واضح … لغته جيدة ويحاول يستخدم لغة بسيطة وماعنده مشكلة يشرح لك بالعربي … بس احيانا يهنّق شوّي في ترجمة المصطلحات للعربية 😆\n\nاضافات:\nالدكتور محمد الغرابلي يعلمك معنى الاخلاق النبيلة قبل مايعلمك الرياضيات … يعامل الطلاب كأنهم ذوي فضل عليه … اذا رحت له بالاوفس اورز ماراح يقصر معاك … وبالنهاية ماقصّر وعطانا بونص … وعنده بونص للي مايغيب … اذا نزل لك شد حيلك معاه وابشر بالـ B+ و فوق.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467364-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-algharabli/118561/15", "user": "user10843", "ts": 1485866274000, "tid": 118561, "pn": 15}}]}', 1485866274000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-to_be_engineer-math001', 'stk-to_be_engineer', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-m118569", "n": "Dr. Ahmad Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(Math 001 (162\nالتحضير : اول خمس دقايق وكان يسمح بالتاخير الا اذا شاف الطالب نفسه يتأخر كثير يعيطه كلمتين حلوة قدام الطلاب.\nطريقة الشرح :الشرح بسلايدات لكنه من الكتاب… اللي يميز السلايدات انه كان يحط في نهايتها اسئلة الريسايتيشن واولد اقزام مرتب لاخر خمس سنوات فتاخذ فكرة عن الاسئلة وتتدرب…\nشرح الدكتور كان واضح مو اسطوري لكن يفي بالغرض + اي سؤال مستعد انه يجاوب عليك بدون تردد.\nالكويزات :متوسطة … اذا فهمت الريساتيشن زين وحليت بعض اسئلة الاولد اقزام قبل الكويز اضمن لك الكلاس ورك في الجيب.\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:ِ A\nالصوت:واضح\nإضافات : الدكتور كان بمثابة الاب… اخلاق بكل ما تعنيه الكلمة… ما حضرت كلاس يخلو من النصائح، بعد الميجر الثاني كثير من الطلاب تحسن ادائهم قام شكرهم بالاسم و وزع على كل الكلاس حلويات.\nالله يوفقك يا دكتور احمد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492691-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-ahmad/118569/13", "user": "To_Be_Engineer", "ts": 1526672775000, "tid": 118569, "pn": 13}}]}', 1526672775000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mjs-math001', 'stk-mjs', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-m118572", "n": "Dr. Adel Moham Al-Mahdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math001-Term181\nالتحضير : يحضر بداية الكلاس وأحيانا ما يحضر ومرن في الميك اب\nالشرح : عشرة على عشرة والنوتة حقته شاملة وفيها أولد اكزام\nالكويزات : متوسطة إلى صعبة وفيه بونص في الكلاس وورك\nالصوت : واضح\nالمياجر والفاينلات : كومن\nالقريد النهائي : A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504567-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-moham-al-mahdi/118572/9", "user": "MJS", "ts": 1546764157000, "tid": 118572, "pn": 9}}]}', 1546764157000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-zeroal-math001', 'stk-zeroal', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-m118572", "n": "Dr. Adel Moham Al-Mahdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math001-Term201 (Online)\nالتحضير :اخر الدرس واذا شاف العدد كامل مايحضر.\nطريقة الشرح :اسطورية, اذا ركزت معه غصبا عليك تفهم احرص انك ما تلهى وقت الشرح وبتختصر وقت كثييير. وقت الميجرات والفاينال كنت اراجع النوتات وبعدها الاولد اكزام اللي ينزلها بالبلاك بورد و اجيب درجة حلوة (اذا كان عندك وقت راجع الاولد اللي ينزلها شرقاوي غالبا اسئلته تكون صعبة بس ماهي ضرورية).\nالكويزات : بالبداية كانت سهلة بعدين صعبها.\nالقريد النهائي ,:A+ واذا فيه اكثر عطينه\nالصوت:واضح\nإضافات : اذا كنت عنده فاحمد ربك بإذن الله بتطلع بقريد يرضيك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529029-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-moham-al-mahdi/118572/14", "user": "zeroal", "ts": 1615748003000, "tid": 118572, "pn": 14}}]}', 1615748003000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-raks-math001', 'stk-raks', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-m172443", "n": "Dr. Rachid Marsli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "151- math001\nالتحضير : اول السمستر كان ما يحضر لاكن عقب شاف طلاب ما يحضرون فبدأ يركز على الحضور\nطريقة الشرح : شرحه من أمثله الكتاب , وقت قرب المياجر يفتح اولد اقزام المحلوله ويشرحها , طبعا كان يحل الرستيشن حل باليد وينزلها بالبلاك بورد لاكن كان عنده أخطاء .\nالكويزات : نفس أمثله الكتاب , لاكن اذا قال نفس أفكار أولد اقزام بيجيب نفسها وبالأرقام بس بدون خيارات , أذكر مره كلاس تيست جاب من أسلئله أولد وغير من السؤال الارقام وصاره المساله طويله مره يعني حطه بدون ما يتأكد وانكبنا بس مشانه فيه .\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي: B+\nالصوت: واضح لاكن اللغه العربيه شوي رايحه فيها\nإضافات :\nالدكتور جيد لاكن لانه اول سنه له ما بعد أخذ على جامعه شي يبيله وقت , بس ابصم بالعشره لو سواله نوتات واشتغل صح بيكون اسطوري والمدرس حبيب ولو عندك عذر بغياب او بتسافر يمشيك .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1444722-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rachid-marsli/172443/3", "user": "raks", "ts": 1458723629000, "tid": 172443, "pn": 3}}]}', 1458723629000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alshehri015-math001', 'stk-alshehri015', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-m172443", "n": "Dr. Rachid Marsli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم …\nانا درست عند المدرس ذا الاوريا كلها\nMath 001 - Math 002\nعشان ما نبخس حق المدرس … المدرس له ايجابيات و سلبيات و تختلف من طالب لطالب\nبالنسبة للطالب اللي اساسه قوي في الماث او يعتمد عالسيلف ستدي بينبسط عند المدرس ذا من ناحيتين\n\nالاولى التحضير … يمديك تخلي اي واحد يحضرك لان التحضير بالارقام و تقول يس اذا جا رقمك فكلم واحد من الشباب و خله يقول يس اذا نادى برقمك ، اذكر في طلاب ما كنت اشوفهم الا وقت الكويزات و اذا سالته يقول انا معكم بالسكشن بس ما احضر\nالثانية … اختباراته جدا سهلة و يمديك تجيب فيها هي و الكلاس وورك رقم عالي جدا\n\nاما الطلاب اللي على قدهم او يحتاج الى مدرس يحفزه و يخليه يشارك معه و متفاعل او مدرس شرررريح زي ابو جيا و ناجي بيتعب مع جدا مع رشيد …\n\nبعطيكم الزبدة الحين دامي درست عنده سنة كاملة\nالمدرس حبيب حبيب جدا لابعد درجة و وده يساعدك و يعطيك كل شي يقدر عليه و يشرح لك و يحاول … لكن للاسف شرحه جدا جدا بدائي و سيء مع انه يبذل قصارى جهده و تحسه يتعب لكن للاسف بدون نتيجة و تطلع من الكلاس زي ما دخلت ، فماا لك الا السيلف ستدي\n\nنجي للنقطة اللي يتميز فيها :\nالمدرس اسطوري من ناحية الكلاس وورك … و يقعد يزود في درجات الطلاب لين ما السستم يعلق او يقوله ما تقدر تزود\nفيقوم يدخل لكل طالب 0.5 عشان يقبلها الموقع و تصير كأنها درجة كاملة لان الكلاس وورك دايما يتقرب الى عدد صحيح\nو بالنسبة للطلاب اللي على الحافة في الفاينل ( اللي يحتاجون بين 18 الى 24 عشان ينجحون ) يقوم يزودهم اكثر من الباقين و للامانة كذا واحد اعرفه و نجحو ب60 و كانو شوي و يحبون راسه و هم طول الترم يسبونه\n\nو المعذرة اني طولت لكن شفت ما في تعليقات كثيرة في الموضوع و حبيت افيد الاوريات القادمة اللي جايين وش طبيعة المدرس و وضعه بالتفصيل … و شكرا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1472575-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rachid-marsli/172443/5", "user": "Alshehri015", "ts": 1494014616000, "tid": 172443, "pn": 5}}]}', 1494014616000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-king_a7md-math001', 'stk-king_a7md', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-m172443", "n": "Dr. Rachid Marsli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 001-171\nالتحضير : ينادي كل واحد برقمه ودايما يحضر، ما يدقق على التأخير، يسمح بحضورك في سكشن ثاني\nطريقة الشرح : يشرح من السلايدات والريسايتيشن ويكتب على السبورة، شرحه مو سيء جدا مثل ما بعض الاخوة صوروه، اشوفه متوسط\nالكويزات : اصعب من اولد اكزام بس حلو عشان يعودك للميجر\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B+\nالصوت: صوته واضح ويتكلم مرات عربي ومرات انجليزي\nإضافات : الدكتور هذا طيب جدا جدا ومحترم، ودائما يتساعد مع الطلاب ويحاول يوصل المعلومة، في الكلاس وورك حذف اسوء كلاس تيست واسوء كويزين وكان في مجال للزيادة وزودنا درجة اضافية، كنت احضر احد الايام في سكشن ثاني وكان متفاهم جدا وما اعترض، ما يدقق على التأخير واجد اهم شي تحضر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485085-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rachid-marsli/172443/9", "user": "KiNG_A7MD", "ts": 1514322585000, "tid": 172443, "pn": 9}}]}', 1514322585000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rs83-math001', 'stk-rs83', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-m172443", "n": "Dr. Rachid Marsli", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 001 T221\nالتحضير: بالسيريال كان والصراحة متساهل ولا يهتم كثير بالتحضير. تجي متاخر يسامح عادي.\n\nالشرح: انا الصراحة كنت معتمد على شرحه ١٠٠٪؜ ومرتاااااح معه مرة افهم بالكلاس ارجع البيت احل اولد اقزامس وخلاص. وجبت درجة حلوة بدون ما اذاكر للفاينل ولا دقيقة. كان يشرح من اولدات مختصرة جدًا تشرح الكونسبت بس وفيها كم سؤال عشان يطبق اللي انشرح. ومرات يشوف افكار مهمة بالاولدات ويحلها بالكلاس ويقول الاخطاء اللي الطلاب يرتكبونها بالعادة. لهجته مغربية مرات يشرح عربي ومرات يشرح انقلش مكس.\n\nالكويزات: كويزاته صعبة الصراحة لكن تصحيحه ممتاز يعني تطلع من الاختبار تحس انك بتجيب ٢/٨ فجاة تلقاه معطيك ٥ من ٨ والغريب انه الافرج طايح. اذا تترك سؤال فاضي حرفيًا يعطيك ٠.٥ واذا كتبت خرابيط عطاك ١ بالسؤال يعطي كل طالب اكثر من حقه الصراحة.\n\nالقريد النهائي A+++++\n\nاضافات: والله دكتور حليل وطيب ويحاول يفيد الطالب ويعطي كل ما عنده الرجال يسوي ساعات مكتبية قبل كل كويز اونلاين غير ساعاته المكتبية الاصلية. ومتساهل بكل شيء التحضير وبالميك اب كان اسطورة الصراحة. ويحذف بالنهاية اسوء كويز واسوء كلاس تيست. ويعطيك الخيار انك تنسحب من كويز واحد وكلاس تيست لكن ما رح يحذف اسوء كويز. يا تنسحب يا تجرب حظك واذا جبت العيد حذفه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536523-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rachid-marsli/172443/19", "user": "RS83", "ts": 1679918280000, "tid": 172443, "pn": 19}}]}', 1679918280000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar-12232-math001', 'stk-omar-12232', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-m172448", "n": "Dr. Shadi Moham Alomari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده Math 001 بترم 201 عن بعد\n\nالتحضير : اوتوماتيكي ويقول للطلاب يرفعو يدهم بأوقات عشوائية واللي ما يرفع غايب.\n\nطريقة الشرح : يقرا القوانين و الكونسيبت ويشرحها ويحل مسائل عليها.\n\nالكويزات : صعببببببة نااااااار.\n\nالقريد النهائي: A\n\nالصوت: واضح ويتكلم شوي عربي وشوي انجليزي.\n\nإضافات : شرحه ممتاز ومن قلب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529588-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shadi-moham-alomari/172448/10", "user": "Omar-12232", "ts": 1619089411000, "tid": 172448, "pn": 10}}]}', 1619089411000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nawaf_ag-math001', 'stk-nawaf_ag', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-m172448", "n": "Dr. Shadi Moham Alomari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 001 - TERM 211\nالتحضير :\nكان مرن بالتحضير يعني لك إلى 10 دقايق وعادي ما يحطك متأخر بس عاد اذا الواحد زودها يبدأ يكون شديد معه\n\nطريقة الشرح :\nيشرح بأستخدام One Note وعنده نوتاته الخاصة فيه، وهي الصدق أعتبرها كنز حتى لو ما تدرس عنده لأنه مختصر لك فيها كل شي ومجمع لك كل شي من شرح للدرس وأسئلة الرستيشن وأولدات خاصة بكل درس وتنقسم نوعين شي بطريقة الحل وشي بس الجواب النهائي (بأختصار ما احتجت لأي مصدر ثاني نهائيًا غير نوتاته)\n\nالكويزات : صعبة، ومن أول يوم قال أنا بقرصكم في الكويزات لكن لمصلحتكم ومن هالكلام وهي غالباً ماتزيد عن 4 أسئلة وتكون في درسين أو 3 دروس بالكثير وكثير أحياناً يجيب أفكار من الأولدات اللي يحطها في One Note\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A ويستاهل أكثر لكن كويزاته بالنسبة لي ما تشفع له\n\nالصوت: واضح ويتكلم عربي كثير لو أحتاج يوضح نقطة مهمة\n\nإضافات :\n- الدكتور أسطورة بالشرح لدرجة أني ترم كامل ما أحتجت لأي مصدر للفهم مجرد بس أني اركز بالمحاضرة خلاص أموري طيبة\n- أخر الترم عطانا بونص لكن أعتقد ملزم يعطينا ويخلي أفرج الكلاس ورك زي المياجر\n- إذا لقيت أنك مع دكتور شادي ألف مبروك الصراحة بتستمتع في الكورس بس شد حيلك بالكويزات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533483-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shadi-moham-alomari/172448/13", "user": "NAWAF_AG", "ts": 1642266609000, "tid": 172448, "pn": 13}}]}', 1642266609000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-someone33-math001', 'stk-someone33', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-m172448", "n": "Dr. Shadi Moham Alomari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "From Telegram\nTerm211&212- Math001&002 (درست عنده الترمين)\n\nالتحضير: الغياب يغيب طبعًا أما التأخير بالمجمل شديد ويحضر أول الكلاس، الترم الأول جدًا شديد عالدقيقة والترم الثاني كان متساهل نوعًا ما … يعطيك فرصة كم مرة بعدها خلاص ولو تكلمه يمشي بس بيعرف وجهك.\nطريقة الشرح: جدًا ممتاز وواضح وسلس ويبدأ من السهل للصعب\nالكويزات: الترم الأول نار الهشيم (هو بنفسه يقول أنها كانت صعبة) أما الترم الثاني (212) قال بخليها آفرج زي الميجر وكانت بسيطة\nالصوت: واضح جدًا وطبيعي\nإضافات: الدكتور محترم ومؤدب وشرحه ممتاز وشديد عالتأخير بس يعذرك المرات الأولى.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535029-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shadi-moham-alomari/172448/14", "user": "SomeOne33", "ts": 1660606441000, "tid": 172448, "pn": 14}}]}', 1660606441000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_ghost2-math001', 'stk-the_ghost2', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-m172448", "n": "Dr. Shadi Moham Alomari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 001 - Term 211\nالتحضير : يمشي شوي بس بعدها يبدا على بعد مده معينه يتشدد\nطريقة الشرح : ون نوت ويعطيه للطلاب من بداية الترم وينزل فيه اولدات من شرحه\nالكويزات : كانت الموت وحتا لو سهل الكويز انت نفسياً بتحسه صعب اذكر الواحد يستانس لو جاب ٧\nالقريد النهائي: B\nالصوت:واضح لكن حاول تجلس قدام معه\nإضافات : الدكتور حبيب وسواليف لكن مايمشي بالدرجات والتصحيح و سمعت انه سهل الكوزات الترم الثاني", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536126-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shadi-moham-alomari/172448/15", "user": "The_Ghost2", "ts": 1673064182000, "tid": 172448, "pn": 15}}]}', 1673064182000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12277-math001', 'stk-user12277', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-m172448", "n": "Dr. Shadi Moham Alomari", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 001 Term 221\nالتحضير : يحضر بالسيريال نمبر، مرات يحضر في البداية ومرات في النهاية ومرات في النص.\n\nطريقة الشرح : يستخدم برنامج microsoft one note يضيفك فيه ويكون فيها نوتاته والريساتيشن والاولد اقزام وكل شي\nولو انت ما تدرس عنده تقدر تكلمه ويضيفك في البرنامج\n\nالكويزات : فيها تشابه من الاولد اقزام، فاذا ما حليت الاولادات بتكون صعبة.\n\nالمياجر: قبلها بفترة ينزل على البرنامج مياجر قديمة ويقول لك تدرب عليها، ويوم الميجر يخلي الاوفس اور في الكلاس وتكون مدتها اطول\n\nالفاينلات : ديبارتمنت\n\nالقريد النهائي: A، نقصت في الميجر والفاينل، اما الكلاس وورك كامل بعد البونس\n\nالصوت: واضح\n\nإضافات : الدكتور ما شاء الله اخلاق وتعامل وشرّيح ومرح، يا ليت في منه في كل مادة باخذها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536159-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/shadi-moham-alomari/172448/16", "user": "user12277", "ts": 1673656435000, "tid": 172448, "pn": 16}}]}', 1673656435000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ashen_one-math001', 'stk-ashen_one', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f176962", "n": "Dr. Ahmed Abdelrazec", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math001 term162\nالتحضير يكون باخر الكلاس دايما بس لاحظ ان بعض الطلاب يتاخرون عن الكلاس فصار يسجلهم ليت\nطريقة الشرح من السلايدات ويوضح الثيورم لو فيه ويكتب عالسبورة،شرحه جيد جدا بس لازم تذاكر اول باول\nالكويزات والكلاس تست موووووية ولا هو دقيق بالتصحيح مرة\nيحل الريسيتيشن ويرسله بالايميل،قبل المياجر والفاينل يحل معنا بارتات دكتور حسام الشرقاوي واحيانا يسوي كاهووت بونص لاعلى واحد تغيير جو عن الكلاس العادي\nافرج سكشنا كان طايح فما قدر يدفنا\nالدكتور اخلاق وحبيب بالاوفس\nتقييمي له A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1476887-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-abdelrazec/176962/2", "user": "Ashen_one", "ts": 1500473138000, "tid": 176962, "pn": 2}}]}', 1500473138000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah_mah-math001', 'stk-abdullah_mah', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f176966", "n": "Dr. Mohammad Awad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "161 math 001\n\nالتحضير : يوميا و احيانا يتساهل معا التاخير\n\nطريقة الشرح : سلايدات هو مسويها بنفسه , جدا جميلة و مفيدة وفيها امثلة و اسئلة تمارين\n\nالكويزات : كويزات محترمة تبين الفاهم من اللي مو فاهم . لكن تقدر تبدع اذا كنت شغال معاه صح\n\nالمياجر :كومن , لكن سوا لنا سلايدات ريفيو حق يوم الميجر جدددا جميلة و شاملة\n\nالفاينلات : نفس حكاية المياجر\n\nالقريد النهائي : A ! و بمرتبة الشرف\n\nالصوت : واضح ومفهوم , يتكلم عربي احيانا وحتى في الشرح\n\nاضافات : دفعتنا 161 مميزة , لانها على ما اعتقد اخر دفعة تدرس math 001 معاه .\nالاستاذ جدا مرح وحبوب و كلاسه مش ثقيل ابدا\nيستقبلك في الاوفس اور بكل رحب , ما يحب انك تجيه معا اسئلة بدون حل , كان يقول جيبوا اسئلتكم معا الحل حتى لو كان غلط .\nطلعت معاه بقريد A وبارك لي على هذا الانجاز\nو كتقدير مني له عطيته هدية كيستين تمر في نهاية الترم\n\nشكرا يا استاذ محمد , دمت في حفظ الرحمن", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1481108-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-awad/176966/6", "user": "Abdullah_MAH", "ts": 1506687321000, "tid": 176966, "pn": 6}}]}', 1506687321000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11372-math001', 'stk-user11372', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f176966", "n": "Dr. Mohammad Awad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(Math 001 (181\nالتحضير : خلال الكلاس يحضر , التأخير عنده اول 10 دقايق وبعدين غياب وحيانا يتساهل مع الطلاب لو تأخر دقيقة.\n\nطريقة الشرح : سلايداااته اسطورية والله والكل يعرف بهذا الكلام لو تذاكرها بس بتجيب فل في المياجر\nوشرح ولا اروع ويحب ينكتب خلال الكلاس والدكتور محب جداااا للرياضيات واله عنده اي سؤال روح اله الاوفيس ومابيقصر معك\n\nالكويزات : حرريققة ! نصيحة اله تبي تجيب 20/20 ذاكر قبلها بمدة لاتقل عن 5 ايام , معظم الاسئلة تجي من سلايداته بالكويزات نسق لصق من البراكتس\n\nالمياجر: كومن.\n\nالفاينلات : كومن.\n\nالقريد النهائي: A+\n\nالصوت: واضح ولا اروع\n\nإضافات : الدكتور اسطوووره وراح يجلد بالكويزات لكن نهاية السمستر اله اديتوا كويس في المياجر بيشوف افرجك السكشن وبيعطيكم بونص مو طبيعي\nواله تبي بونص انتبه تغيب عنده كثير وتراه دكتوووووووور ولا اروع اخلاق وشرح وسلايدات حرييققققة\nاذا حطوك عنده احمد ربك كثيررر واجتهد معه لان جهدك ما راح يروح عالفاضي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504116-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-awad/176966/8", "user": "user11372", "ts": 1545851953000, "tid": 176966, "pn": 8}}]}', 1545851953000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11763-math001', 'stk-user11763', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f176966", "n": "Dr. Mohammad Awad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت عنده math 001\n\nالتحضير : يومياَ وشديد جداً بالتاخير والغياب ، لو متاخر دقيقه راح يحطك ليت على طول\nطريقة الشرح : شرحه جداً جداً ممتاز وغالباً يعطيك اكثر من طريقه بسيطه للحل ، يستخدم سلايداته بالشرح واشوفها افضل ميزه فيه لان السلايدات حقته تغنيك عن كل شي حرفياً فيها الشرح واولد اقزامز وبراكتس اخر الدرس ل ٥ اساله وافكار صعبه تختبر فهمك للدرس\n\nالكويزات : صعبة جداً … لازم تذاكر لها زين لانها اصعب من المياجر بس بتخليك تتجهز زين للمياجر والفاينل (طبعاً يعطيك درجات على الخطوات)\n\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:A+++++ ياحظ اللي ياخذ عنده\nالصوت: واضح جداً ويتكلم عربي احياناً\n\nإضافات : الدكتور جداً ممتع وفاهم ويقدر يوصلك المعلومه بسرعه، يهتم بالمتفوقين … اتذكر بدايه الكورس كنت جداً خايف وجبت العيد باغلب كوزاته والميجر الاول بعد جبت فيه درجه سيئه\nالميجر الثاني حاولت اهتم واذاكر زين وجبت ٢٠ ف بعدها عرفني وصار يساعدني بكل شي واعطاني درجات المشاركه والكوزات كامله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1524898-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-awad/176966/11", "user": "user11763", "ts": 1598095755000, "tid": 176966, "pn": 11}}]}', 1598095755000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tweiti-math001', 'stk-tweiti', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-f176966", "n": "Dr. Mohammad Awad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math001-201\nاونلاين\nالشرح : بداية الترم كنا على بلاك بورد محاضرتين ثم حولنا على التيمز يشارك السلايدات على التيمز و يبدأ يشرح و ينزل السلايدات نهاية اليوم على البلاك ما يقصر معك في الاوفيس اور ويسوي ملفات اسئلة قبل الاختبارات (التيست و الميد و الفاينل) و يعدي عليها قبل الاختبار اذا فيه شي ما فهمته اسآل الدكتور عنده قناة في اليوتيوب ينزل فيها المحاضرات و يشرح الاسئلة الي ينزلها.\nالتحضير: شديد و في البداية خلك مضبوط و راقب غياباتك مشكلة الاون لاين لو تهاون الدكتور البعض رح يفلت و هو ما يحب الغياب فرح يشد و يعطي DN انتبه و لا تنام في الكلاس بعد نص الترم الدكتور رح يكون عرف المجتهدين و يكون يعرف راعي الغيابات و اذا صارت لك مشكلة في الحضور رح يزبطك لكن في البداية انتبه ما يمشي.\nالكويزات: ذاكر لها. الكويز لازم ترسله قبل لا تنتهي المحاضرة ولا مرح يصححه.\nنقطة ارسال الكويز اذا كنت مشارك و مجتهد رح يمشي لك دقيقة بس في البداية رح يكون شاد .\nالصوت: واضح جدا.\nالقريد النهائي: A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527801-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-awad/176966/12", "user": "Tweiti", "ts": 1610371868000, "tid": 176966, "pn": 12}}]}', 1610371868000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-14-msan-math001', 'stk-14-msan', 'MATH 001', 'doc', '{"docs": [{"id": "stk-dr-m182904", "n": "Dr. Muhammad Imran Qureshi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nMath001 online term 201\nالتحضير : نهاية كل محاضرة يقول الأسماء BB\nطريقة الشرح : onenote مسأل حالهم قبل المحاضرة يشرح عليهم الدكتور طيب ويجاوب على أي سؤال حتى لو سخيف\nالكويزات : سهل إلى متوسطة الأغلب سهل\nالمياجر: common\nالفاينلات :common\nالقريد النهائي: A\nالصوت: أول ماتتعود عليه بتفهم طبعا انا خذت أسبوعين عشان افهم معنى (سكير ) طلع يعني square\nإضافات : اي سؤال ترسله على الايميل يحله لك في أسرع وقت وحتى لو تبي تتأكد من حلك لسؤال ارسل له عادي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529209-math001", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-imran-qureshi/182904/9", "user": "14-Msan", "ts": 1616669195000, "tid": 182904, "pn": 9}}]}', 1616669195000, 1794837145, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
